// ---- Machines on a new slip -------------------------------------------------
// Held here rather than read back off the form. Details are entered on a popup
// and only land in this list once "Add" is pressed, so a half-typed machine
// cannot be left sitting on the page and registered by accident.
let nsMachines = [];      // [{ model, qty, serial, remarks }]
let nsEditIndex = -1;     // -1 = adding, otherwise the entry being edited

function renderNsMachines() {
  const wrap = $("ns-machines");
  if (!nsMachines.length) {
    wrap.innerHTML = `<p class="ns-machines-empty">No machines added yet.</p>`;
    return;
  }
  wrap.innerHTML = nsMachines.map((m, i) => `
    <div class="ns-machine-card" data-i="${i}">
      <div class="ns-machine-main">
        <span class="ns-machine-model">${escapeHtml(m.model)}</span>
        ${m.qty > 1 ? `<span class="ns-machine-qty-tag">&times;${m.qty}</span>` : ""}
        ${m.serial ? `<span class="ns-machine-serial">S/N ${escapeHtml(m.serial)}</span>` : ""}
        ${m.remarks ? `<span class="ns-machine-remarks">${escapeHtml(m.remarks)}</span>` : ""}
        ${m.quote ? `<span class="ns-machine-quote">Quote first</span>` : ""}
      </div>
      <div class="ns-machine-acts">
        <button type="button" class="ns-machine-edit" data-i="${i}" aria-label="Edit machine">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M3 17.5 17.5 3a2.1 2.1 0 0 1 3 3L6 20.5 2 21z"/></svg>
        </button>
        <button type="button" class="ns-machine-del" data-i="${i}" aria-label="Remove machine">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M18 6 6 18M6 6l12 12"/></svg>
        </button>
      </div>
    </div>`).join("");
  wrap.querySelectorAll(".ns-machine-edit").forEach((b) =>
    b.addEventListener("click", () => openMachineForm(Number(b.dataset.i))));
  wrap.querySelectorAll(".ns-machine-del").forEach((b) =>
    b.addEventListener("click", () => {
      nsMachines.splice(Number(b.dataset.i), 1);
      renderNsMachines();
    }));
}

// What a machine is called, and the row that offers it.
//
// The SHORT NAME is what gets recorded, so it is what the slip, the printed
// copy and the Sales Order all end up saying - see machine-names.js. The full
// AutoCount description stays on screen underneath it, because the short name
// is for reading a list quickly and the long one is for being sure it is the
// right machine before committing to it.
function machineShortName(r) {
  return (window.MACHINE_NAMES && window.MACHINE_NAMES.shortNameFor(r.item_code, r.description))
    || r.description || r.item_code;
}

function machineOptionHtml(r) {
  const short = machineShortName(r);
  // Only worth repeating the description when it says something the short name
  // does not, which for a machine with no override it usually does.
  const full = r.description && r.description !== short ? r.description : "";
  return `<button type="button" class="company-option" data-code="${escapeAttr(r.item_code)}" data-desc="${escapeAttr(short)}">
      <span class="fp-opt-desc">${escapeHtml(short)}${
        r.desc2 ? ` <span class="fp-opt-model">· ${escapeHtml(r.desc2)}</span>` : ""}</span>
      <span class="fp-opt-code mono">${escapeHtml(r.item_code)}</span>
      ${full ? `<span class="ns-opt-full">${escapeHtml(full)}</span>` : ""}
    </button>`;
}

// ---- Picking the machine from the catalogue ---------------------------------
// Machine units in AutoCount carry a U-prefixed item code (UHUQ, UZEN, UPUL);
// spares do not, which is what keeps this list to machines.
//
// The code is REMEMBERED as well as the wording. That is what lets the app know
// a machine is a fogger rather than guessing it from however the counter
// happened to word it - and it is why typing over the box has to drop the pick:
// the text on screen is what gets recorded, so a stale code behind it would be
// a machine claiming to be something it is not.
let nsmPickedCode = "";      // the AutoCount item behind the typed model, if any

function setPickedModel(code) {
  nsmPickedCode = String(code || "");
  const row = $("nsm-model-picked");
  if (!row) return;
  if (nsmPickedCode) {
    $("nsm-model-code").textContent = nsmPickedCode;
    row.style.display = "flex";
  } else {
    row.style.display = "none";
  }
}

let nsmModelDebounce = null;
function wireModelSearch() {
  const input = $("nsm-model");
  const box = $("nsm-model-results");
  if (!input || !box) return;

  input.addEventListener("input", () => {
    // Anything typed by hand means this is no longer the catalogue machine.
    setPickedModel("");
    clearTimeout(nsmModelDebounce);
    const q = input.value.trim();
    if (q.length < 2) { box.innerHTML = ""; return; }
    nsmModelDebounce = setTimeout(async () => {
      try {
        const data = await api(`/api/machine-search?q=${encodeURIComponent(q)}`);
        const list = data.results || [];
        // No message when there is nothing: the field takes free text by
        // design, and "no matching machines" reads like a refusal when the
        // machine simply is not one of ours.
        if (!list.length) { box.innerHTML = ""; return; }
        box.innerHTML = list.map(machineOptionHtml).join("");
        box.querySelectorAll(".company-option").forEach((btn) =>
          btn.addEventListener("click", () => {
            input.value = btn.dataset.desc;
            setPickedModel(btn.dataset.code);
            box.innerHTML = "";
          })
        );
      } catch (_) { box.innerHTML = ""; }
    }, 250);
  });

  $("nsm-model-clear").addEventListener("click", () => {
    setPickedModel("");
    $("nsm-model").focus();
  });
}
wireModelSearch();

function openMachineForm(index = -1) {
  nsEditIndex = index;
  const m = index >= 0 ? nsMachines[index]
          : { model: "", qty: 1, serial: "", remarks: "", code: "" };
  $("nsm-model-results").innerHTML = "";
  setPickedModel(m.code || "");
  $("nsm-title").textContent = index >= 0 ? "Edit machine" : "Add machine";
  $("nsm-add").textContent = index >= 0 ? "Save" : "Add";
  $("nsm-model").value = m.model;
  $("nsm-qty").value = m.qty;
  $("nsm-serial").value = m.serial;
  $("nsm-remarks").value = m.remarks || "";
  $("nsm-status").innerHTML = "";
  nsmSerialHint();
  $("nsm-modal").style.display = "flex";
  document.body.style.overflow = "hidden";
  setTimeout(() => $("nsm-model").focus(), 50);
}

function closeMachineForm() {
  $("nsm-modal").style.display = "none";
  document.body.style.overflow = "";
  nsEditIndex = -1;
  $("nsm-model-results").innerHTML = "";
  setPickedModel("");
}

// Above one unit the serial box covers all of them, so say so rather than
// leaving someone to wonder which machine the number belongs to.
function nsmSerialHint() {
  const qty = Math.max(1, parseInt($("nsm-qty").value, 10) || 1);
  const hint = $("nsm-serial-hint");
  if (qty > 1) {
    hint.textContent = `This slip will list ${qty} separate machines. Anything typed here is recorded against all ${qty}.`;
    hint.style.display = "block";
  } else {
    hint.style.display = "none";
  }
}

function commitMachineForm() {
  const model = $("nsm-model").value.trim();
  if (!model) {
    $("nsm-status").innerHTML = statusErr("Model No. is required.");
    $("nsm-model").focus();
    return;
  }
  let qty = parseInt($("nsm-qty").value, 10);
  if (!Number.isFinite(qty) || qty < 1) qty = 1;
  const entry = {
    model, qty,
    // Only set when the model was chosen from the list and not typed over
    // since - see setPickedModel.
    code: nsmPickedCode,
    serial: $("nsm-serial").value.trim(),
    remarks: $("nsm-remarks").value.trim(),
  };
  if (nsEditIndex >= 0) nsMachines[nsEditIndex] = entry;
  else nsMachines.push(entry);
  closeMachineForm();
  renderNsMachines();
}

// Check & Service and Repair only are a choice between each other: "service
// everything, but do not service anything" is not a request anybody makes.
// Ticking one clears the other rather than refusing the second tap.
["ns-check-service", "ns-repair-only"].forEach((id, i, all) => {
  const box = $(id);
  if (!box) return;
  box.addEventListener("change", () => {
    if (!box.checked) return;
    const other = $(all[1 - i]);
    if (other) other.checked = false;
  });
});

function resetNewServiceForm() {
  ["ns-company", "ns-contact-name", "ns-contact-number", "ns-whatsapp", "ns-notes"].forEach((id) => ($(id).value = ""));
  const same = $("ns-whatsapp-same"); if (same) same.checked = true;
  const wa = $("ns-whatsapp"); if (wa) wa.setAttribute("disabled", "true");
  const created = $("ns-created"); if (created) { created.style.display = "none"; created.innerHTML = ""; }
  ["ns-check-service", "ns-repair-only", "ns-quote-first"].forEach((id) => {
    const b = $(id); if (b) b.checked = false;
  });
  nsMachines = [];
  renderNsMachines();
  $("ns-status").innerHTML = "";
  const sug = $("ns-company-suggest"); if (sug) sug.innerHTML = "";
  nsDebtorCode = "";
  sigPadClear();
  renderSigPreview();
}

async function submitNewService() {
  const company = $("ns-company").value.trim();

  // Expand each machine row by its quantity. A row with qty >= 2 becomes
  // separate entries suffixed " - n/total" (e.g. "BK3410 - 1/2", "BK3410 - 2/2").
  // A row with qty 1 stays as-is ("BK3410"). Each entry becomes its own machine.
  // A quantity above one becomes that many separate machines on the slip, so
  // each can be repaired, commented on and priced independently. The serial
  // typed once is carried onto all of them - John's call: staff can list
  // several numbers in the one box when it matters.
  const machines = [];
  for (const m of nsMachines) {
    if (m.qty === 1) {
      machines.push({ desc: m.model, machine_code: m.code || "", serial: m.serial, remarks: m.remarks || "" });
    } else {
      for (let n = 1; n <= m.qty; n++) {
        // Several of the same machine are the same catalogue item, so they all
        // carry the same code; only the "- 1/3" in the wording tells them apart.
        machines.push({ desc: `${m.model} - ${n}/${m.qty}`, machine_code: m.code || "", serial: m.serial, remarks: m.remarks || "" });
      }
    }
  }

  if (!company) { $("ns-status").innerHTML = statusErr("Company is required."); return; }
  if (machines.length === 0) { $("ns-status").innerHTML = statusErr("Add at least one machine."); return; }

  // The signature is the customer accepting the printed terms, so a slip
  // cannot be registered without it. Scroll it into view rather than just
  // complaining — it sits below the fold on most phones.
  const signature = sigPadData();
  if (!signature) {
    $("ns-status").innerHTML = statusErr("Ask the customer to sign before registering.");
    openSigModal();
    return;
  }

  $("ns-submit").disabled = true;
  $("ns-status").innerHTML = statusInfo("Registering…");
  try {
    const slip = await api("/api/slips", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        company,
        // No debtor picked from AutoCount means a walk-in, which bills to
        // Cash Sales rather than being guessed at from the typed name.
        debtor_code: nsDebtorCode || CASH_SALES_DEBTOR,
        contact_name: $("ns-contact-name").value.trim(),
        contact_number: $("ns-contact-number").value.trim(),
        whatsapp_number: $("ns-whatsapp").value.trim(),
        // Whoever is signed in on this phone took the machine in.
        created_by: userName(),
        check_service: $("ns-check-service").checked,
        repair_only: $("ns-repair-only").checked,
        quote_first: $("ns-quote-first").checked,
        notes: $("ns-notes").value.trim(),
        machines,
        signature,
      }),
    });
    toast(`Service slip ${slip.slip_number} created`, "ok");
    showSlipCreated(slip);
  } catch (e) {
    $("ns-status").innerHTML = statusErr(e.message);
  } finally {
    $("ns-submit").disabled = false;
  }
}

// After a slip is registered: show its number with Share (PDF) + Done actions.
function showSlipCreated(slip) {
  const panel = $("ns-created");
  if (!panel) { setTimeout(goHome, 1200); return; }
  panel.style.display = "block";
  panel.innerHTML = `
    <div class="created-card">
      <div class="created-check">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"><path d="M20 6 9 17l-5-5"/></svg>
      </div>
      <div class="created-title">Service slip ${escapeHtml(slip.slip_number)} created</div>
      <div class="created-sub">${escapeHtml(slip.company)} · ${slip.machines.length} machine(s)</div>
      ${contactActionHtml(slip)}
      <button class="btn-primary" id="ns-share" type="button" style="width:100%;margin-top:10px;">Share PDF</button>
      <button class="btn-secondary" id="ns-done" style="width:100%;margin-top:8px;">Done</button>
    </div>`;
  // Hide the form bits while the success card is up
  $("ns-status").innerHTML = "";
  $("ns-share").addEventListener("click", () => shareSlipPdf(slip));
  $("ns-done").addEventListener("click", goHome);
  wireContactActions(panel, slip);
  driveArchive(slip);
  window.scrollTo(0, 0);

  // Offered only when the server can actually send, so staff are never shown a
  // button that cannot work. Waiting on Meta approving the business account.
  whatsappStatus().then((wa) => {
    if (!wa.enabled || !wa.configured) return;
    const btn = document.createElement("button");
    btn.className = "btn-primary wa-send";
    btn.type = "button";
    btn.style.cssText = "width:100%;margin-top:8px;";
    btn.textContent = "Send to customer on WhatsApp";
    $("ns-share").insertAdjacentElement("beforebegin", btn);
    wireWhatsappButton(btn, slip, { auto: wa.auto_send });
  });
}

// ---- Service slip PDF ------------------------------------------------------
// The only part of OM Service a customer ever sees, so it is also where the
// terms live. Laid out at A4 in Helvetica (the only face jsPDF has built in).

// Terms & Conditions, as supplied by John (19 Aug 2026). Split into segments so
// the phrases he marked can be set bold mid-sentence. Wording is verbatim —
// do not reword these without asking; they are the terms customers sign against.
const SLIP_TERMS = [
  [
    { t: "Repaired equipment remaining unclaimed for a period exceeding " },
    { t: "Two Months (60 days)", b: true },
    { t: " may be disposed of at the sole discretion of Outboard & Marine Pte Ltd." },
  ],
  [
    { t: "Repair Assessment will be conducted free-of-charge. However, Outboard & Marine Pte Ltd will not be responsible for re-assembly of the assessed equipment should the client decide not to proceed with the repair. " },
    { t: "(Re-assembly surcharge of S$20.00 will be levied upon such request)", b: true },
  ],
  [
    { t: "Our standard Service & Repair package may include diagnosis & replacement of minor / peripheral components, etc. Repair duration would be less than 2 days." },
  ],
  [
    { t: "Our extended Services & Repair package may include cleaning, repair, and overhaul of key engine / product components and functional testing." },
  ],
  [
    { t: "Repair charges range from S$15.00 ~ S$80.00 (EXCLUDING Cost of spare parts & prevailing GST) " },
    { t: "NOT APPLICABLE", b: true },
    { t: " for Chipper Shredders. Vehicle mounted application equipment are subject to individualised quotation." },
  ],
  [
    { t: "The client agrees to proceed for repair without quotation if price does not exceed S$120.00 for all other equipment brands." },
  ],
];

// Lay out mixed normal/bold runs with word wrapping. jsPDF has no rich text, so
// each word is measured and placed individually. Pass draw=false to measure a
// block without rendering it — used to balance the two-column terms.
// Returns the final baseline y.
function pdfFlowRich(doc, segments, x, y, maxW, size, leading, draw = true) {
  doc.setFontSize(size);
  let cx = x;
  let cy = y;
  for (const seg of segments) {
    doc.setFont("helvetica", seg.b ? "bold" : "normal");
    for (const word of seg.t.split(/(\s+)/)) {
      if (!word) continue;
      const isSpace = !/\S/.test(word);
      const w = doc.getTextWidth(word);
      if (!isSpace && cx + w > x + maxW) {
        cy += leading;
        cx = x;
      }
      if (isSpace && cx === x) continue;   // never start a line with a space
      if (draw) doc.text(word, cx, cy);
      cx += w;
    }
  }
  return cy;
}

// Width a letterspaced string will actually occupy. jsPDF measures text with
// char spacing ignored, so anything that positions against a label's width has
// to add it back by hand.
function pdfSpacedWidth(doc, text, space) {
  return doc.getTextWidth(text) + space * Math.max(0, text.length - 1);
}

// Small letterspaced label, the workhorse of this layout. jsPDF's char spacing
// is global state, so it is always reset before returning.
//
// Right alignment is corrected manually for the same reason: jsPDF anchors on
// the unspaced width, so a right-aligned label overruns its anchor by the
// spacing and collides with whatever sits beside it.
function pdfLabel(doc, text, x, y, { size = 6.6, space = 1.6, grey = 150, bold = true, align } = {}) {
  doc.setFontSize(size);
  doc.setFont("helvetica", bold ? "bold" : "normal");
  doc.setTextColor(grey);
  if (align === "right") {
    doc.setCharSpace(space);
    doc.text(text, x - pdfSpacedWidth(doc, text, space), y);
    doc.setCharSpace(0);
    return;
  }
  doc.setCharSpace(space);
  doc.text(text, x, y, align ? { align } : undefined);
  doc.setCharSpace(0);
}

// Build the service-slip PDF (jsPDF) and return a Blob.
//
// Layout: hierarchy carried by type size, weight and letterspacing rather than
// boxes, with a single teal rule under the header as the only colour. The
// header is the leaf mark plus the company wordmark, with the address set as
// live text — which is also why the website line is correct here even though
// the old letterhead image had it wrong.
function buildSlipPdf(slip) {
  const { jsPDF } = window.jspdf;
  const doc = new jsPDF({ unit: "pt", format: "a4" });

  const LEFT = 48;
  const RIGHT = 547;
  const W = RIGHT - LEFT;
  const BOTTOM = 772;
  const TEAL = [13, 116, 122];
  const TEAL_TINT = [237, 246, 246];
  const BORDER = [219, 225, 227];
  const INK = 26;
  let y = 46;

  const setDraw = (c) => Array.isArray(c) ? doc.setDrawColor(c[0], c[1], c[2]) : doc.setDrawColor(c);
  const setFill = (c) => Array.isArray(c) ? doc.setFillColor(c[0], c[1], c[2]) : doc.setFillColor(c);
  const setText = (c) => Array.isArray(c) ? doc.setTextColor(c[0], c[1], c[2]) : doc.setTextColor(c);

  const need = (h) => {
    if (y + h <= BOTTOM) return false;
    doc.addPage();
    y = 54;
    return true;
  };

  // ---- Small outline icons -------------------------------------------------
  // jsPDF has no icon font, so these are drawn from primitives. Deliberately
  // simple: at 11pt anything more detailed turns to mush on a printed slip.
  function icon(name, ix, iy, s) {
    setDraw(TEAL); doc.setLineWidth(0.9);
    const m = s / 12;
    if (name === "calendar") {
      doc.roundedRect(ix, iy + 1.5 * m, 12 * m, 10 * m, 1.2 * m, 1.2 * m);
      doc.line(ix, iy + 4.5 * m, ix + 12 * m, iy + 4.5 * m);
      doc.line(ix + 3.5 * m, iy, ix + 3.5 * m, iy + 3 * m);
      doc.line(ix + 8.5 * m, iy, ix + 8.5 * m, iy + 3 * m);
    } else if (name === "building") {
      doc.rect(ix + 1 * m, iy, 10 * m, 11.5 * m);
      doc.line(ix + 3.6 * m, iy + 3 * m, ix + 5 * m, iy + 3 * m);
      doc.line(ix + 7 * m, iy + 3 * m, ix + 8.4 * m, iy + 3 * m);
      doc.line(ix + 3.6 * m, iy + 6 * m, ix + 5 * m, iy + 6 * m);
      doc.line(ix + 7 * m, iy + 6 * m, ix + 8.4 * m, iy + 6 * m);
      doc.line(ix + 5.2 * m, iy + 11.5 * m, ix + 5.2 * m, iy + 8.8 * m);
      doc.line(ix + 6.8 * m, iy + 11.5 * m, ix + 6.8 * m, iy + 8.8 * m);
      doc.line(ix + 5.2 * m, iy + 8.8 * m, ix + 6.8 * m, iy + 8.8 * m);
    } else if (name === "person") {
      doc.circle(ix + 6 * m, iy + 3.6 * m, 2.7 * m);
      doc.lines([[0, -3.2 * m], [1.7 * m, -1.9 * m], [4.6 * m, 0], [1.7 * m, 1.9 * m], [0, 3.2 * m]],
        ix + 1 * m, iy + 11.6 * m);
    } else if (name === "phone") {
      doc.roundedRect(ix + 2.6 * m, iy, 6.8 * m, 12 * m, 1.4 * m, 1.4 * m);
      doc.line(ix + 4.8 * m, iy + 1.8 * m, ix + 7.2 * m, iy + 1.8 * m);
      setFill(TEAL);
      doc.circle(ix + 6 * m, iy + 9.9 * m, 0.7 * m, "F");
    } else if (name === "gear") {
      // Six short, stubby teeth. Four long ones read as a snowflake.
      doc.circle(ix + 6 * m, iy + 6 * m, 3.6 * m);
      doc.circle(ix + 6 * m, iy + 6 * m, 1.5 * m);
      doc.setLineWidth(1.5);
      for (let i = 0; i < 6; i++) {
        const a = (Math.PI / 3) * i;
        doc.line(ix + 6 * m + Math.cos(a) * 3.6 * m, iy + 6 * m + Math.sin(a) * 3.6 * m,
                 ix + 6 * m + Math.cos(a) * 5.5 * m, iy + 6 * m + Math.sin(a) * 5.5 * m);
      }
      doc.setLineWidth(0.9);
    } else if (name === "clipboard") {
      doc.roundedRect(ix + 1 * m, iy + 1.6 * m, 10 * m, 10.4 * m, 1.2 * m, 1.2 * m);
      doc.roundedRect(ix + 4 * m, iy, 4 * m, 3 * m, 0.8 * m, 0.8 * m);
      doc.line(ix + 3.4 * m, iy + 6 * m, ix + 8.6 * m, iy + 6 * m);
      doc.line(ix + 3.4 * m, iy + 8.6 * m, ix + 7 * m, iy + 8.6 * m);
    } else if (name === "shield") {
      // The last segment closes the path back up the left edge. Without it the
      // shield ends at the bottom-left corner and its left side is simply
      // missing, which reads as the icon being clipped.
      doc.lines([[5 * m, -1.9 * m], [5 * m, 1.9 * m], [0, 4.8 * m], [-5 * m, 4.9 * m],
                 [-5 * m, -4.9 * m], [0, -4.8 * m]],
        ix + 1 * m, iy + 2.3 * m);
      doc.line(ix + 3.7 * m, iy + 6 * m, ix + 5.3 * m, iy + 7.7 * m);
      doc.line(ix + 5.3 * m, iy + 7.7 * m, ix + 8.5 * m, iy + 4.4 * m);
    } else if (name === "info") {
      doc.circle(ix + 6 * m, iy + 6 * m, 5.2 * m);
      setFill(TEAL);
      doc.circle(ix + 6 * m, iy + 3.5 * m, 0.75 * m, "F");
      doc.setLineWidth(1.1);
      doc.line(ix + 6 * m, iy + 5.5 * m, ix + 6 * m, iy + 8.8 * m);
    }
  }

  // A teal section heading with its icon, as on the printed copy.
  function sectionHead(label, ic) {
    icon(ic, LEFT, y - 8.5, 11);
    doc.setFontSize(9); doc.setFont("helvetica", "bold");
    setText(TEAL); doc.setCharSpace(0.9);
    doc.text(label, LEFT + 17, y);
    doc.setCharSpace(0);
    y += 12;
  }

  // ---- Header: mark + wordmark, address set as text ----
  const MARK = 46;
  let headBottom = y + MARK;
  try {
    doc.addImage(OM_MARK, "PNG", LEFT, y, MARK, MARK);
  } catch (_) { /* fall through to text below */ }
  try {
    const nameW = 208;
    const nameH = nameW / OM_NAMEBLOCK_RATIO;
    doc.addImage(OM_NAMEBLOCK, "PNG", LEFT + MARK + 13, y + (MARK - nameH) / 2, nameW, nameH);
  } catch (_) {
    doc.setFontSize(15); doc.setFont("helvetica", "bold"); setText(INK);
    doc.text("Outboard & Marine Pte Ltd", LEFT + MARK + 13, y + 28);
  }

  doc.setFontSize(6.9); doc.setFont("helvetica", "normal"); setText(105);
  const addr = [
    "9 Kaki Bukit Rd 1, #01-03, Eunos Technolink, Singapore 415938",
    "Tel (65) 6743 4039   ·   Fax (65) 6748 2031",
    "sales@omprotools.com.sg   ·   www.gardenequipment.com.sg",
    "GST M2-0009392-5   ·   Co. Reg. 196800629G",
  ];
  let ay = y + 11;
  addr.forEach((line) => { doc.text(line, RIGHT, ay, { align: "right" }); ay += 9.2; });
  headBottom = Math.max(headBottom, ay - 5);

  y = headBottom + 10;
  setDraw(TEAL); doc.setLineWidth(1.8);
  doc.line(LEFT, y, RIGHT, y);
  y += 30;

  // ---- Title + slip number panel ----
  const BOX_W = 158, BOX_H = 58, BAND_H = 19;
  doc.setFontSize(25); doc.setFont("helvetica", "bold"); setText(TEAL);
  doc.text("Service Slip", LEFT, y + 6);
  doc.setFontSize(9.2); doc.setFont("helvetica", "normal"); setText(120);
  doc.text("Customer Acknowledgement Copy", LEFT, y + 21);

  const boxX = RIGHT - BOX_W, boxY = y - 15;
  setFill(TEAL);
  doc.roundedRect(boxX, boxY, BOX_W, BAND_H + 6, 4, 4, "F");
  setFill(255); setDraw(TEAL); doc.setLineWidth(1.1);
  doc.rect(boxX, boxY + BAND_H, BOX_W, BOX_H - BAND_H, "FD");
  doc.setFontSize(7.4); doc.setFont("helvetica", "bold"); setText(255);
  doc.setCharSpace(1.6);
  doc.text("SLIP NO.", boxX + BOX_W / 2, boxY + 13.5, { align: "center" });
  doc.setCharSpace(0);
  doc.setFontSize(23); setText(INK);
  doc.text(String(slip.slip_number || ""), boxX + BOX_W / 2, boxY + BOX_H - 11, { align: "center" });

  y = boxY + BOX_H + 24;

  // ---- Meta card: four fields, each with an icon ----
  const META_H = 56;
  setDraw(BORDER); setFill(252); doc.setLineWidth(0.8);
  doc.roundedRect(LEFT, y, W, META_H, 5, 5, "FD");
  const meta = [
    ["calendar", "DATE RECEIVED", formatDate(slip.created_at) || "—"],
    ["building", "COMPANY", slip.company || "—"],
    ["person", "CONTACT", slip.contact_name || "—"],
    ["phone", "CONTACT NO.", slip.contact_number || "—"],
  ];
  const cellW = W / 4;
  meta.forEach(([ic, label, value], i) => {
    const cx = LEFT + i * cellW;
    if (i) {
      setDraw(BORDER); doc.setLineWidth(0.7);
      doc.line(cx, y + 10, cx, y + META_H - 10);
    }
    icon(ic, cx + 14, y + 14, 11);
    doc.setFontSize(6.6); doc.setFont("helvetica", "bold"); setText(140);
    doc.setCharSpace(1.1);
    doc.text(label, cx + 31, y + 22);
    doc.setCharSpace(0);
    doc.setFontSize(11); doc.setFont("helvetica", "bold"); setText(INK);
    doc.text(doc.splitTextToSize(String(value), cellW - 28)[0] || "", cx + 14, y + 43);
  });
  y += META_H + 26;

  // ---- Equipment table ----
  sectionHead("EQUIPMENT RECEIVED", "gear");
  y += 4;

  const NO_W = 46, RET_W = 96, DESC_W = W - NO_W - RET_W;
  const drawTableHead = () => {
    setFill(TEAL);
    doc.rect(LEFT, y, W, 21, "F");
    doc.setFontSize(7); doc.setFont("helvetica", "bold"); setText(255);
    doc.setCharSpace(1.2);
    doc.text("NO.", LEFT + NO_W / 2, y + 13.5, { align: "center" });
    doc.text("EQUIPMENT DESCRIPTION", LEFT + NO_W + 14, y + 13.5);
    doc.text("RETURNED", LEFT + NO_W + DESC_W + RET_W / 2, y + 13.5, { align: "center" });
    doc.setCharSpace(0);
    y += 21;
  };
  drawTableHead();

  (slip.machines || []).forEach((m, i) => {
    // Set the font BEFORE measuring. splitTextToSize measures at whatever size
    // was last set, so leaving the serial's 8pt in place made the next row
    // measure narrow, skip its wrap, and then print at 9.6pt straight through
    // the RETURNED column.
    doc.setFontSize(9.6); doc.setFont("helvetica", "normal");
    const lines = doc.splitTextToSize(String(m.machine_desc || ""), DESC_W - 26);
    const serial = String(m.serial_no || "").trim();
    doc.setFontSize(8);
    const serialLines = serial ? doc.splitTextToSize("S/N " + serial, DESC_W - 26) : [];
    const remark = String(m.remarks || "").trim();
    const remarkLines = remark ? doc.splitTextToSize("Remarks: " + remark, DESC_W - 26) : [];
    const rowH = Math.max(30, 16 + lines.length * 12 + serialLines.length * 10 + remarkLines.length * 10);
    if (need(rowH + 30)) drawTableHead();

    setDraw(BORDER); setFill(255); doc.setLineWidth(0.7);
    doc.rect(LEFT, y, W, rowH, "FD");
    doc.line(LEFT + NO_W, y, LEFT + NO_W, y + rowH);
    doc.line(LEFT + NO_W + DESC_W, y, LEFT + NO_W + DESC_W, y + rowH);

    doc.setFontSize(9.6); doc.setFont("helvetica", "normal"); setText(120);
    doc.text(String(i + 1), LEFT + NO_W / 2, y + 19, { align: "center" });
    setText(INK);
    doc.text(lines, LEFT + NO_W + 14, y + 19);
    if (serialLines.length) {
      doc.setFontSize(8); setText(125);
      doc.text(serialLines, LEFT + NO_W + 14, y + 19 + lines.length * 12);
    }
    if (remarkLines.length) {
      doc.setFontSize(8); setText(125);
      doc.text(remarkLines, LEFT + NO_W + 14, y + 19 + lines.length * 12 + serialLines.length * 10);
    }
    // Ticked by hand when the equipment goes back to the customer.
    setDraw(150); doc.setLineWidth(0.8); setFill(255);
    doc.rect(LEFT + NO_W + DESC_W + RET_W / 2 - 6, y + rowH / 2 - 6, 12, 12, "FD");
    y += rowH;
  });
  y += 26;

  // ---- Requested ----
  // What the customer asked for at the counter - not where the job has since
  // got to. Reading a machine's state here meant a slip reprinted after a
  // technician sent something for quoting grew a request the customer never
  // made.
  const requests = [];
  if (slip.check_service) requests.push("CHECK & SERVICE FOR ALL");
  if (slip.repair_only) requests.push("REPAIR ONLY - DO NOT SERVICE");
  if (slip.quote_first) requests.push("QUOTATION REQUIRED BEFORE REPAIR");
  if (requests.length) {
    need(58);
    sectionHead("REQUESTED", "clipboard");
    y += 4;
    const boxH = 16 + requests.length * 15;
    setDraw(BORDER); setFill(TEAL_TINT); doc.setLineWidth(0.8);
    doc.roundedRect(LEFT, y, W, boxH, 5, 5, "FD");
    doc.setFontSize(10); doc.setFont("helvetica", "bold"); setText(INK);
    requests.forEach((r, i) => doc.text(r, LEFT + 16, y + 20 + i * 15));
    y += boxH + 24;
  }

  // ---- Notes ----
  if (slip.notes) {
    const lines = doc.splitTextToSize(String(slip.notes), W - 32);
    need(lines.length * 12 + 46);
    sectionHead("NOTES", "clipboard");
    y += 4;
    const boxH = 16 + lines.length * 12;
    setDraw(BORDER); setFill(252); doc.setLineWidth(0.8);
    doc.roundedRect(LEFT, y, W, boxH, 5, 5, "FD");
    doc.setFontSize(9.4); doc.setFont("helvetica", "normal"); setText(60);
    doc.text(lines, LEFT + 16, y + 18);
    y += boxH + 24;
  }

  // The slip used to print a "CHANGED AFTER SIGNING" box listing every
  // correction, with who made it and when. Customers told the sales team it
  // was a page of detail they had no use for - a corrected phone number is
  // not something they need itemised - so the printed slip now shows what the
  // job IS, and nothing about how it got there.
  //
  // The record itself is untouched: slip_amendments still logs every change,
  // and View Slips still shows "Changed after the customer signed" to staff.
  // It stopped being printed, it did not stop existing.

  // ---- Terms, balanced across two columns ----
  const T_SIZE = 7.2, T_LEAD = 9.6, T_GAP = 34;
  const tColW = (W - T_GAP) / 2 - 22;
  // Measure exactly what drawColumn advances, or the estimate drifts. It used
  // to add a separator for every item including the last, overshooting by 9pt
  // per column - enough to push the signature onto a page of its own.
  const SEP_H = 9;
  const heights = SLIP_TERMS.map((segs) => {
    const end = pdfFlowRich(doc, segs, 0, 0, tColW, T_SIZE, T_LEAD, false);
    return end + T_LEAD + 4;
  });
  const colHeightOf = (items) =>
    items.reduce((a, b) => a + b, 0) + Math.max(0, items.length - 1) * SEP_H;
  const totalH = colHeightOf(heights);
  let split = SLIP_TERMS.length, run = 0;
  for (let i = 0; i < heights.length; i++) {
    run += heights[i] + SEP_H;
    if (run >= totalH / 2) { split = i + 1; break; }
  }
  const colHeight = Math.max(
    colHeightOf(heights.slice(0, split)),
    colHeightOf(heights.slice(split))
  );

  need(colHeight + 46);
  sectionHead("TERMS & CONDITIONS", "shield");
  y += 8;

  const drawColumn = (items, startIndex, x, startY) => {
    let cy = startY;
    items.forEach((segs, n) => {
      // Numbered in a teal ring, the way the printed copy reads.
      setDraw(TEAL); setFill(255); doc.setLineWidth(0.8);
      doc.circle(x + 7, cy - 2.6, 7, "FD");
      doc.setFontSize(6.8); doc.setFont("helvetica", "bold"); setText(TEAL);
      doc.text(String(startIndex + n + 1), x + 7, cy - 0.4, { align: "center" });
      setText(62);
      const end = pdfFlowRich(doc, segs, x + 20, cy, tColW, T_SIZE, T_LEAD);
      cy = end + T_LEAD + 4;
      if (n < items.length - 1) {
        setDraw(232); doc.setLineWidth(0.6);
        doc.setLineDashPattern([1.4, 1.8], 0);
        doc.line(x, cy, x + tColW + 20, cy);
        doc.setLineDashPattern([], 0);
        cy += 9;
      }
    });
    return cy;
  };
  drawColumn(SLIP_TERMS.slice(0, split), 0, LEFT, y);
  drawColumn(SLIP_TERMS.slice(split), split, LEFT + W / 2 + T_GAP / 2, y);
  y += colHeight + 22;

  // ---- Signature ----
  // Customer only: the counter staff are already identified by the letterhead.
  // Pinned to the foot of the last page rather than left to flow. A slip with
  // enough machines to need a second page used to strand the signature half
  // way down it, which reads as though the document carries on.
  const SIG_H = 66;
  const SIG_BOTTOM = 786;          // just clear of the footer rule at 800
  const sigY = SIG_BOTTOM - SIG_H;
  if (y > sigY) { doc.addPage(); }
  y = sigY;
  setDraw(BORDER); setFill(255); doc.setLineWidth(0.8);
  doc.roundedRect(LEFT, y, W, SIG_H, 5, 5, "FD");
  const sigLineY = y + SIG_H - 22;
  const sigW = 250;
  if (slip.signature) {
    try {
      const props = doc.getImageProperties(slip.signature);
      const maxH = 32, maxW = sigW - 24;
      const scale = Math.min(maxW / props.width, maxH / props.height);
      doc.addImage(slip.signature, "PNG", LEFT + 22,
        sigLineY - props.height * scale - 3, props.width * scale, props.height * scale);
    } catch (_) { /* a bad image must never stop the slip printing */ }
  }
  setDraw(90); doc.setLineWidth(0.8);
  doc.line(LEFT + 18, sigLineY, LEFT + 18 + sigW, sigLineY);
  doc.setFontSize(6.8); doc.setFont("helvetica", "bold"); setText(TEAL);
  doc.setCharSpace(1.1);
  doc.text("CUSTOMER SIGNATURE   ·   I ACCEPT THE TERMS ABOVE", LEFT + 18, sigLineY + 14);
  doc.setCharSpace(0);

  // ---- Page footers ----
  const pages = doc.getNumberOfPages();
  for (let p = 1; p <= pages; p++) {
    doc.setPage(p);
    setDraw(228); doc.setLineWidth(0.7);
    doc.line(LEFT, 800, RIGHT, 800);
    icon("info", LEFT, 807, 10);
    doc.setFontSize(7.4); doc.setFont("helvetica", "normal"); setText(120);
    doc.text(
      "Please quote Slip No. " + String(slip.slip_number || "") + " when enquiring about your equipment.",
      LEFT + 16, 816
    );
    doc.text("Page " + p + " of " + pages, RIGHT, 816, { align: "right" });
  }

  return doc.output("blob");
}
// ---- Sending the slip to the customer on WhatsApp --------------------------
// Asked once and remembered: whether the server is set up to send at all, and
// whether it should send without being asked. Both live on the server so
// switching to automatic is a setting there, not an app deploy.
let waStatusPromise = null;
function whatsappStatus() {
  if (!waStatusPromise) {
    waStatusPromise = api("/api/whatsapp/status")
      .catch(() => ({ enabled: false, configured: false, auto_send: false }));
  }
  return waStatusPromise;
}

// The PDF is built here, in the browser, by the same code that produces the
// copy staff look at - then posted up as raw bytes. Sending the finished file
// rather than asking the server to rebuild it means the customer cannot
// receive a subtly different document from the one that was signed.
async function sendSlipWhatsApp(slipIn, { auto = false } = {}) {
  // The customer signed against these terms, so the copy they receive must
  // carry the signature - it is fetched rather than assumed present.
  const slip = await withSignature(slipIn);
  // The customer's own copy, so this one refuses outright rather than asking:
  // sending an unsigned slip to the customer is worse than not sending one.
  if (!slip.signature) {
    return { ok: false, error: "The signature could not be loaded, so nothing was sent. Close the app fully, reopen it and try again." };
  }
  let blob;
  try {
    blob = buildSlipPdf(slip);
  } catch (e) {
    return { ok: false, error: "Couldn't build the PDF: " + e.message };
  }
  const params = new URLSearchParams();
  const me = userName();
  if (me) params.set("who", me);
  params.set("role", getRole());
  if (auto) params.set("auto", "1");

  try {
    const r = await api(
      `/api/slips/${encodeURIComponent(slip.slip_number)}/whatsapp?${params.toString()}`,
      { method: "POST", headers: { "Content-Type": "application/pdf" }, body: blob }
    );
    return { ok: true, to: r.to };
  } catch (e) {
    return { ok: false, error: e.message || "Could not send on WhatsApp." };
  }
}

// One button, used on the success card and again in View Slips - the second
// one matters, because a send that fails needs somewhere to be retried from.
function wireWhatsappButton(btn, slip, { auto = false } = {}) {
  const idle = btn.textContent;
  const run = async (isAuto) => {
    btn.disabled = true;
    btn.textContent = isAuto ? "Sending to customer…" : "Sending…";
    const r = await sendSlipWhatsApp(slip, { auto: isAuto });
    if (r.ok) {
      btn.textContent = "Sent to " + r.to;
      btn.classList.add("wa-sent");
      toast("Slip sent on WhatsApp", "ok");
    } else {
      btn.disabled = false;
      btn.textContent = idle;
      // Left on screen rather than a toast that vanishes: a failed send is
      // something someone has to act on.
      toast(r.error, "err");
    }
  };
  btn.addEventListener("click", () => run(false));
  if (auto) run(true);
}

// ---- Getting the slip to a customer nobody has messaged before --------------
//
// WhatsApp's send-to list is saved contacts and existing chats only, so a new
// customer simply is not in it - staff could produce the PDF and then have
// nowhere to send it. A wa.me link is the way in: it opens a chat with a number
// that is in nobody's address book. Once that chat exists it appears in the
// share sheet like any other, so the order on screen is the order of use:
//
//   Open chat   ->  creates the conversation
//   Share PDF   ->  the conversation is now there to pick
//
// Nothing about the PDF changes, and no customer data leaves the network.
function waDigits(slip) {
  const digits = String(slip.whatsapp_number || slip.contact_number || "").replace(/\D/g, "");
  if (!digits) return "";
  // A local Singapore mobile, as typed on the counter pad. wa.me needs the
  // country code; anything already carrying one is left alone.
  if (digits.length === 8 && /^[689]/.test(digits)) return "65" + digits;
  return digits;
}

// Sent before the PDF, so it says the copy follows rather than claiming to
// carry it - the file goes in the next message, from the share sheet.
function waOpeningMessage(slip, link = "") {
  // Whoever was written down at the counter. The contact is a person and the
  // company is not, so the person is preferred; with neither, the greeting
  // stays polite rather than addressing an empty space.
  const name = String(slip.contact_name || "").trim() ||
               String(slip.company || "").trim() ||
               "Sir/Madam";
  return [
    `Dear ${name},`,
    "Thank you for allowing us to assist you with repairing and servicing of your machine(s).",
    "",
    link
      ? `Kindly find your service slip here:\n${link}`
      : "Kindly find your service slip attached below.",
    "",
    "We will contact you once our technicians have checked and/or worked on it.",
    "",
    "Thank you for your patience.",
    "",
    "- Outboard & Marine Pte Ltd",
  ].join("\n");
}

// ---- What a part fits ---------------------------------------------------------
// AutoCount keeps the machines a part fits on the item's second description
// line. The app has always fetched and shown it - as an unlabelled grey line
// under the description, which nobody could be expected to read as "fits
// these machines". Labelling it and making each machine tappable turns a field
// that was already there into the answer to "what else fits this?".
//
// A survey of the catalogue shaped this: 76% of active items have the line, it
// averages 8 characters, and 873 model codes are shared across 5,722 parts, so
// it is a real vocabulary. Most parts name one machine; the rest separate them
// with commas.
function fitsList(part) {
  return String((part && part.desc2) || "")
    .split(",")
    .map((s) => s.trim())
    .filter(Boolean);
}

// We hold exploded diagrams for 14 machines and AutoCount names 873, so most
// taps cannot lead to a diagram. Listing the machine's parts is the action that
// always works, and the diagram is offered on top when we happen to have it.
function iplIdFor(model) {
  const key = (s) => String(s || "").toUpperCase().replace(/[^A-Z0-9]/g, "");
  const want = key(model);
  if (!want || !ipl.models) return null;
  for (const m of ipl.models) {
    // A book covers "BK3410FL / FL-S" while a part says "BK3410", so either may
    // be the start of the other. Loose on purpose: this only ever navigates,
    // and the rule for the app is that loose matching is fine for finding and
    // never for writing.
    //
    // Prefixes only count from four characters, though. The catalogue contains
    // model codes as short as "T3", and two characters would happily match a
    // book for something else entirely.
    for (const alt of String(m.short || "").split("/")) {
      const c = key(alt);
      if (!c) continue;
      if (c === want) return m.id;
      const shorter = Math.min(c.length, want.length);
      if (shorter >= 4 && (c.startsWith(want) || want.startsWith(c))) return m.id;
    }
  }
  return null;
}

function fitsRowHtml(part) {
  const models = fitsList(part);
  if (!models.length) return "";
  return `
    <div class="fp-row fp-fits">
      <span class="fp-lbl">Fits</span>
      <span class="fp-val">${models.map((m) =>
        `<button type="button" class="fits-chip" data-model="${escapeAttr(m)}">${escapeHtml(m)}</button>`
      ).join("")}</span>
    </div>`;
}

// Every part that fits one machine. Read from AutoCount rather than from the
// diagrams, so it covers all 873 machines the catalogue names and not only the
// 14 we hold books for.
let fitsModel = null;

function closeFitsSheet() {
  $("fits-modal").style.display = "none";
  const stillOpen = ["ipl-modal", "machine-modal", "peek-modal", "note-modal", "order-modal"]
    .some((id) => $(id) && $(id).style.display === "flex");
  if (!stillOpen) document.body.style.overflow = "";
  fitsModel = null;
}
$("fits-close").addEventListener("click", closeFitsSheet);

$("fits-ipl").addEventListener("click", () => {
  const id = iplIdFor(fitsModel);
  closeFitsSheet();
  closeIplPart && closeIplPart();
  if (id) { showScreen("ipl"); openIplModel(id); }
});

async function showModelParts(model) {
  fitsModel = model;
  $("fits-title").textContent = model;
  $("fits-sub").textContent = "";
  $("fits-body").innerHTML = `<div class="fp-loading">Looking up parts…</div>`;
  $("fits-ipl").style.display = "none";
  $("fits-modal").style.display = "flex";
  document.body.style.overflow = "hidden";

  // Offered only when a diagram for this machine actually exists - most
  // machines in the catalogue have no book, and a button that leads nowhere is
  // worse than no button.
  const iplId = iplIdFor(model);
  if (iplId) {
    const m = (ipl.models || []).find((x) => x.id === iplId);
    $("fits-ipl").textContent = `Open the ${m ? m.name : model} diagram`;
    $("fits-ipl").style.display = "";
  }

  try {
    const r = await api(`/api/parts-by-model?model=${encodeURIComponent(model)}`);
    const list = r.results || [];
    if (!list.length) {
      $("fits-body").innerHTML =
        `<div class="fp-empty">No other parts in AutoCount list ${escapeHtml(model)}.</div>`;
      return;
    }
    $("fits-sub").textContent = r.truncated
      ? `${list.length} of ${r.total} parts`
      : `${r.total} part${r.total === 1 ? "" : "s"}`;
    $("fits-body").innerHTML = list.map((x) =>
      `<button type="button" class="company-option" data-code="${escapeAttr(x.item_code)}">
         <span class="fp-opt-desc">${escapeHtml(x.description)}</span>
         <span class="fp-opt-code mono">${escapeHtml(x.item_code)}</span>
       </button>`).join("") +
      (r.truncated ? `<div class="fp-empty">Showing the first ${list.length}. Search the part number to find a specific one.</div>` : "");
    // Straight into the part peek, which already shows stock, shelf and notes -
    // and its own "Fits" row, so one machine leads to another.
    $("fits-body").querySelectorAll(".company-option").forEach((b) =>
      b.addEventListener("click", () => { closeFitsSheet(); peekAtPart(b.dataset.code); })
    );
  } catch (e) {
    $("fits-body").innerHTML = `<div class="fp-empty">${escapeHtml(e.message || "Lookup failed")}</div>`;
  }
}

function wireFits(scope) {
  (scope || document).querySelectorAll(".fits-chip").forEach((b) => {
    if (b.dataset.fitsWired) return;
    b.dataset.fitsWired = "1";
    b.addEventListener("click", () => showModelParts(b.dataset.model));
  });
}

// ---- The customer's copy, kept in Drive -------------------------------------
// Asked once and remembered, the same way the WhatsApp setting is: whether the
// server can file a PDF in Drive at all. When it cannot, everything below is
// skipped and the app behaves exactly as it did before - open the chat, then
// share the file off the phone.
let driveStatusPromise = null;
function driveStatus() {
  if (!driveStatusPromise) {
    driveStatusPromise = api("/api/drive/status").catch(() => ({ enabled: false, configured: false }));
  }
  return driveStatusPromise;
}

// Build this slip's PDF and file it in Drive, returning the link to it.
//
// The PDF is built HERE, by the same code that draws the copy staff look at,
// and posted up as bytes - so the document in Drive is the one that was signed
// rather than something the server assembled separately. Uploading again
// replaces the same file, which is what keeps a link already sent to a
// customer pointing at the current version after a slip is edited.
async function driveStoreSlip(slipIn, { share = false } = {}) {
  const slip = await withSignature(slipIn);
  const blob = buildSlipPdf(slip);
  const r = await api(
    `/api/slips/${encodeURIComponent(slip.slip_number)}/pdf${share ? "?share=1" : ""}`,
    { method: "POST", headers: { "Content-Type": "application/pdf" }, body: blob }
  );
  return r.link || "";
}

// Filed as soon as the slip is registered, so the folder is a complete record
// rather than only the slips somebody happened to send. Deliberately silent:
// this runs behind the success card, and a customer standing at the counter
// should not be shown a Drive error about a slip that saved perfectly well.
function driveArchive(slip) {
  driveStatus().then((d) => {
    if (!d.enabled || !d.configured) return;
    driveStoreSlip(slip).catch((e) => console.warn("[drive] archive failed:", e.message));
  });
}

function contactActionHtml(slip) {
  const shown = String(slip.whatsapp_number || slip.contact_number || "").trim();
  if (!shown) return "";
  const who = slip.contact_name || slip.company || "";
  const digits = waDigits(slip);
  return `
    <div class="contact-row">
      <div class="contact-text">
        <span class="contact-lab">${slip.whatsapp_number ? "WhatsApp" : "Contact"}${
          who ? " · " + escapeHtml(who) : ""}</span>
        <span class="contact-num mono">${escapeHtml(shown)}</span>
      </div>
      ${digits ? `<button type="button" class="contact-act" data-wa="${escapeAttr(digits)}">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M21 11.5a8.4 8.4 0 0 1-9 8.4 8.5 8.5 0 0 1-3.9-.9L3 20.5l1.6-4.9A8.4 8.4 0 0 1 12 3.1a8.4 8.4 0 0 1 9 8.4z"/></svg>
        Open chat
      </button>` : ""}
    </div>
    <p class="contact-hint">New customer? <b>Open chat</b>, send the message, then come back and <b>Share PDF</b> — WhatsApp only lists a customer once something has been sent to them. Needed once per customer; after that, Share PDF on its own.</p>`;
}

function wireContactActions(scope, slip) {
  (scope || document).querySelectorAll("[data-wa]").forEach((btn) => {
    if (btn.dataset.waWired) return;
    btn.dataset.waWired = "1";
    btn.addEventListener("click", () => openCustomerChat(btn, slip));
  });
  // The wording under the buttons depends on whether a link can be sent, and
  // that answer comes from the server, so it is filled in once it arrives.
  driveStatus().then((d) => {
    const hint = (scope || document).querySelector(".contact-hint");
    if (hint && d.enabled && d.configured) hint.innerHTML = LINK_HINT;
  });
}

const LINK_HINT =
  "Opens WhatsApp with the message and a link to this slip. " +
  "Only the customer holding the link can open it — it shows this slip and nothing else.";

// Send the customer their copy.
//
// With Drive set up this is one trip: the PDF is filed, and its link goes
// inside the message, so staff tap once here and once in WhatsApp. Without it,
// the old path - open the chat, send, come back, Share PDF - still works, and
// a Drive that is merely having a bad day falls back to it rather than
// stranding somebody at the counter.
async function openCustomerChat(btn, slip) {
  const d = await driveStatus();
  let link = "";
  if (d.enabled && d.configured) {
    const idle = btn.innerHTML;
    btn.disabled = true;
    btn.textContent = "Preparing…";
    try {
      link = await driveStoreSlip(slip, { share: true });
    } catch (e) {
      toast("Couldn't put the slip in Drive — send it with Share PDF instead", "err");
      console.warn("[drive]", e.message);
    }
    btn.disabled = false;
    btn.innerHTML = idle;
  }
  // A new tab rather than this one: without a link the app must still be here
  // to come back to for Share PDF.
  window.open(
    `https://wa.me/${btn.dataset.wa}?text=${encodeURIComponent(waOpeningMessage(slip, link))}`,
    "_blank", "noopener"
  );
}

// Share the PDF via the device's native share sheet (WhatsApp/email/AirDrop),
// falling back to a plain download where sharing files isn't supported.
// The slip object no longer carries the signature - it is fetched here, by the
// one thing that draws it. Failing to get it must not stop the PDF: a slip
// without the drawn signature is still the slip.
async function withSignature(slip) {
  if (!slip || slip.signature) return slip;
  try {
    const r = await api(`/api/slips/${encodeURIComponent(slip.slip_number)}/signature`);
    return { ...slip, signature: r.signature || "" };
  } catch (_) {
    return slip;
  }
}

// A slip PDF without the signature is a document missing the customer's
// acceptance of the printed terms. It used to be impossible to produce one by
// accident; once the signature moved off the slip response it became possible,
// and the first way it happened was a phone still running the previous version
// of the app - which looked for a signature the server had stopped sending and
// found none. Silence was the wrong answer to that, so this asks.
async function confirmUnsigned(slip) {
  if (slip && slip.signature) return true;
  return confirm(
    `Slip ${slip ? slip.slip_number : ""} has no signature on it.\n\n` +
    "If this app was updated moments ago, close it fully and open it again — " +
    "that usually fixes it.\n\nProduce the PDF without the signature anyway?"
  );
}

async function shareSlipPdf(slipIn) {
  const slip = await withSignature(slipIn);
  if (!(await confirmUnsigned(slip))) return;
  let blob;
  try {
    blob = buildSlipPdf(slip);
  } catch (e) {
    toast("Couldn't build PDF: " + e.message, "err");
    return;
  }
  await deliverPdf(blob, `ServiceSlip_${slip.slip_number}.pdf`, `Service Slip ${slip.slip_number}`);
}

// Getting a PDF off the phone. The share sheet where the browser has one -
// that is what puts it in front of a printer, or WhatsApp, or mail - and a
// plain download everywhere else. Extracted so the workshop printout and the
// customer's slip cannot drift apart in how they are handed over.
async function deliverPdf(blob, filename, title) {
  const file = new File([blob], filename, { type: "application/pdf" });
  if (navigator.canShare && navigator.canShare({ files: [file] })) {
    try {
      await navigator.share({ files: [file], title });
      return;
    } catch (_) { /* cancelled, or the share failed - fall through to download */ }
  }
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url; a.download = filename;
  document.body.appendChild(a); a.click(); a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 4000);
}

function statusErr(m) { return `<span class="led" style="background:var(--amber);box-shadow:0 0 0 3px var(--amber-tint)"></span> ${escapeHtml(m)}`; }
function statusInfo(m) { return `<span class="led"></span> ${escapeHtml(m)}`; }
function statusOk(m) { return `<span class="led" style="background:#38A32A;box-shadow:0 0 0 3px rgba(56,163,42,.18)"></span> ${escapeHtml(m)}`; }

// ============================================================================
// OPEN SERVICE
// ============================================================================
// ---- Open Service: slip list -> slip detail -> machine modal ---------------
async function enterOpenService() {
  showScreen("open");
  // Technicians only: this row tells THEM what the customer said. Sales have
  // their own on Need to Quote, pointing the other way. Anyone else opening a
  // slip does not need a second notifications control.
  if (getRole() === "tech") renderPushRow("tech");
  else { const r = $("push-row-tech"); if (r) r.style.display = "none"; }
  session.slipNumber = null; session.slip = null; session.machineId = null;
  session.technician = ""; session.pendingParts = [];
  $("os-slip-list").innerHTML = `<div class="fp-loading">Loading slips…</div>`;
  try {
    session.allSlips = await api(`/api/slips?status=working`);
    renderSlipList();
  } catch (e) {
    $("os-slip-list").innerHTML = "";
    toast(e.message, "err");
  }
}

// Render the active-slip list, filtered by the search box (number or company).
function renderSlipList() {
  const q = ($("os-search").value || "").trim().toLowerCase();
  const list = (session.allSlips || []).filter((s) =>
    !q || s.slip_number.includes(q) || (s.company || "").toLowerCase().includes(q)
  );
  const wrap = $("os-slip-list");
  if (!list.length) {
    wrap.innerHTML = `<div class="fp-empty">${q ? "No slips match" : "No open slips"}</div>`;
    return;
  }
  // Newest first
  const sorted = [...list].sort((a, b) => b.slip_number.localeCompare(a.slip_number));
  wrap.innerHTML = sorted.map((s) => `
    <button type="button" class="slip-card" data-slip="${escapeAttr(s.slip_number)}">
      <div class="slip-card-top">
        <strong>${escapeHtml(s.slip_number)}</strong>
        <span class="vs-status vs-${escapeAttr(s.status)}">${escapeHtml(STATUS_LABEL[s.status] || s.status)}</span>
      </div>
      <div class="slip-card-co">${escapeHtml(s.company)}</div>
      <div class="slip-card-sub">${(s.machines || []).length} machine${(s.machines || []).length === 1 ? "" : "s"}${s.created_at ? " · " + escapeHtml(formatDate(s.created_at)) : ""}</div>
    </button>`).join("");
  wrap.querySelectorAll(".slip-card").forEach((btn) =>
    btn.addEventListener("click", () => onSlipChosen(btn.dataset.slip))
  );
}
$("os-search").addEventListener("input", renderSlipList);
$("top-back").addEventListener("click", enterOpenService);

async function onSlipChosen(slipNumber) {
  if (!slipNumber) return;
  try {
    session.slip = await api(`/api/slips/${encodeURIComponent(slipNumber)}`);
    session.slipNumber = slipNumber;
    session.machineId = null;
    showScreen("slip");
    renderSlipScreen();
  } catch (e) {
    toast(e.message, "err");
  }
}

// The slip-detail screen: header card, machines as buttons, status actions.
function renderSlipScreen() {
  const slip = session.slip;
  if (!slip) return;

  const meta = [];
  if (slip.contact_name) meta.push(`Contact: ${escapeHtml(slip.contact_name)}`);
  if (slip.contact_number) meta.push(escapeHtml(slip.contact_number));
  const created = formatDate(slip.created_at);

  $("sd-head").innerHTML = `
    <div class="vs-card">
      <div class="vs-head">
        <div>
          <div class="vs-company">${escapeHtml(slip.company)}</div>
          <div class="vs-sub">Slip ${escapeHtml(slip.slip_number)}${created ? " · Created " + escapeHtml(created) : ""}</div>
        </div>
        <span class="vs-status vs-${escapeAttr(slip.status)}" id="os-status-badge">${escapeHtml(STATUS_LABEL[slip.status] || slip.status)}</span>
      </div>
      ${meta.length ? `<div class="vs-sub">${meta.join(" · ")}</div>` : ""}
      ${slip.notes ? `<div class="vs-notes">${escapeHtml(slip.notes)}</div>` : ""}
    </div>
    ${requestBadgesHtml(slip, "sd")}`;

  // Machines as tappable buttons with per-machine progress.
  $("sd-machines").innerHTML = slip.machines.map((m) => {
    const parts = m.parts || [];
    const labour = Number(m.labour_charge) || 0;
    let total = labour; for (const p of parts) total += p.unit_price * p.quantity;
    const hasComment = !!String(m.repair_comment || "").trim();
    const worked = parts.length > 0 || hasComment || labour > 0;
    // Where this machine is, on the machine itself - otherwise the only way to
    // find out which one is waiting is to open each in turn.
    const qTag = machinePill(m).trim();
    return `
      <button type="button" class="machine-btn ${worked ? "machine-btn-worked" : ""}" data-machine="${m.id}">
        <div class="machine-btn-top">
          <strong>${escapeHtml(m.machine_desc)}</strong>
          ${qTag || (worked ? `<span class="machine-tick">✓</span>` : `<span class="machine-untouched">Need Repair</span>`)}
        </div>
        <div class="machine-btn-sub">${m.serial_no ? "S/N " + escapeHtml(m.serial_no) + " · " : ""}${parts.length} part${parts.length === 1 ? "" : "s"}${hasComment ? " · has comment" : ""}${total > 0 ? " · " + money(total) : ""}</div>
        ${m.remarks ? `<div class="machine-btn-remarks">“${escapeHtml(m.remarks)}”</div>` : ""}
      </button>`;
  }).join("");
  $("sd-machines").querySelectorAll(".machine-btn").forEach((btn) =>
    btn.addEventListener("click", () => openMachineModal(Number(btn.dataset.machine)))
  );

  renderSlipStatusUI();
  updateSlipFooter();
}

// ---- Machine modal ----------------------------------------------------------
function openMachineModal(machineId) {
  session.machineId = machineId;
  session.pendingParts = [];

  // Whoever opens the machine is the person working on it, so there is nothing
  // to ask. Technicians keep their long-standing codes; anyone else is recorded
  // by their initials.
  const me = getUser();
  session.technician = initialsFor(me);
  $("os-tech").value = session.technician;
  $("os-tech-field").style.display = "none";
  $("os-entry").style.display = "none";
  const m = currentMachine();
  $("mm-title").textContent = m ? m.machine_desc : "Machine";
  // Which machine this is decides whether the tube buttons belong here at all.
  try { renderTubePicker(); } catch (_) {}
  $("mm-sub").textContent = `Slip ${session.slipNumber} · ${session.slip.company}`;
  const mmr = $("mm-remarks");
  if (m && m.remarks) { mmr.textContent = `“${m.remarks}”`; mmr.style.display = "block"; }
  else { mmr.style.display = "none"; mmr.textContent = ""; }
  // The same thing the machine's paper tag says. Shown on every machine of the
  // slip, because the quotation was agreed for the job, not for one machine.
  const ask = $("mm-ask-quote");
  if (ask) ask.style.display = session.slip && session.slip.quote_first ? "flex" : "none";
  loadCommentForCurrentMachine();
  loadLabourForCurrentMachine();
  renderMachineParts();
  renderMachineQuoteRow();
  renderMachineDecisionBanner();
  updateSlipFooter();
  $("machine-modal").style.display = "flex";
  document.body.style.overflow = "hidden";
  // With the technician already known there is nothing left to wait for, so
  // open straight onto the part entry instead of a panel nobody has to fill in.
  maybeShowEntry();
}

async function closeMachineModal(save) {
  if (!save && session.pendingParts.length) {
    const ok = confirm(`${session.pendingParts.length} scanned part(s) haven't been saved. Discard them?`);
    if (!ok) return;
  }
  try { stopQrScanner(); } catch (_) {}
  if (save) {
    $("mm-save").disabled = true;
    try {
      await commitPendingParts();
      await saveCurrentLabour();
      await saveCurrentComment();
      toast("Saved", "ok");
    } catch (e) {
      toast(e.message, "err");
      $("mm-save").disabled = false;
      return; // keep the modal open so nothing scanned is lost
    }
    $("mm-save").disabled = false;
  }
  $("machine-modal").style.display = "none";
  document.body.style.overflow = "";
  session.machineId = null;
  session.pendingParts = [];
  // Refresh the slip so the machine buttons reflect the latest state.
  try { await refreshSlip(); } catch (_) {}
  renderSlipScreen();
}
// Labour feeds the machine total, so recompute as it is typed.
$("os-labour").addEventListener("input", () => updateSlipFooter());

$("mm-save").addEventListener("click", () => closeMachineModal(true));
$("mm-close").addEventListener("click", () => closeMachineModal(false));

// POST every pending part to the server, in order. Stops on first failure
// (already-saved ones are removed from the pending list as they succeed).
async function commitPendingParts() {
  while (session.pendingParts.length) {
    const p = session.pendingParts[0];
    await api(`/api/machines/${session.machineId}/parts`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        item_code: p.item_code, description: p.description, uom: p.uom,
        unit_price: p.unit_price, quantity: p.quantity, technician: p.technician,
        free_text: !!p.free_text,
        // Which tube type this line is. Without it the server would merge two
        // tubes cut from the same roll into one line at one price.
        variant: p.variant || "",
      }),
    });
    session.pendingParts.shift();
  }
}

// Load the saved comment for the currently selected machine into the textbox.
function loadCommentForCurrentMachine() {
  const box = $("os-comment");
  if (!box) return;
  const m = currentMachine();
  box.value = (m && m.repair_comment) ? m.repair_comment : "";
}

function loadLabourForCurrentMachine() {
  const box = $("os-labour");
  if (!box) return;
  const m = currentMachine();
  const v = m ? Number(m.labour_charge) || 0 : 0;
  box.value = v ? v.toFixed(2) : "";
}

// Labour typed into the box, as a number. Blank means zero.
function currentLabourValue() {
  const box = $("os-labour");
  if (!box) return 0;
  const v = parseFloat(box.value);
  return Number.isFinite(v) && v > 0 ? Math.round(v * 100) / 100 : 0;
}

// Save the labour charge for the currently selected machine.
async function saveCurrentLabour() {
  const box = $("os-labour");
  if (!box || !session.machineId) return;
  const m = currentMachine();
  const value = currentLabourValue();
  if (m && (Number(m.labour_charge) || 0) === value) return;   // unchanged
  await api(`/api/machines/${session.machineId}/labour`, {
    method: "PATCH",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ labour_charge: value }),
  });
  if (m) m.labour_charge = value;
}

// Save the textbox comment to whichever machine is currently selected.
async function saveCurrentComment() {
  const box = $("os-comment");
  if (!box || !session.machineId) return;
  const m = currentMachine();
  const current = box.value;
  // Skip the network call if nothing changed.
  if (m && (m.repair_comment || "") === current) return;
  try {
    await api(`/api/machines/${session.machineId}/comment`, {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ comment: current }),
    });
    if (m) m.repair_comment = current; // keep local copy in sync
  } catch (e) {
    toast("Couldn't save comment: " + e.message, "err");
  }
}

// Parts are stored against the initials (WJ, XL, KM, R) so old and new records
// agree, but there is no reason to show someone a code for their own name.
function technicianLabel() {
  const me = getUser();
  if (me && initialsFor(me) === session.technician) return me.name;
  const other = STAFF.find((u) => initialsFor(u) === session.technician);
  return other ? other.name : session.technician;
}

function onTechChosen(tech) {
  session.technician = tech || "";
  maybeShowEntry();
}

function maybeShowEntry() {
  const ready = session.slipNumber && session.machineId && session.technician;
  $("os-entry").style.display = ready ? "block" : "none";
  if (ready) {
    setMode(currentMode || "qr");
    renderContext();
    renderMachineParts();
    updateSlipFooter();
  }
}

// The machine, the slip and the company are already in the header, so this is
// only what the header does not carry: who is working on it and when it came
// in. It used to be a card below repeating all five, which pushed the parts
// list - the actual record of the job - off the bottom of the screen.
function renderContext() {
  const created = formatDate(session.slip.created_at);
  const tech = technicianLabel();
  // The labels are their own elements so they can be translated: the app
  // matches whole strings, and "Tech WJ · Received 1 Sep" would never match
  // anything - leaving this line in English on a technician's phone.
  const bits = [];
  if (tech) bits.push(`<span>Tech</span> ${escapeHtml(tech)}`);
  if (created) bits.push(`<span>Received</span> ${escapeHtml(created)}`);
  $("mm-who").innerHTML = bits.join(" · ");
}

// The scanned-part entry point. Parts are held as PENDING (not yet saved) and
// committed to the server when the technician taps Save in the machine popup.
async function addByCode(code) {
  code = (code || "").trim();
  if (!code) return;
  if (!session.machineId || !session.technician) {
    toast("Pick your name first", "err");
    return;
  }
  try {
    const item = await lookupItem(code);
    // Same part already pending for this tech? Just bump its quantity.
    const existing = session.pendingParts.find(
      (p) => p.item_code === item.item_code && p.technician === session.technician
    );

    // A part that has been superseded is worth knowing about while it is still
    // in your hand, not after the job is quoted. Only on the FIRST scan of it:
    // the technician has already read it by the second, and a warning that
    // repeats is a warning people learn to dismiss.
    if (!existing) {
      const note = await fetchPartNote(item.item_code);
      if (note && note.note) {
        const ok = confirm(
          `${item.item_code}\n${item.description || ""}\n\n${note.note}\n\nAdd this part anyway?`
        );
        if (!ok) return;
      }
    }

    if (existing) {
      existing.quantity += 1;
    } else {
      let description = item.description;
      // Judged on what the CATALOGUE says, before any renaming - and recorded
      // on the line, because the rename is the whole point and would otherwise
      // erase the evidence.
      const freeText = isFreeTextPart(item.item_code, item.description);
      // The moment to name one of these is now, while the part is in hand -
      // not later from a list of identical "SPARE PARTS" lines.
      if (freeText) {
        const typed = prompt(
          `${item.item_code}

What is this part? It will appear on the Sales Order.`,
          ""
        );
        if (typed === null) return;                  // changed their mind
        if (typed.trim()) description = typed.trim();
      }
      session.pendingParts.push({
        item_code: item.item_code,
        description,
        uom: item.uom,
        unit_price: item.unit_price,
        quantity: 1,
        technician: session.technician,
        free_text: freeText,
      });
      toast(`Added ${description} — tap Save when done`, "ok");
      renderMachineParts();
      updateSlipFooter();
      return;
    }
    toast(`Added ${item.description} — tap Save when done`, "ok");
    renderMachineParts();
    updateSlipFooter();
  } catch (e) {
    toast(e.message, "err");
  }
}

async function refreshSlip() {
  if (!session.slipNumber) return;
  // Preserve whatever the technician has typed in the comment box for the
  // current machine, so a part-scan refresh doesn't wipe an unsaved comment.
  const box = $("os-comment");
  const unsaved = (box && session.machineId) ? box.value : null;

  session.slip = await api(`/api/slips/${encodeURIComponent(session.slipNumber)}`);

  if (unsaved !== null) {
    const m = currentMachine();
    if (m) m.repair_comment = unsaved; // keep local copy aligned with the box
  }
}

const PENCIL = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M3 17.5 17.5 3a2.1 2.1 0 0 1 3 3L6 20.5 2 21z"/></svg>';
const TRASH = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M3 6h18M8 6V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2m2 0v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6"/><path d="M10 11v6M14 11v6"/></svg>';

function currentMachine() {
  if (!session.slip) return null;
  return session.slip.machines.find((m) => m.id === session.machineId) || null;
}

// The A5-A8 and MISC entries stand in for something not really in the
// catalogue. The code is right for the accounts; what the part actually was is
// only known to whoever is holding it.
//
// The marker can sit in EITHER field: "MISC - INDENT UNIT_PARTS" is one such
// entry, and whether AutoCount carries that as the code or as the description
// of some other code, it is the same kind of line. Kept identical to the
// backend copy in data/sqliteRepo.js - if one changes, change both.
function isFreeTextPart(itemCode, description = "") {
  const norm = (v) => String(v || "").trim().toUpperCase();
  const code = norm(itemCode);
  if (/^A[5-8]\b/.test(code) || code.startsWith("MISC")) return true;
  // "Starts with", not "contains": a real part whose description merely
  // mentions miscellaneous something must not turn into a free-text line.
  return norm(description).startsWith("MISC");
}

async function editPartDescription(partId, current) {
  const text = prompt("What is this part? It will appear on the Sales Order.", current || "");
  if (text === null) return;
  const clean = text.trim();
  if (!clean) { toast("A description is required.", "err"); return; }
  try {
    await api(`/api/parts/${partId}`, {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ description: clean }),
    });
    await refreshSlip();
    renderMachineParts();
  } catch (e) {
    toast(e.message, "err");
  }
}

// ---- The tube picker -------------------------------------------------------
// Shown only on a machine that looks like a fogger. The model is free text
// typed at the counter, so looksLikeFogger() is deliberately generous - see
// fogger-tubes.js for why erring towards showing it is the safer mistake.
let tubePending = null;      // { tube, pieces } while the piece prompt is open

function renderTubePicker() {
  const box = $("tube-pick");
  if (!box || !window.FOGGER_TUBES) return;
  const m = currentMachine();
  if (!m || !window.FOGGER_TUBES.isFogger(m)) {
    box.style.display = "none";
    return;
  }
  // A price typed wrong here reaches a customer's invoice with nothing in
  // between to question it, so the table checks itself against the second
  // figure the sheet prints. Say so loudly rather than pricing a job on it.
  const bad = window.FOGGER_TUBES.check();
  if (bad.length) {
    box.style.display = "";
    $("tube-btns").innerHTML =
      `<div class="tube-frac" style="grid-column:1/-1">Tube table looks wrong — ${escapeHtml(bad.join("; "))}. Tell the office before using these.</div>`;
    return;
  }
  box.style.display = "";
  $("tube-btns").innerHTML = window.FOGGER_TUBES.list.map((t) => `
    <button type="button" class="tube-btn" data-tube="${escapeAttr(t.type)}">
      ${escapeHtml(t.type)}
      <span class="tube-each">${money(t.each)}</span>
    </button>`).join("");
}

function openTubeQty(type) {
  const t = window.FOGGER_TUBES && window.FOGGER_TUBES.byType(type);
  if (!t) return;
  tubePending = { tube: t, pieces: 1 };
  $("tube-qty-title").textContent = `Tube ${t.type}`;
  $("tube-qty-sub").textContent = `${t.code} · ${money(t.each)} a piece`;
  $("tube-qty-status").innerHTML = "";
  $("tube-qty-other").value = "";
  renderTubeQtyButtons();
  $("tube-qty-modal").style.display = "flex";
  document.body.style.overflow = "hidden";
}

function renderTubeQtyButtons() {
  $("tube-qty-btns").innerHTML = [1, 2, 3].map((n) => `
    <button type="button" class="tube-qty-btn${tubePending && tubePending.pieces === n ? " on" : ""}" data-tubeqty="${n}">${n}</button>`).join("");
  if (tubePending) {
    const t = tubePending.tube;
    const n = tubePending.pieces;
    $("tube-qty-status").innerHTML = statusInfo(
      `${n} pc${n === 1 ? "" : "s"} · ${Number((n * t.unitQty).toFixed(4))} of a roll · ${money(n * t.unitQty * t.unitPrice)}`
    );
  }
}

function closeTubeQty() {
  $("tube-qty-modal").style.display = "none";
  document.body.style.overflow = "";
  tubePending = null;
}

// Add the chosen tube to the machine.
//
// The item code is RESOLVED against AutoCount rather than written from the
// table. The table is a workshop sheet, not the stock ledger, and a code taken
// from it on trust would end up on a Sales Order that nobody notices is wrong
// until it is in AutoCount. If the code will not resolve, say so and add
// nothing - the technician can still type the part in the normal way.
async function addTubeToMachine() {
  if (!tubePending) return;
  const { tube, pieces } = tubePending;
  const btn = $("tube-qty-add");
  btn.disabled = true;
  $("tube-qty-status").innerHTML = statusInfo("Checking the item code…");
  try {
    const item = await lookupItem(tube.code);
    if (!item || !item.item_code) throw new Error("not found");
    session.pendingParts.push({
      item_code: item.item_code,
      description: `PULSFOG TUBE ${tube.type}`,
      uom: item.uom || "UNIT",
      // The sheet's roll price, not AutoCount's: one item code covers several
      // tube types at several prices, so AutoCount has no single figure that
      // could be right for all of them.
      unit_price: tube.unitPrice,
      quantity: Number((pieces * tube.unitQty).toFixed(4)),
      variant: tube.type,
      technician: session.technician,
      free_text: false,
    });
    closeTubeQty();
    toast(`Added tube ${tube.type} × ${pieces} — tap Save when done`, "ok");
    renderMachineParts();
    updateSlipFooter();
  } catch (e) {
    $("tube-qty-status").innerHTML = statusErr(
      `Could not find ${tube.code} in AutoCount. Add it by typing the part instead, and tell the office the code on the tube sheet may have changed.`
    );
  }
  btn.disabled = false;
}

$("tube-btns").addEventListener("click", (e) => {
  const b = e.target.closest("[data-tube]");
  if (b) openTubeQty(b.dataset.tube);
});
$("tube-qty-btns").addEventListener("click", (e) => {
  const b = e.target.closest("[data-tubeqty]");
  if (!b || !tubePending) return;
  tubePending.pieces = Number(b.dataset.tubeqty);
  $("tube-qty-other").value = "";
  renderTubeQtyButtons();
});
$("tube-qty-other").addEventListener("input", (e) => {
  if (!tubePending) return;
  const n = parseInt(e.target.value, 10);
  if (Number.isFinite(n) && n > 0 && n < 100) {
    tubePending.pieces = n;
    renderTubeQtyButtons();
    // renderTubeQtyButtons clears the highlight for anything but 1-3, which is
    // what we want, but it must not steal the box the tech is typing in.
    $("tube-qty-other").value = String(n);
    $("tube-qty-other").focus();
  }
});
$("tube-qty-close").addEventListener("click", closeTubeQty);
$("tube-qty-add").addEventListener("click", addTubeToMachine);

// ---- PulsFOG tubes ---------------------------------------------------------
// These are cut to length from a roll, so one repair uses a fraction of a
// stock unit - 0.265 of a roll for a piece of tube 142, not "1 tube". The
// workshop was working that out from a paper table, which is the kind of sum
// that goes wrong at four o'clock on a Friday.
//
// The line is stored the way the stock actually moves: quantity is the roll
// fraction and the price is the roll price, so AutoCount deducts the right
// amount. The PIECE COUNT IS NEVER STORED - it is worked back out from the
// quantity wherever it is shown. That way topping a line up from two pieces to
// three cannot leave a "x 2 pcs" caption behind, disagreeing with the number
// next to it.
function tubeFor(part) {
  if (!part || !window.FOGGER_TUBES) return null;
  const type = String(part.variant || "");
  return type ? window.FOGGER_TUBES.byType(type) : null;
}

// Pieces, from the fraction. Rounded because 3 x 0.075 is 0.22499999999999998
// in binary floating point, and a technician should not be shown "2 pcs"
// because of that.
function tubePieces(part) {
  const t = tubeFor(part);
  if (!t || !(t.unitQty > 0)) return null;
  return Math.max(1, Math.round((Number(part.quantity) || 0) / t.unitQty));
}

// What the quantity column should read, and what sits under the description.
function tubeQtyDisplay(part) {
  const t = tubeFor(part);
  if (!t) return null;
  const pcs = tubePieces(part);
  return {
    pieces: pcs,
    // Trailing zeros trimmed: 0.53, not 0.5300000000000001 and not 0.530.
    frac: `${pcs} pc${pcs === 1 ? "" : "s"} · ${Number((pcs * t.unitQty).toFixed(4))} of a roll`,
  };
}

function renderMachineParts() {
  const wrap = $("machine-parts");
  const machine = currentMachine();
  const parts = machine ? (machine.parts || []) : [];
  wrap.innerHTML = "";

  // Pending (scanned but not yet saved) parts first, visually distinct.
  if (session.pendingParts.length) {
    const pendWrap = document.createElement("div");
    pendWrap.className = "pending-wrap";
    pendWrap.innerHTML = `<div class="pending-head">Not saved yet — tap Save below</div>` +
      session.pendingParts.map((p, i) => `
        <div class="line line-pending">
          <div class="head">
            <div class="info">
              <div class="desc">${escapeHtml(p.description)}${
                p.free_text
                  ? ` <button type="button" class="desc-edit" data-pdesc="${i}" aria-label="Edit description">${PENCIL}</button>`
                  : ""
              }</div>
              <div class="sku mono">${escapeHtml(p.item_code)} · ${escapeHtml(p.technician)}</div>
              ${tubeQtyDisplay(p) ? `<div class="tube-frac">${escapeHtml(tubeQtyDisplay(p).frac)}</div>` : ""}
            </div>
            <div class="price-col">
              <span class="price-edit">$<input type="number" step="0.01" min="0" value="${Number(p.unit_price).toFixed(2)}" data-pprice="${i}" inputmode="decimal" aria-label="Unit price" /></span>
              <button class="remove" data-pdel="${i}" aria-label="Remove part">${TRASH}</button>
            </div>
          </div>
          <div class="foot">
            <div class="qty">
              <button data-pdec="${i}" aria-label="Decrease">−</button>
              <input type="number" min="1" value="${tubeQtyDisplay(p) ? tubeQtyDisplay(p).pieces : p.quantity}" data-pqty="${i}" inputmode="numeric" aria-label="Quantity" />
              <button data-pinc="${i}" aria-label="Increase">+</button>
            </div>
            <div class="amt-wrap">
              <span class="amt-lbl">Line total</span>
              <span class="amt">${money(p.unit_price * p.quantity)}</span>
            </div>
          </div>
        </div>`).join("");
    wrap.appendChild(pendWrap);
  }

  if (parts.length === 0 && session.pendingParts.length === 0) {
    wrap.innerHTML = `
      <div class="cart-empty">
        <div class="ico">
          <svg viewBox="0 0 24 24" fill="none" stroke="#1f6f78" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><circle cx="9" cy="21" r="1"/><circle cx="20" cy="21" r="1"/><path d="M1 1h4l2.7 13.4a2 2 0 0 0 2 1.6h9.7a2 2 0 0 0 2-1.6L23 6H6"/></svg>
        </div>
        <strong>No parts yet</strong>
        <span>Scan or type a part to add it to this machine.</span>
      </div>`;
    return;
  }

  for (const p of parts) {
    const noPrice = !(Number(p.unit_price) > 0);
    const el = document.createElement("div");
    el.className = "line" + (noPrice ? " no-price" : "");
    el.innerHTML = `
      <div class="head">
        <div class="info">
          <div class="desc">${escapeHtml(p.description)}${
            (p.free_text || isFreeTextPart(p.item_code, p.description))
              ? ` <button type="button" class="desc-edit" data-desc="${p.id}" aria-label="Edit description">${PENCIL}</button>`
              : ""
          }</div>
          <div class="sku mono">${escapeHtml(p.item_code)} · ${escapeHtml(p.technician || "")}</div>
          ${tubeQtyDisplay(p) ? `<div class="tube-frac">${escapeHtml(tubeQtyDisplay(p).frac)}</div>` : ""}
          ${noPrice ? `<div class="no-price-tag">No price — enter one</div>` : ""}
        </div>
        <div class="price-col">
          <span class="price-edit">$<input type="number" step="0.01" min="0" value="${Number(p.unit_price).toFixed(2)}" data-price="${p.id}" inputmode="decimal" aria-label="Unit price" /></span>
          <button class="remove" data-del="${p.id}" aria-label="Remove part">${TRASH}</button>
        </div>
      </div>
      <div class="foot">
        <div class="qty">
          <button data-dec="${p.id}" aria-label="Decrease">−</button>
          <input type="number" min="1" value="${tubeQtyDisplay(p) ? tubeQtyDisplay(p).pieces : p.quantity}" data-qty="${p.id}" inputmode="numeric" aria-label="Quantity" />
          <button data-inc="${p.id}" aria-label="Increase">+</button>
        </div>
        <div class="amt-wrap">
          <span class="amt-lbl">Line total</span>
          <span class="amt">${money(p.unit_price * p.quantity)}</span>
        </div>
      </div>`;
    wrap.appendChild(el);
  }
}

async function setPartPrice(partId, price) {
  try {
    await api(`/api/parts/${partId}`, {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ unit_price: price }),
    });
    await refreshSlip();
    renderMachineParts();
    updateSlipFooter();
  } catch (e) {
    toast(e.message, "err");
  }
}

async function setPartQty(partId, qty) {
  try {
    await api(`/api/parts/${partId}`, {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ quantity: qty }),
    });
    await refreshSlip();
    renderMachineParts();
    updateSlipFooter();
  } catch (e) {
    toast(e.message, "err");
  }
}

function updateSlipFooter() {
  if (!session.slip) return;

  // Slip summary (on the slip-detail screen): number, machine count, slip total
  $("os-slip-badge").textContent = session.slipNumber || "—";
  const machines = session.slip.machines || [];
  let slipTotal = 0, slipParts = 0;
  for (const m of machines) {
    for (const p of (m.parts || [])) { slipTotal += p.unit_price * p.quantity; slipParts++; }
    slipTotal += Number(m.labour_charge) || 0;
  }
  $("os-machine-name").textContent = `${machines.length} machine${machines.length === 1 ? "" : "s"}`;
  $("os-machine-total").textContent = money(slipTotal);

  // Status badge + which status action buttons apply right now
  renderSlipStatusUI();

  // Machine total inside the modal: saved parts + pending (unsaved) parts
  const machine = currentMachine();
  if (machine) {
    let mt = 0;
    for (const p of (machine.parts || [])) mt += p.unit_price * p.quantity;
    for (const p of session.pendingParts) mt += p.unit_price * p.quantity;
    // Reads the box, not the saved value, so the total moves as it is typed.
    mt += currentLabourValue();
    const mmTotal = $("mm-total");
    if (mmTotal) mmTotal.textContent = money(mt);
  }

  // Create Sales Order covers the whole slip; enable when parts exist and the
  // slip hasn't already been repaired/closed.
  // Billable when there is anything to charge for — parts OR labour. A slip
  // that is pure labour ("cleaned the carburettor, no parts") is legitimate.
  const st = session.slip.status;
  const billable = slipParts > 0 || slipTotal > 0;
  // A slip converted machine by machine sits at ALL_REPAIRED between orders, so
  // that status must not disable the button any more - only a slip whose every
  // machine is already on an order, or one that is closed.
  renderAutoCountPending();
  const machinesLeft = (session.slip && (session.slip.machines || []).some((m) => !m.converted_at));
  $("os-create-so").disabled = !billable || !machinesLeft || st === "CLOSED" || st === "CONVERTED";
}

// ---- Quoting one machine ----------------------------------------------------
// A technician who has finished one machine on a two-machine slip can hand that
// one over to be priced without claiming the other is done. The slip's own
// buttons still cover "all of them together".
function renderMachineDecisionBanner() {
  const box = $("mm-decision");
  if (!box) return;
  const m = currentMachine();
  const st = m ? m.state : "";
  // Only the states a technician has to act on. "Received" is the ordinary
  // case, and a banner shown always is a banner nobody reads.
  if (st !== "TO_REPAIR" && st !== "CONDEMNED" && st !== "QUOTED") {
    box.style.display = "none"; box.innerHTML = ""; return;
  }
  const who = m.decided_by ? ` ${escapeHtml(m.decided_by)}` : "";
  const when = m.decided_at ? ` · ${escapeHtml(formatDate(m.decided_at) || m.decided_at)}` : "";
  if (st === "QUOTED") {
    box.className = "decision-banner decision-quoted";
    box.innerHTML = `<b>Quoted — waiting on the customer</b>Hold off until they say yes or no.
       <span class="decision-who">Quoted by${who}${when}</span>`;
  } else if (st === "TO_REPAIR") {
    box.className = "decision-banner decision-repair";
    box.innerHTML = `<b>Go ahead and repair</b>The customer has confirmed this repair.
       <span class="decision-who">Confirmed by${who}${when}</span>`;
  } else {
    const d = DISPOSAL_LABEL[m.disposal];
    box.className = "decision-banner decision-condemn";
    box.innerHTML = `<b>Do not repair — condemned</b>The customer does not want this machine repaired. Stop work on it.
       <span class="decision-who">${d ? escapeHtml(d) + " · " : ""}Decided by${who}${when}</span>`;
  }
  box.style.display = "block";
}

// The buttons that move THIS machine along. Which ones show depends only on
// where the machine is, so a technician is never offered a step that makes no
// sense from here.
function renderMachineQuoteRow() {
  const row = $("mm-quote-row");
  if (!row) return;
  const m = currentMachine();
  const slipStatus = session.slip ? session.slip.status : "";
  // A closed or fully billed slip has left all of this behind.
  const live = slipStatus !== "CLOSED" && slipStatus !== "CONVERTED";
  if (!m || !live || m.converted_at) { row.style.display = "none"; return; }

  const state = $("mm-quote-state");
  const btns = $("mm-quote-btns");
  row.style.display = "flex";

  // Sales and Admin ring the customer, so they get the answer buttons. A
  // technician can send a machine for quoting and take it back, which is the
  // part of this that is theirs.
  const decide = canDecide();
  let text, actions;
  if (m.state === "AWAITING_QUOTE") {
    text = `<span class="machine-quote mq-need">Waiting to quote</span> Sales have been told about this machine.`;
    actions = [["TO_REPAIR", "Undo — no quote needed", "btn-secondary"]];
    if (decide) actions.unshift(["QUOTED", "Mark as quoted", "btn-secondary"]);
  } else if (m.state === "QUOTED") {
    text = `<span class="machine-quote mq-done">Waiting on customer</span> Quoted; waiting for their answer.`;
    actions = decide
      ? [["TO_REPAIR", "They said go ahead", "btn-secondary"],
         ["CONDEMNED", "They said no — condemn", "btn-secondary"]]
      : [["AWAITING_QUOTE", "Send for quoting again", "btn-secondary"]];
  } else if (m.state === "TO_REPAIR") {
    text = `<span class="machine-quote mq-repair">Repair confirmed</span> Carry on with the repair.`;
    actions = [["AWAITING_QUOTE", "Send for quoting", "btn-secondary"]];
    if (canMarkRepaired()) actions.unshift(["REPAIRED", "Mark as repaired", "btn-secondary"]);
  } else if (m.state === "REPAIRED") {
    text = `<span class="machine-quote mq-repaired">Repaired</span> Finished — waiting for Sales to invoice it.`;
    // Always reversible, and by anyone who could tick it. A tick that could not
    // be taken back would be a machine stuck as finished on a slip that has
    // left nobody able to say otherwise.
    actions = canMarkRepaired()
      ? [["TO_REPAIR", "Not finished after all", "btn-secondary"]]
      : [];
  } else if (m.state === "CONDEMNED") {
    const d = DISPOSAL_LABEL[m.disposal];
    text = `<span class="machine-quote mq-condemn">Condemned</span> <span>${escapeHtml(
      d || "Still here — record where it goes before the slip can close.")}</span>`;
    actions = [["TO_REPAIR", "Repair it after all", "btn-secondary"]];
  } else {
    text = "This machine has not been sent for quoting.";
    actions = [["AWAITING_QUOTE", "Send this machine for quoting", "btn-secondary"]];
    // A machine nobody needed to quote for is repaired straight from here.
    if (canMarkRepaired()) actions.unshift(["REPAIRED", "Mark as repaired", "btn-secondary"]);
  }

  state.innerHTML = text;
  btns.innerHTML = actions.map(([to, label, cls]) =>
    `<button type="button" class="${cls}" data-to="${escapeAttr(to)}">${escapeHtml(label)}</button>`).join("");
  btns.querySelectorAll("[data-to]").forEach((b) =>
    b.addEventListener("click", () => moveMachine(b, b.dataset.to)));

  // Where a condemned machine went. Asked here because this is the screen
  // someone is on when the customer turns up for it.
  if (m.state === "CONDEMNED") {
    btns.insertAdjacentHTML("beforeend", `
      <div class="mm-disposal">
        <div class="mm-disposal-q">What happened to it?</div>
        <button type="button" class="btn-secondary" data-disposal="COLLECTED"${m.disposal === "COLLECTED" ? " disabled" : ""}>Customer collected it</button>
        <button type="button" class="btn-secondary" data-disposal="DISPOSED"${m.disposal === "DISPOSED" ? " disabled" : ""}>We disposed of it</button>
      </div>`);
    btns.querySelectorAll("[data-disposal]").forEach((b) =>
      b.addEventListener("click", () => recordDisposal(b, m.id, b.dataset.disposal)));
  }
}

async function moveMachine(btn, to) {
  const m = currentMachine();
  if (!m || !session.slipNumber) return;

  // Anything scanned but not yet saved would otherwise be missing from the very
  // quote this is asking for.
  if (to === "AWAITING_QUOTE" && session.pendingParts.length) {
    try {
      await commitPendingParts();
      await saveCurrentLabour();
      await saveCurrentComment();
    } catch (e) { toast(e.message, "err"); return; }
  }
  if (to === "CONDEMNED" && !confirm(
    "Condemn this machine?\n\nThe technicians who worked on it will be told to stop."
  )) return;

  btn.disabled = true;
  try {
    await api(`/api/slips/${encodeURIComponent(session.slipNumber)}/machines/${m.id}/state`, {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ state: to, who: initialsFor(getUser()) }),
    });
    await refreshSlip();
    renderMachineParts();
    renderMachineQuoteRow();
    renderMachineDecisionBanner();
    updateSlipFooter();
    refreshQuoteCount();
    toast(MOVE_TOAST[to] || "Saved", "ok");
  } catch (e) {
    toast(e.message, "err");
    btn.disabled = false;
  }
}

const MOVE_TOAST = {
  AWAITING_QUOTE: "Sent for quoting",
  QUOTED: "Marked as quoted",
  REPAIRED: "Marked as repaired",
  TO_REPAIR: "Repair confirmed",
  CONDEMNED: "Condemned — technician notified",
};

async function recordDisposal(btn, machineId, disposal) {
  btn.disabled = true;
  try {
    await api(`/api/slips/${encodeURIComponent(session.slipNumber)}/machines/${machineId}/disposal`, {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ disposal, who: initialsFor(getUser()) }),
    });
    await refreshSlip();
    renderMachineQuoteRow();
    renderMachineDecisionBanner();
    updateSlipFooter();
    toast(DISPOSAL_LABEL[disposal], "ok");
  } catch (e) {
    toast(e.message, "err");
    btn.disabled = false;
  }
}

// ---- Slip status UI (Open Service) ------------------------------------------
// Shows the current status as a badge next to the slip number, and decides
// which manual status buttons apply:
//   OPEN / IN_PROGRESS  -> [Need to Quote] [No quote needed]
//   NEED_QUOTE          -> [Mark as Quoted] [No quote needed]
//   QUOTED              -> [No quote needed]  (returns to In Progress)
//   ALL_REPAIRED/CLOSED -> no buttons
function renderSlipStatusUI() {
  const status = session.slip ? session.slip.status : "";
  const badge = $("os-status-badge");
  if (badge) {
    badge.textContent = STATUS_LABEL[status] || status || "—";
    badge.className = "vs-status vs-" + status;
  }
  const wrap = $("os-status-actions");
  if (!wrap) return;
  const machines = (session.slip && session.slip.machines) || [];
  const live = status === "OPEN" || status === "IN_PROGRESS" ||
               status === "NEED_QUOTE" || status === "QUOTED";
  // Machines are sent for quoting one at a time, so this button is the "all of
  // them together" case: offered while any machine is still not waiting.
  const someLeft = machines.some((m) => m.state !== "AWAITING_QUOTE" && !m.converted_at);
  const showQuote = live && someLeft;
  const showQuoted = status === "NEED_QUOTE";
  const showNoQuote = live;
  const quoteBtn = $("os-need-quote");
  quoteBtn.textContent = machines.length > 1
    ? (status === "NEED_QUOTE" ? "Quote the rest too" : "Quote all machines")
    : "Need to Quote";
  quoteBtn.style.display = showQuote ? "inline-flex" : "none";
  $("os-mark-quoted").style.display = showQuoted ? "inline-flex" : "none";
  $("os-no-quote").style.display = showNoQuote ? "inline-flex" : "none";
  wrap.style.display = (showQuote || showQuoted || showNoQuote) ? "flex" : "none";
}

// The slip-wide buttons move every machine at once. They post the same states
// as the per-machine buttons, to the same model - "all of them" is the only
// difference.
async function changeSlipStatus(newState, confirmMsg) {
  if (!session.slipNumber) return;
  try {
    await api(`/api/slips/${encodeURIComponent(session.slipNumber)}/state`, {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ state: newState, who: initialsFor(getUser()) }),
    });
    await refreshSlip();
    updateSlipFooter();
    toast(confirmMsg, "ok");
  } catch (e) {
    toast(e.message, "err");
  }
}

$("os-need-quote").addEventListener("click", () => changeSlipStatus("AWAITING_QUOTE", "Sent for quoting"));
$("os-mark-quoted").addEventListener("click", () => changeSlipStatus("QUOTED", "Marked as quoted"));
$("os-no-quote").addEventListener("click", () => {
  const s = session.slip ? session.slip.status : "";
  if (s === "NEED_QUOTE" || s === "QUOTED") {
    changeSlipStatus("TO_REPAIR", "Continuing without quote");
  } else {
    toast("No quote needed — carry on", "ok");
  }
});

// An order that did not reach AutoCount must not sit unnoticed. The toast that
// reported it lasts four seconds; this stays until the order is sent.
async function renderAutoCountPending() {
  const box = $("os-ac-pending");
  if (!box || !session.slip) return;
  let waiting = [];
  try {
    const r = await api("/api/orders/awaiting-autocount");
    const mine = `S/S: ${session.slip.slip_number}`;
    waiting = (r.orders || []).filter((o) => o.notes === mine);
  } catch (_) {
    box.style.display = "none";
    return;
  }
  if (!waiting.length) { box.style.display = "none"; box.innerHTML = ""; return; }

  box.style.display = "block";
  box.innerHTML = waiting.map((o) => `
    <div class="ac-pending-row" data-so="${escapeAttr(o.so_number)}">
      <div class="ac-pending-main">
        <strong>${escapeHtml(o.so_number)} is not in AutoCount</strong>
        <span>${escapeHtml(o.autocount_error || "It has not been sent yet.")}</span>
      </div>
      <button type="button" class="ac-retry" data-retry="${escapeAttr(o.so_number)}">Send to AutoCount</button>
    </div>`).join("");

  box.querySelectorAll(".ac-retry").forEach((b) =>
    b.addEventListener("click", async () => {
      b.disabled = true;
      const was = b.textContent;
      b.textContent = "Sending…";
      try {
        const r = await api(`/api/orders/${encodeURIComponent(b.dataset.retry)}/push-to-autocount`, { method: "POST" });
        if (r.pushed) toast(`Written into AutoCount as ${r.doc_no}`, "ok");
        else toast(r.reason || "Still could not write it.", "err");
      } catch (e) {
        toast(e.message, "err");
      }
      b.disabled = false;
      b.textContent = was;
      await refreshSlip();
      renderAutoCountPending();
    })
  );
}

// Ask which machines go on this order. A slip is converted a machine at a
// time, so this is the normal case rather than a special one.
function openConvertPicker() {
  if (!session.slip) return;
  const machines = session.slip.machines || [];
  const left = machines.filter((m) => !m.converted_at);
  if (!left.length) {
    toast("Every machine on this slip is already on a Sales Order.", "ok");
    return;
  }
  $("conv-sub").textContent = `Slip ${session.slip.slip_number} · ${session.slip.company}`;
  $("conv-status").innerHTML = "";
  // Reset here rather than on each exit path: a slip is converted several
  // times over, and a button left disabled by the previous run is silent -
  // the click simply does nothing and nobody can tell why.
  $("conv-go").disabled = false;
  $("conv-list").innerHTML = machines.map((m) => {
    const done = !!m.converted_at;
    const parts = (m.parts || []).length;
    const labour = Number(m.labour_charge) || 0;
    const billable = parts > 0 || labour > 0 || String(m.repair_comment || "").trim();
    const sub = done
      ? `On ${escapeHtml(m.so_number || "a Sales Order")}`
      : billable
        ? `${parts} part${parts === 1 ? "" : "s"}${labour > 0 ? " · labour " + money(labour) : ""}`
        : "No work recorded yet";
    return `
      <label class="conv-row${done ? " conv-done" : ""}${!done && !billable ? " conv-blocked" : ""}">
        <input type="checkbox" value="${m.id}" ${done || !billable ? "disabled" : "checked"}>
        <span class="conv-main">
          <span class="conv-name">${escapeHtml(m.machine_desc)}</span>
          ${m.serial_no ? `<span class="conv-serial">S/N ${escapeHtml(m.serial_no)}</span>` : ""}
          <span class="conv-sub">${sub}</span>
        </span>
      </label>`;
  }).join("");
  $("conv-modal").style.display = "flex";
  document.body.style.overflow = "hidden";
}

// ---- Printing for the paper slip -------------------------------------------
// The workshop runs the app and a paper service slip side by side, and the
// paper copy is where the parts get written out by hand. That is where a
// 848F6B12C0 turns into a 848F6B12CO. This prints what the app already knows
// so it can be cut out and stuck on.
//
// A5 rather than A4: it is close to the paper slip's own size, cuts down to a
// strip without a lot of waste, and prints on A4 without anyone changing a
// setting. Sized for sticking on, not for filing.
function openPrintPicker() {
  const slip = session.slip;
  if (!slip || !slip.machines || !slip.machines.length) return;
  $("pr-sub").textContent = `Slip ${slip.slip_number} · ${slip.company}`;
  $("pr-status").innerHTML = "";
  $("pr-list").innerHTML = slip.machines.map((m) => {
    const parts = m.parts || [];
    const labour = Number(m.labour_charge) || 0;
    let total = labour;
    for (const p of parts) total += p.unit_price * p.quantity;
    const bits = [];
    bits.push(`${parts.length} part${parts.length === 1 ? "" : "s"}`);
    if (labour > 0) bits.push(`labour ${money(labour)}`);
    // A machine nobody has touched prints as an empty box, which is worth
    // saying before they tick it rather than after they have printed it.
    const worked = parts.length > 0 || labour > 0 || String(m.repair_comment || "").trim();
    return `
      <label class="conv-row">
        <input type="checkbox" value="${m.id}" ${worked ? "checked" : ""}>
        <span class="conv-main">
          <span class="conv-name">${escapeHtml(m.machine_desc)}</span>
          ${m.serial_no ? `<span class="conv-serial">S/N ${escapeHtml(m.serial_no)}</span>` : ""}
          <span class="conv-sub">${worked ? escapeHtml(bits.join(" · ") + " · " + money(total)) : "Nothing recorded yet"}</span>
        </span>
      </label>`;
  }).join("");
  $("pr-modal").style.display = "flex";
  document.body.style.overflow = "hidden";
}

function closePrintPicker() {
  $("pr-modal").style.display = "none";
  document.body.style.overflow = "";
}

function buildMachinePrintPdf(slip, machines) {
  const { jsPDF } = window.jspdf;
  const doc = new jsPDF({ unit: "pt", format: "a5" });
  const LEFT = 30, RIGHT = 390, W = RIGHT - LEFT, BOTTOM = 565;
  const INK = 26, MUTED = 110, RULE = 205;
  let y = 34;

  const need = (h) => { if (y + h > BOTTOM) { doc.addPage(); y = 34; } };
  const rule = () => { doc.setDrawColor(RULE); doc.setLineWidth(0.6); doc.line(LEFT, y, RIGHT, y); y += 9; };

  // Header: enough to identify the slip when it is stuck on the paper one.
  doc.setFont("helvetica", "bold"); doc.setFontSize(13); doc.setTextColor(INK);
  doc.text(`Slip ${slip.slip_number}`, LEFT, y);
  doc.setFont("helvetica", "normal"); doc.setFontSize(9); doc.setTextColor(MUTED);
  doc.text(formatDate(slip.created_at) || "", RIGHT, y, { align: "right" });
  y += 14;
  doc.setFontSize(10); doc.setTextColor(INK);
  doc.text(doc.splitTextToSize(slip.company || "", W), LEFT, y);
  y += 14;
  rule();

  let grand = 0;
  for (const m of machines) {
    const parts = m.parts || [];
    const labour = Number(m.labour_charge) || 0;
    let total = labour;
    for (const p of parts) total += p.unit_price * p.quantity;
    grand += total;

    need(46);
    doc.setFont("helvetica", "bold"); doc.setFontSize(10.5); doc.setTextColor(INK);
    doc.text(doc.splitTextToSize(m.machine_desc || "", W), LEFT, y);
    y += 13;
    if (m.serial_no) {
      doc.setFont("helvetica", "normal"); doc.setFontSize(8.5); doc.setTextColor(MUTED);
      doc.text(`S/N ${m.serial_no}`, LEFT, y); y += 11;
    }

    if (parts.length) {
      // Part number, description, quantity, cost per item, line amount - the
      // five John asked for. Quantity is not on his list but stays: without it
      // "SCREW $0.90" against a $9.90 line does not reconcile, and reconciling
      // against the invoice is what the sheet is for.
      const CODE = LEFT, DESC = LEFT + 88, QTY = RIGHT - 122, UNIT = RIGHT - 62, AMT = RIGHT;
      doc.setFont("helvetica", "bold"); doc.setFontSize(7.4); doc.setTextColor(MUTED);
      doc.text("PART", CODE, y); doc.text("DESCRIPTION", DESC, y);
      doc.text("QTY", QTY, y, { align: "right" });
      doc.text("UNIT", UNIT, y, { align: "right" });
      doc.text("AMOUNT", AMT, y, { align: "right" });
      // Rule under the heading, then clear air before the first row. Drawn
      // after advancing it landed inside the first line's ascenders and struck
      // through the part number - the one thing on here that must be legible.
      y += 4;
      doc.setDrawColor(RULE); doc.setLineWidth(0.5); doc.line(LEFT, y, RIGHT, y);
      y += 10;
      doc.setFont("helvetica", "normal"); doc.setFontSize(8.6); doc.setTextColor(INK);
      for (const p of parts) {
        const desc = doc.splitTextToSize(p.description || "", QTY - DESC - 10);
        const h = Math.max(11, desc.length * 10);
        need(h + 4);
        doc.text(String(p.item_code || ""), CODE, y);
        doc.text(desc, DESC, y);
        doc.text(String(p.quantity), QTY, y, { align: "right" });
        doc.text(money(p.unit_price), UNIT, y, { align: "right" });
        doc.text(money(p.unit_price * p.quantity), AMT, y, { align: "right" });
        y += h;
      }
    }
    if (labour > 0) {
      need(13);
      doc.setFont("helvetica", "normal"); doc.setFontSize(8.6); doc.setTextColor(INK);
      doc.text("Labour", LEFT, y);
      doc.text(money(labour), RIGHT, y, { align: "right" });
      y += 12;
    }
    if (String(m.repair_comment || "").trim()) {
      const note = doc.splitTextToSize(m.repair_comment.trim(), W);
      need(note.length * 9 + 6);
      doc.setFontSize(8); doc.setTextColor(MUTED);
      doc.text(note, LEFT, y); y += note.length * 9 + 2;
    }
    if (!parts.length && labour <= 0) {
      need(13);
      doc.setFontSize(8.6); doc.setTextColor(MUTED);
      doc.text("No parts or labour recorded.", LEFT, y); y += 12;
    }

    need(16);
    doc.setFont("helvetica", "bold"); doc.setFontSize(9.4); doc.setTextColor(INK);
    doc.text("Machine total", LEFT, y);
    doc.text(money(total), RIGHT, y, { align: "right" });
    y += 12;
    rule();
  }

  // Only worth a grand total when there is more than one machine on the sheet.
  if (machines.length > 1) {
    need(20);
    doc.setFont("helvetica", "bold"); doc.setFontSize(11); doc.setTextColor(INK);
    doc.text(`Total — ${machines.length} machines`, LEFT, y);
    doc.text(money(grand), RIGHT, y, { align: "right" });
    y += 16;
  }

  doc.setFont("helvetica", "normal"); doc.setFontSize(7); doc.setTextColor(MUTED);
  doc.text("Printed from OM Service · workshop copy", LEFT, BOTTOM + 14);
  return doc.output("blob");
}

async function makeMachinePrintout() {
  const chosen = [...document.querySelectorAll("#pr-list input:checked")].map((c) => Number(c.value));
  if (!chosen.length) {
    $("pr-status").innerHTML = statusErr("Pick at least one machine.");
    return;
  }
  $("pr-go").disabled = true;
  $("pr-status").innerHTML = statusInfo("Preparing…");
  try {
    // Whatever is typed but unsaved on the open machine belongs on the paper
    // too, or the printout is behind the screen it was made from.
    await saveCurrentComment();
    const slip = await api(`/api/slips/${encodeURIComponent(session.slipNumber)}`);
    session.slip = slip;
    const machines = slip.machines.filter((m) => chosen.includes(m.id));
    const blob = buildMachinePrintPdf(slip, machines);
    // Same delivery as the customer slip: the phone's own share sheet where it
    // exists, so it can go straight to a printer or to whoever has one, and a
    // plain download everywhere else.
    await deliverPdf(blob, `Slip-${slip.slip_number}-workshop.pdf`,
                     `Slip ${slip.slip_number} — workshop copy`);
    closePrintPicker();
    $("pr-status").innerHTML = "";
  } catch (e) {
    $("pr-status").innerHTML = statusErr(e.message || "Could not make the printout");
  }
  $("pr-go").disabled = false;
}

function closeConvertPicker() {
  $("conv-modal").style.display = "none";
  document.body.style.overflow = "";
}

async function createSalesOrder() {
  if (!session.slipNumber) return;
  const chosen = [...document.querySelectorAll("#conv-list input:checked")].map((c) => Number(c.value));
  if (!chosen.length) {
    $("conv-status").innerHTML = statusErr("Pick at least one machine.");
    return;
  }
  $("conv-go").disabled = true;
  $("os-create-so").disabled = true;
  // Persist the current machine's comment first (per the agreed save-on-SO behaviour).
  await saveCurrentComment();
  try {
    const result = await api(`/api/slips/${encodeURIComponent(session.slipNumber)}/order`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ machine_ids: chosen }),
    });
    closeConvertPicker();

    // Say plainly whether it reached AutoCount. A silent failure here is the
    // worst outcome: staff would believe the order exists and only find out
    // when they went looking for it.
    const ac = result.autocount || {};
    if (ac.pushed) {
      // The app has taken AutoCount's number, so there is only one to report.
      setTimeout(() => toast(
        ac.rename_note
          ? `In AutoCount as ${ac.doc_no} (the app kept ${result.so_number}: ${ac.rename_note})`
          : `Written into AutoCount as Sales Order ${ac.doc_no}`,
        ac.rename_note ? "err" : "ok"), 1600);
    } else if (ac.error) {
      setTimeout(() => toast(`NOT written to AutoCount: ${ac.error}`, "err"), 1600);
    } else if (ac.reason && !/switched off|not enabled/i.test(ac.reason)) {
      setTimeout(() => toast(`Not written to AutoCount: ${ac.reason}`, "err"), 1600);
    }

    const left = result.machines_remaining;
    toast(
      left === 0
        ? `Sales Order ${result.so_number} created — slip is now Converted`
        : `Sales Order ${result.so_number} created — ${left} machine${left === 1 ? "" : "s"} still to convert`,
      "ok"
    );
    // Straight into the keyable block — this is the moment it gets typed into
    // AutoCount, so don't make anyone go looking for it.
    showSlipOrder(session.slipNumber);
    // Report price write-back outcome (prices saved into AutoCount for parts
    // that previously had none). Failures are non-blocking but flagged.
    const ps = result.price_sync;
    if (ps && ps.failed && ps.failed.length) {
      setTimeout(() => toast(`Price save to AutoCount failed for: ${ps.failed.join(", ")}`, "err"), 1800);
      setTimeout(async () => { await refreshSlip(); renderSlipScreen(); }, 4200);
    } else if (ps && ps.updated && ps.updated.length) {
      setTimeout(() => toast(`${ps.updated.length} price${ps.updated.length === 1 ? "" : "s"} saved to AutoCount`, "ok"), 1800);
      setTimeout(async () => { await refreshSlip(); renderSlipScreen(); }, 3600);
    } else {
      setTimeout(async () => { await refreshSlip(); renderSlipScreen(); }, 1600);
    }
  } catch (e) {
    toast(e.message, "err");
    $("os-create-so").disabled = false;
    $("conv-go").disabled = false;
  }
}

// ============================================================================
// CLOSE SERVICE
// ============================================================================
let closeSearch = null;
let csPickedSlip = null; // currently selected slip number in Close Service
async function enterCloseService() {
  showScreen("close");
  $("cs-context").style.display = "none";
  $("cs-ref").value = "";
  $("cs-status").innerHTML = "";
  csPickedSlip = null;

  if (!closeSearch) {
    closeSearch = setupSlipSearch({
      inputId: "cs-search", resultsId: "cs-results", scope: "repaired",
      onPick: (slipNumber) => onCloseSlipChosen(slipNumber),
    });
  }
  closeSearch.reset();
}

async function onCloseSlipChosen(slipNumber) {
  csPickedSlip = slipNumber || null;
  if (!slipNumber) { $("cs-context").style.display = "none"; return; }
  try {
    const slip = await api(`/api/slips/${encodeURIComponent(slipNumber)}`);
    $("cs-context").style.display = "block";
    // A condemned machine still in the workshop stops the slip closing. Say so
    // here, on the screen where someone is about to try, rather than only
    // refusing once they have typed the DO number.
    const stranded = (slip.machines || []).filter(
      (m) => m.state === "CONDEMNED" && !String(m.disposal || "").trim()
    );
    $("cs-context").innerHTML =
      `<div><strong>${escapeHtml(slip.company)}</strong> · Slip ${escapeHtml(slip.slip_number)}</div>` +
      `<div class="sub">Status: ${escapeHtml(STATUS_LABEL[slip.status] || slip.status)} · ${slip.machines.length} machine(s)</div>` +
      (formatDate(slip.created_at) ? `<div class="sub">Created: ${escapeHtml(formatDate(slip.created_at))}</div>` : "") +
      (stranded.length ? `<div class="cs-blocked"><b>Cannot close yet</b>${
        escapeHtml(stranded.map((m) => m.machine_desc).join(", "))} ${
        stranded.length === 1
          ? "was condemned and is still here. Record where it went under View Slips first."
          : "were condemned and are still here. Record where each one went under View Slips first."
      }</div>` : "");
  } catch (e) {
    toast(e.message, "err");
  }
}

async function submitClose() {
  const slipNumber = csPickedSlip;
  const ref = $("cs-ref").value.trim();
  if (!slipNumber) { $("cs-status").innerHTML = statusErr("Pick a slip to close."); return; }
  if (!ref) { $("cs-status").innerHTML = statusErr("Enter the DO/CS/INV number."); return; }

  $("cs-submit").disabled = true;
  $("cs-status").innerHTML = statusInfo("Closing…");
  try {
    await api(`/api/slips/${encodeURIComponent(slipNumber)}/close`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ closing_ref: ref }),
    });
    toast(`Slip ${slipNumber} closed`, "ok");
    $("cs-status").innerHTML = statusOk(`Closed ${slipNumber}. Returning home…`);
    setTimeout(goHome, 1400);
  } catch (e) {
    $("cs-status").innerHTML = statusErr(e.message);
  } finally {
    $("cs-submit").disabled = false;
  }
}

// ============================================================================
// VIEW SLIPS (read-only)
// ============================================================================
let viewSearch = null;
async function enterViewSlips() {
  showScreen("view");
  $("vs-detail").innerHTML = "";
  if (!viewSearch) {
    viewSearch = setupSlipSearch({
      inputId: "vs-search", resultsId: "vs-results", scope: "all",
      onPick: (slipNumber) => onViewSlipChosen(slipNumber),
    });
  }
  viewSearch.reset();
}

async function onViewSlipChosen(slipNumber) {
  const wrap = $("vs-detail");
  if (!slipNumber) { wrap.innerHTML = ""; return; }
  wrap.innerHTML = `<div class="slip-context"><span class="led"></span> Loading…</div>`;
  try {
    const slip = await api(`/api/slips/${encodeURIComponent(slipNumber)}`);
    wrap.innerHTML = renderSlipDetail(slip);
    wireVsStatusActions(slipNumber);
    wireDecideButtons(wrap, slipNumber);
    const editBtn = document.getElementById("vs-edit");
    if (editBtn) editBtn.addEventListener("click", () => openSlipEdit(slip));
    // Rebuilt from the stored slip, so a re-issued copy matches the original.
    const share = document.getElementById("vs-share");
    if (share) share.addEventListener("click", () => shareSlipPdf(slip));
    wireContactActions(wrap, slip);
    if (share) {
      whatsappStatus().then((wa) => {
        if (!wa.enabled || !wa.configured) return;
        const btn = document.createElement("button");
        btn.className = "btn-secondary wa-send";
        btn.type = "button";
        btn.style.cssText = "width:100%;margin-top:8px;";
        btn.textContent = "Send to customer on WhatsApp";
        share.insertAdjacentElement("afterend", btn);
        // Never automatic here - this screen is opened to look at old slips,
        // and re-sending one just because it was viewed would be alarming.
        wireWhatsappButton(btn, slip, { auto: false });
      });
    }
    const soBtn = document.getElementById("vs-so");
    if (soBtn) soBtn.addEventListener("click", () => showSlipOrder(slip.slip_number));
  } catch (e) {
    wrap.innerHTML = "";
    toast(e.message, "err");
  }
}

// The same manual status buttons as Open Service, rendered in the View Slips
// detail so sales can manage quoting from here too.
function renderVsStatusActions(slip) {
  const s = slip.status;
  const showQuote = s === "OPEN" || s === "IN_PROGRESS";
  const showQuoted = s === "NEED_QUOTE";
  const showNoQuote = showQuote || showQuoted || s === "QUOTED";
  if (!showQuote && !showQuoted && !showNoQuote) return "";
  return `<div class="status-actions">
    ${showQuote ? `<button class="status-btn status-btn-quote" data-vs-state="AWAITING_QUOTE">Need to Quote</button>` : ""}
    ${showQuoted ? `<button class="status-btn status-btn-quoted" data-vs-state="QUOTED">Mark as Quoted</button>` : ""}
    ${showNoQuote ? `<button class="status-btn status-btn-noquote" data-vs-state="NO_QUOTE">No quote needed</button>` : ""}
  </div>`;
}

// These move every machine on the slip at once. The per-machine buttons below
// are the same model applied to one.
function wireVsStatusActions(slipNumber) {
  document.querySelectorAll("#vs-detail [data-vs-state]").forEach((btn) =>
    btn.addEventListener("click", async () => {
      const action = btn.dataset.vsState;
      // "No quote needed" means "stop waiting, get on with it" - which is
      // TO_REPAIR - and means nothing on a slip that was never waiting.
      const slip = action === "NO_QUOTE"
        ? await api(`/api/slips/${encodeURIComponent(slipNumber)}`) : null;
      if (action === "NO_QUOTE" && slip.status !== "NEED_QUOTE" && slip.status !== "QUOTED") {
        toast("No quote needed — carry on", "ok");
        return;
      }
      const state = action === "NO_QUOTE" ? "TO_REPAIR" : action;
      try {
        await api(`/api/slips/${encodeURIComponent(slipNumber)}/state`, {
          method: "PATCH",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ state, who: initialsFor(getUser()) }),
        });
        toast(state === "AWAITING_QUOTE" ? "Sent for quoting"
            : state === "QUOTED" ? "Marked as quoted"
            : "Continuing without quote", "ok");
        onViewSlipChosen(slipNumber); // re-render with the new status
        refreshQuoteCount();
      } catch (e) {
        toast(e.message, "err");
      }
    })
  );
}

function renderSlipDetail(slip) {
  // Header block: customer + meta
  let slipQty = 0, slipAmount = 0, slipParts = 0, slipLabour = 0;
  for (const m of slip.machines) {
    for (const p of (m.parts || [])) { slipQty += p.quantity; slipAmount += p.unit_price * p.quantity; slipParts++; }
    slipLabour += Number(m.labour_charge) || 0;
  }
  slipAmount += slipLabour;

  const meta = [];
  if (slip.contact_name) meta.push(`Contact: ${escapeHtml(slip.contact_name)}`);
  if (slip.contact_number) meta.push(escapeHtml(slip.contact_number));

  let html = `
    <div class="vs-card">
      <div class="vs-head">
        <div>
          <div class="vs-company">${escapeHtml(slip.company)}</div>
          <div class="vs-sub">Slip ${escapeHtml(slip.slip_number)} · Created ${escapeHtml(formatDate(slip.created_at))}${
            slip.created_by ? ` · Registered by ${escapeHtml(slip.created_by)}` : ""}</div>
        </div>
        <span class="vs-status vs-${escapeAttr(slip.status)}">${escapeHtml(STATUS_LABEL[slip.status] || slip.status)}</span>
      </div>
      ${meta.length ? `<div class="vs-sub">${meta.join(" · ")}</div>` : ""}
      ${(slip.amendments || []).length ? `<div class="vs-amended"><b>Changed after the customer signed</b>${
        slip.amendments.map((a) => `<div>${escapeHtml(a.field)}: &ldquo;${escapeHtml(a.before || "—")}&rdquo; &rarr; &ldquo;${escapeHtml(a.after || "—")}&rdquo;${
          a.changed_by ? ` · ${escapeHtml(a.changed_by)}` : ""}${a.changed_at ? ` · ${escapeHtml(String(a.changed_at).slice(0, 10))}` : ""}</div>`).join("")
      }</div>` : ""}
      ${requestBadgesHtml(slip, "vs")}
      ${slip.notes ? `<div class="vs-notes">${escapeHtml(slip.notes)}</div>` : ""}
      ${slip.status === "CLOSED" && slip.closing_ref ? `<div class="vs-sub">Closed with: <strong>${escapeHtml(slip.closing_ref)}</strong>${slip.closed_at ? " on " + escapeHtml(formatDate(slip.closed_at)) : ""}</div>` : ""}
      ${renderVsStatusActions(slip)}
    </div>`;

  // Each machine + its parts
  for (const m of slip.machines) {
    const parts = m.parts || [];
    const mLabour = Number(m.labour_charge) || 0;
    let mQty = 0, mAmount = 0;
    for (const p of parts) { mQty += p.quantity; mAmount += p.unit_price * p.quantity; }
    mAmount += mLabour;

    const pill = machinePill(m);

    html += `
      <div class="vs-machine">
        <div class="vs-machine-name">${escapeHtml(m.machine_desc)}${pill}</div>`;

    // Sales quote the machine, ring the customer, and come back with one of two
    // answers. Each step is offered only from where the machine actually is,
    // and the step already taken stays on screen so it can be corrected.
    const live = slip.status !== "CLOSED" && !m.converted_at;
    if (canDecide() && live && m.state !== "RECEIVED") {
      const acts =
        m.state === "AWAITING_QUOTE" ? [["QUOTED", "Mark as Quoted", "decide-quoted"],
                                        ["TO_REPAIR", "No quote needed", ""]]
      : m.state === "QUOTED"         ? [["TO_REPAIR", "Confirm Repair", "decide-repair"],
                                        ["CONDEMNED", "Condemn", "decide-condemn"]]
      : m.state === "TO_REPAIR"      ? [["AWAITING_QUOTE", "Send for quoting", ""]]
      : m.state === "CONDEMNED"      ? [["TO_REPAIR", "Repair it after all", "decide-repair"]]
      : [];
      if (acts.length) {
        html += `<div class="decide-row" data-decide="${m.id}">${acts.map(([to, label, cls]) =>
          `<button type="button" class="decide-btn ${cls}" data-state="${escapeAttr(to)}">${escapeHtml(label)}</button>`
        ).join("")}</div>`;
      }
    }

    // Finished with. Its own row rather than folded into the decisions above,
    // for two reasons: a different set of people may tick it - the technician
    // who did the work included - and it applies from RECEIVED, where Sales
    // have no decision to make and the block above deliberately shows nothing.
    if (canMarkRepaired() && live) {
      const rep =
        m.state === "REPAIRED"                                  ? [["TO_REPAIR", "Not finished after all", ""]]
      : (m.state === "RECEIVED" || m.state === "TO_REPAIR")     ? [["REPAIRED", "Mark as repaired", "decide-repaired"]]
      : [];                       // waiting on a quote or condemned: not yet
      if (rep.length) {
        html += `<div class="decide-row" data-decide="${m.id}">${rep.map(([to, label, cls]) =>
          `<button type="button" class="decide-btn ${cls}" data-state="${escapeAttr(to)}">${escapeHtml(label)}</button>`
        ).join("")}</div>`;
      }
    }

    // A condemned machine is still in the workshop until somebody says where it
    // went, and the slip will not close until they do. Asked here, on the
    // screen sales are looking at when the customer rings about collecting it.
    // Not gated on canDecide, unlike the decisions above: where a machine went
    // is a fact rather than a customer's answer, the workshop often knows it
    // first, and the slip cannot close until somebody records it.
    if (live && m.state === "CONDEMNED") {
      html += `<div class="decide-row decide-disposal" data-dispose="${m.id}">
          <span class="decide-q">${m.disposal ? "Recorded:" : "Where did it go?"}</span>
          <button type="button" class="decide-btn"${m.disposal === "COLLECTED" ? " disabled" : ""} data-disposal="COLLECTED">Customer collected</button>
          <button type="button" class="decide-btn"${m.disposal === "DISPOSED" ? " disabled" : ""} data-disposal="DISPOSED">We disposed of it</button>
        </div>`;
    }
    html += `${m.serial_no ? `<div class="vs-machine-serial">S/N ${escapeHtml(m.serial_no)}</div>` : ""}${
      m.remarks ? `<div class="vs-machine-remarks">“${escapeHtml(m.remarks)}”</div>` : ""}`;

    if (m.repair_comment) {
      html += `<div class="vs-comment">${escapeHtml(m.repair_comment)}</div>`;
    }

    if (parts.length === 0 && !mLabour) {
      html += `<div class="vs-sub" style="padding:6px 0;">No parts recorded.</div>`;
    } else {
      if (parts.length === 0) {
        html += `<div class="vs-sub" style="padding:6px 0;">No parts recorded.</div>`;
      }
      for (const p of parts) {
        html += `
          <div class="vs-part">
            <div class="vs-part-info">
              <div class="vs-part-desc">${escapeHtml(p.description)}</div>
              <div class="vs-part-sku mono">${escapeHtml(p.item_code)}${p.technician ? " · " + escapeHtml(p.technician) : ""}</div>
            </div>
            <div class="vs-part-amt">
              <div>${escapeHtml(String(p.quantity))} × ${money(p.unit_price)}</div>
              <div class="vs-part-line">${money(p.unit_price * p.quantity)}</div>
            </div>
          </div>`;
      }
      if (mLabour) {
        html += `
          <div class="vs-part">
            <div class="vs-part-info">
              <div class="vs-part-desc">Labour Charge</div>
            </div>
            <div class="vs-part-amt">
              <div class="vs-part-line">${money(mLabour)}</div>
            </div>
          </div>`;
      }
      html += `<div class="vs-machine-total">Machine total: <strong>${money(mAmount)}</strong> (${mQty} qty)</div>`;
    }
    html += `</div>`;
  }

  // Slip total
  html += `
    <div class="vs-grand">
      <span>${slipParts} part${slipParts === 1 ? "" : "s"} · ${slipQty} qty across ${slip.machines.length} machine${slip.machines.length === 1 ? "" : "s"}${slipLabour ? ` · incl. ${money(slipLabour)} labour` : ""}</span>
      <strong>${money(slipAmount)}</strong>
    </div>`;

  // Re-issue the customer's copy — same PDF as registration, signature and all.
  html += `
    ${contactActionHtml(slip)}
    <button class="btn-primary" id="vs-share" type="button" style="margin-top:10px;">Share PDF</button>${
      canDecide() && slip.status !== "CLOSED"
        ? `<button class="btn-secondary" id="vs-edit" style="margin-top:10px;width:100%;">Edit slip</button>` : ""}`;

  // Once an order exists, the keyable AutoCount block stays reachable — sales
  // may key it in later, or need it again.
  if (slip.status === "ALL_REPAIRED" || slip.status === "CLOSED") {
    html += `
      <button class="btn-secondary" id="vs-so" style="margin-top:10px;width:100%;">View Sales Order</button>`;
  }

  return html;
}

// Moving a machine along from the sales screen, and telling the technician who
// did the work. Condemn is confirmed first: it tells someone to stop work on a
// machine, and it sits one tap away from Confirm Repair.
function wireDecideButtons(wrap, slipNumber) {
  wrap.querySelectorAll(".decide-row [data-state]").forEach((btn) => {
    btn.addEventListener("click", async () => {
      const row = btn.closest(".decide-row");
      const machineId = Number(row.dataset.decide);
      const state = btn.dataset.state;
      if (state === "CONDEMNED" && !confirm(
        "Condemn this machine?\n\nThe technicians who worked on it will be told to stop."
      )) return;

      row.querySelectorAll("button").forEach((b) => { b.disabled = true; });
      try {
        await api(`/api/slips/${encodeURIComponent(slipNumber)}/machines/${machineId}/state`, {
          method: "PATCH",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ state, who: initialsFor(getUser()) }),
        });
        toast(MOVE_TOAST[state] || "Saved", "ok");
        onViewSlipChosen(slipNumber);
        refreshQuoteCount();
      } catch (e) {
        toast(e.message || "Could not save that", "err");
        row.querySelectorAll("button").forEach((b) => { b.disabled = false; });
      }
    });
  });

  wrap.querySelectorAll(".decide-disposal [data-disposal]").forEach((btn) => {
    btn.addEventListener("click", async () => {
      const row = btn.closest(".decide-disposal");
      const machineId = Number(row.dataset.dispose);
      const disposal = btn.dataset.disposal;
      row.querySelectorAll("button").forEach((b) => { b.disabled = true; });
      try {
        await api(`/api/slips/${encodeURIComponent(slipNumber)}/machines/${machineId}/disposal`, {
          method: "PATCH",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ disposal, who: initialsFor(getUser()) }),
        });
        toast(DISPOSAL_LABEL[disposal], "ok");
        onViewSlipChosen(slipNumber);
      } catch (e) {
        toast(e.message || "Could not save that", "err");
        row.querySelectorAll("button").forEach((b) => { b.disabled = false; });
      }
    });
  });
}

// ---- Editing a slip's registration details -----------------------------------
// What was written at the counter can be wrong - a misspelt company, a serial
// read off the wrong plate. This fixes THAT: contacts, notes, machine names,
// serials and intake remarks. Parts, labour and status are the work and live
// in Open Service; a closed slip is a finished record and has no Edit button.
// Saving asks for confirmation with a summary of exactly what changes.
let vseSlip = null;

// What the fields started as, so a change can be marked the moment it is made
// rather than only listed once Save has been pressed.
function vseOriginal() {
  const m = {};
  for (const x of (vseSlip.machines || [])) {
    m[x.id] = { desc: x.machine_desc || "", code: x.machine_code || "",
                serial: (x.serial_no || "").trim(), remarks: (x.remarks || "").trim() };
  }
  return {
    company: vseSlip.company || "",
    contact_name: vseSlip.contact_name || "",
    contact_number: vseSlip.contact_number || "",
    whatsapp_number: vseSlip.whatsapp_number || "",
    notes: vseSlip.notes || "",
    machines: m,
  };
}

function openSlipEdit(slip) {
  vseSlip = slip;
  $("vse-sub").textContent = `Slip ${slip.slip_number} · ${slip.company}`;
  $("vse-company").value = slip.company || "";
  $("vse-contact-name").value = slip.contact_name || "";
  $("vse-contact-number").value = slip.contact_number || "";
  $("vse-whatsapp").value = slip.whatsapp_number || "";
  $("vse-notes").value = slip.notes || "";

  const machines = slip.machines || [];
  $("vse-machines-label").textContent =
    machines.length === 1 ? "Machine" : `Machines (${machines.length})`;

  // The card header keeps the name the machine was REGISTERED with, even while
  // the name field is being retyped. Retitling the card as someone types turns
  // the one fixed landmark on the screen into a moving one.
  $("vse-machines").innerHTML = machines.map((m, i) => `
    <div class="vse-card vse-machine" data-machine="${m.id}" data-code="${escapeAttr(m.machine_code || "")}">
      <div class="vse-m-head">
        <span class="vse-m-num">${i + 1}</span>
        <span class="vse-m-name">${escapeHtml(m.machine_desc)}</span>
        ${machinePill(m)}
      </div>
      <div class="vse-card-body">
        <div class="field" data-f="desc">
          <div class="vse-lab"><label>Machine <span class="req">*</span></label></div>
          <input class="vse-m-desc" type="text" value="${escapeAttr(m.machine_desc)}" />
          <div class="company-suggest vse-m-results"></div>
        </div>
        <!-- Which catalogue machine this is. Its own field rather than a note
             under the name, so that setting it on a slip whose wording is
             already right still counts as a change - otherwise Save would sit
             greyed out on exactly the correction this screen is for. -->
        <div class="field" data-f="code">
          <div class="vse-lab"><label>Catalogue item</label></div>
          <div class="vse-m-code"></div>
        </div>
        <div class="field" data-f="serial">
          <div class="vse-lab"><label>Serial No.</label></div>
          <input class="vse-m-serial" type="text" value="${escapeAttr(m.serial_no || "")}" />
        </div>
        <div class="field" data-f="remarks">
          <div class="vse-lab"><label>Remarks</label></div>
          <textarea class="vse-m-remarks" rows="2">${escapeHtml(m.remarks || "")}</textarea>
        </div>
      </div>
    </div>`).join("");

  vseRenderCodes();

  // Only a signed slip carries an amendment note, so only a signed slip says so.
  $("vse-signed").style.display = slip.has_signature ? "flex" : "none";

  $("vse-modal").style.display = "flex";
  document.body.style.overflow = "hidden";
  vseWatch();
  vseMarkAll();
}

// Every field reports itself as it is typed in, which keeps the Save button's
// count and the amber marks honest without re-reading the form on a timer.
function vseWatch() {
  const fields = [
    ...["vse-company", "vse-contact-name", "vse-contact-number", "vse-whatsapp", "vse-notes"].map((id) => $(id)),
    ...document.querySelectorAll("#vse-machines input, #vse-machines textarea"),
  ];
  for (const el of fields) {
    if (el.dataset.vseWired) continue;
    el.dataset.vseWired = "1";
    el.addEventListener("input", vseMarkAll);
  }
}

// A field that differs from what was registered is outlined and says what it
// was. At the counter with a customer waiting, that catches the typed-in-the-
// wrong-box mistake while it can still be undone by looking.
function vseMark(field, before, after) {
  if (!field) return false;
  const changed = before !== after;
  field.classList.toggle("vse-changed", changed);
  const lab = field.querySelector(".vse-lab") || field;
  let tag = lab.querySelector(".vse-chg");
  let was = field.querySelector(".vse-was");
  if (changed) {
    if (!tag) {
      tag = document.createElement("span");
      tag.className = "vse-chg";
      tag.textContent = "changed";
      lab.appendChild(tag);
    }
    if (!was) {
      was = document.createElement("div");
      was.className = "vse-was";
      field.appendChild(was);
    }
    was.textContent = before ? `was ${before}` : "was empty";
  } else {
    if (tag) tag.remove();
    if (was) was.remove();
  }
  return changed;
}

function vseMarkAll() {
  if (!vseSlip) return 0;
  const o = vseOriginal();
  let n = 0;
  const pairs = [
    ["vse-company", o.company], ["vse-contact-name", o.contact_name],
    ["vse-contact-number", o.contact_number], ["vse-whatsapp", o.whatsapp_number],
    ["vse-notes", o.notes],
  ];
  for (const [id, before] of pairs) {
    const el = $(id);
    if (vseMark(el.closest(".field"), before.trim(), el.value.trim())) n++;
  }
  document.querySelectorAll("#vse-machines .vse-machine").forEach((card) => {
    const was = o.machines[Number(card.dataset.machine)];
    if (!was) return;
    const get = (sel) => card.querySelector(sel).value.trim();
    if (vseMark(card.querySelector('[data-f="desc"]'), was.desc, get(".vse-m-desc"))) n++;
    if (vseMark(card.querySelector('[data-f="code"]'), was.code || "", card.dataset.code || "")) n++;
    if (vseMark(card.querySelector('[data-f="serial"]'), was.serial, get(".vse-m-serial"))) n++;
    if (vseMark(card.querySelector('[data-f="remarks"]'), was.remarks, get(".vse-m-remarks"))) n++;
  });

  // The button says what it will do. Nothing to save is a disabled button
  // rather than a button that answers "Nothing was changed" after a tap.
  const btn = $("vse-save");
  btn.disabled = n === 0;
  btn.textContent = n === 0 ? "Save changes"
                  : n === 1 ? "Save 1 change" : `Save ${n} changes`;
  return n;
}

// ---- Picking the catalogue machine while editing a slip ---------------------
// Same list as the Add machine form. It is here because the slips written
// before that existed are the ones with no catalogue item against them, and
// they are exactly the ones the app cannot reason about - a fogger it cannot
// recognise offers no tubes.
//
// The code lives on the card (data-code) rather than in a variable, because
// there is one per machine and the cards are rebuilt on every open.
function vseRenderCodes() {
  document.querySelectorAll("#vse-machines .vse-machine").forEach((card) => {
    const box = card.querySelector(".vse-m-code");
    if (!box) return;
    const code = card.dataset.code || "";
    box.innerHTML = code
      ? `<span class="mono">${escapeHtml(code)}</span>
         <button type="button" class="btn-quiet vse-m-clear">Not this one</button>`
      : `<span class="vse-m-nocode">Not from the catalogue — start typing the machine above to pick one</span>`;
  });
}

let vseModelDebounce = null;
$("vse-machines").addEventListener("input", (e) => {
  const input = e.target.closest(".vse-m-desc");
  if (!input) return;
  const card = input.closest(".vse-machine");
  const box = card.querySelector(".vse-m-results");
  // Typed by hand means this is no longer the catalogue machine - the same
  // rule as the Add machine form, for the same reason: what is on screen is
  // what gets saved, so a code left behind it would be a lie about the machine.
  card.dataset.code = "";
  vseRenderCodes();
  vseMarkAll();
  clearTimeout(vseModelDebounce);
  const q = input.value.trim();
  if (q.length < 2) { box.innerHTML = ""; return; }
  vseModelDebounce = setTimeout(async () => {
    try {
      const data = await api(`/api/machine-search?q=${encodeURIComponent(q)}`);
      const list = data.results || [];
      if (!list.length) { box.innerHTML = ""; return; }
      box.innerHTML = list.map(machineOptionHtml).join("");
    } catch (_) { box.innerHTML = ""; }
  }, 250);
});

$("vse-machines").addEventListener("click", (e) => {
  const opt = e.target.closest(".company-option");
  if (opt) {
    const card = opt.closest(".vse-machine");
    card.querySelector(".vse-m-desc").value = opt.dataset.desc;
    card.dataset.code = opt.dataset.code;
    card.querySelector(".vse-m-results").innerHTML = "";
    vseRenderCodes();
    vseMarkAll();
    return;
  }
  const clear = e.target.closest(".vse-m-clear");
  if (clear) {
    const card = clear.closest(".vse-machine");
    card.dataset.code = "";
    vseRenderCodes();
    vseMarkAll();
  }
});

function closeSlipEdit() {
  $("vse-modal").style.display = "none";
  $("vsr-modal").style.display = "none";
  document.body.style.overflow = "";
  vseSlip = null;
}
$("vse-close").addEventListener("click", closeSlipEdit);
$("vse-cancel").addEventListener("click", closeSlipEdit);

// What the form says now, against what was registered. One pass produces both
// the payload and the list a person reads, so the two cannot disagree.
function vseCollect() {
  const val = (id) => $(id).value.trim();
  const payload = {
    role: getRole(), who: initialsFor(getUser()),
    company: val("vse-company"),
    contact_name: val("vse-contact-name"),
    contact_number: val("vse-contact-number"),
    whatsapp_number: val("vse-whatsapp"),
    notes: val("vse-notes"),
    machines: [],
  };
  const o = vseOriginal();
  const groups = [];
  const customer = [];
  for (const [key, label] of [
    ["company", "Company"], ["contact_name", "Contact name"],
    ["contact_number", "Contact number"], ["whatsapp_number", "WhatsApp"],
    ["notes", "Notes"],
  ]) {
    if (o[key].trim() !== payload[key]) customer.push({ label, before: o[key].trim(), after: payload[key] });
  }
  if (customer.length) groups.push({ title: "Customer", rows: customer });

  let blank = false;
  document.querySelectorAll("#vse-machines .vse-machine").forEach((card) => {
    const id = Number(card.dataset.machine);
    const was = o.machines[id];
    const get = (sel) => card.querySelector(sel).value.trim();
    const desc = get(".vse-m-desc");
    if (!desc) { blank = true; return; }
    payload.machines.push({ id, machine_desc: desc, machine_code: card.dataset.code || "",
                            serial_no: get(".vse-m-serial"), remarks: get(".vse-m-remarks") });
    if (!was) return;
    const rows = [];
    if (was.desc !== desc) rows.push({ label: "Machine", before: was.desc, after: desc });
    // The catalogue item belongs in the review for the same reason it is
    // counted on the Save button: setting it on a slip whose wording is
    // already right is a real change, and the button's count and this list
    // are meant to be the same number.
    if ((was.code || "") !== (card.dataset.code || "")) {
      rows.push({ label: "Catalogue item", before: was.code || "", after: card.dataset.code || "" });
    }
    if (was.serial !== get(".vse-m-serial")) rows.push({ label: "Serial No.", before: was.serial, after: get(".vse-m-serial") });
    if (was.remarks !== get(".vse-m-remarks")) rows.push({ label: "Remarks", before: was.remarks, after: get(".vse-m-remarks") });
    // Named by what it was registered as, so the heading still matches the
    // machine when its name is the thing being corrected.
    if (rows.length) groups.push({ title: was.desc, rows });
  });

  return { payload, groups, blank, count: groups.reduce((n, g) => n + g.rows.length, 0) };
}

$("vse-save").addEventListener("click", () => {
  if (!vseSlip) return;
  const { payload, groups, blank, count } = vseCollect();
  if (!payload.company) { toast("Company cannot be empty", "err"); $("vse-company").focus(); return; }
  if (blank) { toast("A machine's description cannot be empty", "err"); return; }
  if (!count) { toast("Nothing was changed", "ok"); return; }

  $("vsr-sub").textContent =
    `Slip ${vseSlip.slip_number} · ${count === 1 ? "1 change" : count + " changes"}`;
  $("vsr-list").innerHTML = groups.map((g) => `
    <div class="vsr-group">
      <div class="vsr-group-title">${escapeHtml(g.title)}</div>
      ${g.rows.map((r) => `
        <div class="vsr-row">
          <div class="vsr-label">${escapeHtml(r.label)}</div>
          <div class="vsr-before">${escapeHtml(r.before || "—")}</div>
          <div class="vsr-after">${escapeHtml(r.after || "—")}</div>
        </div>`).join("")}
    </div>`).join("") +
    (vseSlip.has_signature
      ? `<div class="vse-signed vsr-note"><span aria-hidden="true">&#9998;</span>
           <span>This slip has been signed, so the change will be recorded on it.</span></div>`
      : "");
  $("vsr-confirm").disabled = false;
  $("vsr-confirm").textContent = count === 1 ? "Save 1 change" : `Save ${count} changes`;
  $("vsr-modal").style.display = "flex";
});

const vsrBack = () => { $("vsr-modal").style.display = "none"; };
$("vsr-back").addEventListener("click", vsrBack);
$("vsr-close").addEventListener("click", vsrBack);

$("vsr-confirm").addEventListener("click", async () => {
  if (!vseSlip) return;
  const { payload } = vseCollect();
  const btn = $("vsr-confirm");
  btn.disabled = true;
  try {
    await api(`/api/slips/${encodeURIComponent(vseSlip.slip_number)}/details`, {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload),
    });
    toast("Slip updated", "ok");
    const n = vseSlip.slip_number;
    closeSlipEdit();
    onViewSlipChosen(n);
  } catch (e) {
    toast(e.message || "Could not save the edit", "err");
    btn.disabled = false;
  }
});

// ---- Sales Order block ------------------------------------------------------
// Shows the order exactly as it is keyed into AutoCount: one block per machine,
// opened by the labour line, then the machine heading, its parts, the repair
// comment and a sub-total. Un-coded rows are notes and carry no price.
function renderSalesOrder(order) {
  const lines = order.lines || [];
  let html = `
    <div class="so-row so-head">
      <span>Item Code</span><span>Description</span>
      <span class="so-qty">Qty</span><span class="so-price">Price</span><span class="so-amt">Amount</span>
    </div>`;

  for (const l of lines) {
    const isNote = !l.item_code;
    let kind = "";
    if (isNote) {
      const d = String(l.description || "");
      if (d === "SubTotal") kind = " so-row-sub";
      else if (d.startsWith("*")) kind = " so-row-comment";
      else if (d.includes("S/S:")) kind = " so-row-machine";
      else kind = " so-row-note";
    }
    html += `
      <div class="so-row${isNote ? " so-row-note" : ""}${kind}">
        <span class="so-code mono">${escapeHtml(l.item_code || "")}</span>
        <span class="so-desc">${escapeHtml(l.description || "")}</span>
        <span class="so-qty">${l.quantity ? escapeHtml(String(l.quantity)) : ""}</span>
        <span class="so-price">${l.quantity ? money(l.unit_price) : ""}</span>
        <span class="so-amt">${l.line_amount ? money(l.line_amount) : ""}</span>
      </div>`;
  }

  $("so-lines").innerHTML = html;
  $("so-sub").textContent = `${order.so_number} · ${order.notes || ""}`;
  $("so-total").textContent = money(order.total_amount);
  $("so-modal").style.display = "flex";
  document.body.style.overflow = "hidden";
}

function closeSalesOrder() {
  $("so-modal").style.display = "none";
  document.body.style.overflow = "";
}
$("so-close").addEventListener("click", closeSalesOrder);
$("so-modal").addEventListener("click", (e) => {
  if (e.target === $("so-modal")) closeSalesOrder();
});

// Fetch and show the order raised for a slip.
async function showSlipOrder(slipNumber) {
  try {
    const order = await api(`/api/slips/${encodeURIComponent(slipNumber)}/order`);
    renderSalesOrder(order);
  } catch (e) {
    toast(e.message, "err");
  }
}

// ---- Scanner ---------------------------------------------------------------
function scanStatus(html) { const el = $("scan-status"); if (el) el.innerHTML = html; }

// Scanner engine: prefer the device's native BarcodeDetector (fast, accurate on
// Code 128 — great on Android), fall back to ZXing (covers iPhone Safari).
let videoStream = null;
let detectLoop = null;
let zxingReader = null;
let torchOn = false;
// Double-read confirm: hold the last candidate; only accept on a second matching read.
let pendingCode = null;

const STATUS_READY = '<span class="led"></span> Point at a barcode — tap the view to focus';
const STATUS_BLOCKED = '<span class="led" style="background:var(--amber);box-shadow:0 0 0 3px var(--amber-tint)"></span> Camera blocked — switch to Type code';

async function startScanner() {
  await stopScanner();
  const video = $("reader-video");
  if (!video) { scanStatus(STATUS_BLOCKED); return; }

  try {
    // Ask for a high-resolution rear camera with continuous autofocus tuned for
    // close-up labels — sharper frames lock far faster, especially up close.
    videoStream = await navigator.mediaDevices.getUserMedia({
      video: {
        facingMode: { ideal: "environment" },
        width: { ideal: 1920 },
        height: { ideal: 1080 },
        focusMode: { ideal: "continuous" },
        // Nudge focus toward a near distance (macro) so a close label snaps sharp
        // quickly instead of hunting across the whole range. Ignored if unsupported.
        focusDistance: { ideal: 0.12 },
        advanced: [{ focusMode: "continuous" }, { focusDistance: 0.12 }],
      },
      audio: false,
    });
    video.srcObject = videoStream;
    video.setAttribute("playsinline", "true");
    await video.play();
    scanStatus(STATUS_READY);
    updateTorchButton();
    applyFocusTuning();
  } catch (e) {
    // Retry with a basic request if the constrained one was rejected.
    try {
      videoStream = await navigator.mediaDevices.getUserMedia({
        video: { facingMode: "environment" }, audio: false,
      });
      video.srcObject = videoStream;
      video.setAttribute("playsinline", "true");
      await video.play();
      scanStatus(STATUS_READY);
      updateTorchButton();
      applyFocusTuning();
    } catch (e2) {
      scanStatus(STATUS_BLOCKED);
      return;
    }
  }

  // Path 1: native BarcodeDetector (Chrome/Android, some others)
  if ("BarcodeDetector" in window) {
    try {
      const detector = new window.BarcodeDetector({
        formats: ["code_128", "code_39", "qr_code", "ean_13"],
      });
      const tick = async () => {
        if (!videoStream) return;
        try {
          const codes = await detector.detect(video);
          if (codes && codes.length) onScanCandidate(codes[0].rawValue);
        } catch (_) {}
        detectLoop = requestAnimationFrame(tick);
      };
      detectLoop = requestAnimationFrame(tick);
      return;
    } catch (_) {
      // fall through to ZXing
    }
  }

  // Path 2: ZXing fallback (iPhone Safari, browsers without BarcodeDetector)
  if (window.ZXingBrowser) {
    try {
      zxingReader = new ZXingBrowser.BrowserMultiFormatReader();
      zxingReader.decodeFromVideoElement(video, (result) => {
        if (result) onScanCandidate(result.getText());
      });
      return;
    } catch (_) {}
  }

  // Camera works but no decoder engine is available — guide to manual entry.
  scanStatus('<span class="led" style="background:var(--amber);box-shadow:0 0 0 3px var(--amber-tint)"></span> Scanner not supported here — use Type code');
}

// Torch / flashlight — helps in dim storeroom lighting. Supported on most
// Android Chrome; quietly hidden where the device/browser can't do it.
function torchTrack() {
  if (!videoStream) return null;
  const track = videoStream.getVideoTracks()[0];
  if (!track || !track.getCapabilities) return null;
  const caps = track.getCapabilities();
  return caps && caps.torch ? track : null;
}
function updateTorchButton() {
  const btn = $("torch-btn");
  if (!btn) return;
  btn.style.display = torchTrack() ? "flex" : "none";
  btn.classList.toggle("on", torchOn);
}
async function toggleTorch() {
  const track = torchTrack();
  if (!track) return;
  torchOn = !torchOn;
  try { await track.applyConstraints({ advanced: [{ torch: torchOn }] }); } catch (_) {}
  updateTorchButton();
}

// Focus tuning: after the stream starts, apply continuous + near focus if the
// device exposes those capabilities (constraints in getUserMedia are best-effort,
// so we re-apply here where capabilities are actually known).
function applyFocusTuning() {
  if (!videoStream) return;
  const track = videoStream.getVideoTracks()[0];
  if (!track || !track.getCapabilities) return;
  let caps = {};
  try { caps = track.getCapabilities() || {}; } catch (_) { return; }
  const advanced = [];
  if (caps.focusMode && caps.focusMode.includes("continuous")) {
    advanced.push({ focusMode: "continuous" });
  }
  if (caps.focusDistance) {
    // Aim near the close end of the supported range for label-distance focus.
    const near = caps.focusDistance.min +
      (caps.focusDistance.max - caps.focusDistance.min) * 0.15;
    advanced.push({ focusDistance: near });
  }
  if (advanced.length) {
    track.applyConstraints({ advanced }).catch(() => {});
  }
}

// Tap-to-focus: tapping the preview forces a quick single-shot refocus on the
// label, then returns to continuous — useful when auto-focus is hunting.
async function tapToFocus() {
  if (!videoStream) return;
  const track = videoStream.getVideoTracks()[0];
  if (!track || !track.getCapabilities) return;
  let caps = {};
  try { caps = track.getCapabilities() || {}; } catch (_) { return; }
  if (!caps.focusMode) return;
  try {
    if (caps.focusMode.includes("single-shot")) {
      await track.applyConstraints({ advanced: [{ focusMode: "single-shot" }] });
      // Briefly hold single-shot, then restore continuous for ongoing scanning.
      setTimeout(() => {
        if (caps.focusMode.includes("continuous")) {
          track.applyConstraints({ advanced: [{ focusMode: "continuous" }] }).catch(() => {});
        }
      }, 1200);
    } else if (caps.focusMode.includes("manual") && caps.focusDistance) {
      const near = caps.focusDistance.min +
        (caps.focusDistance.max - caps.focusDistance.min) * 0.12;
      await track.applyConstraints({ advanced: [{ focusMode: "manual", focusDistance: near }] });
    }
    // Quick visual pulse so the user knows the tap registered.
    const frame = $("reader-video");
    if (frame) { frame.classList.add("focus-pulse"); setTimeout(() => frame.classList.remove("focus-pulse"), 350); }
  } catch (_) {}
}

async function stopScanner() {
  if (detectLoop) { cancelAnimationFrame(detectLoop); detectLoop = null; }
  if (zxingReader) { try { zxingReader.reset(); } catch (_) {} zxingReader = null; }
  if (videoStream) {
    // Turn torch off before releasing, so it doesn't stay lit.
    try {
      const t = videoStream.getVideoTracks()[0];
      if (torchOn && t) t.applyConstraints({ advanced: [{ torch: false }] }).catch(() => {});
    } catch (_) {}
    try { videoStream.getTracks().forEach((t) => t.stop()); } catch (_) {}
    videoStream = null;
  }
  torchOn = false;
  pendingCode = null;
  const video = $("reader-video");
  if (video) { try { video.srcObject = null; } catch (_) {} }
}

// Double-read confirm: a code must be seen twice in a row before we accept it.
// This kills one-frame misreads (e.g. a wrong number from a blurry frame).
function onScanCandidate(text) {
  if (!text) return;
  if (scanCooldown) return;
  if (text === pendingCode) {
    pendingCode = null;
    onScan(text);
  } else {
    pendingCode = text;
  }
}

function onScan(decodedText) {
  if (scanCooldown) return;
  if (!decodedText) return;
  scanCooldown = true;
  pendingCode = null;
  scanStatus(`<span class="led"></span> Scanned ${escapeHtml(decodedText)}`);
  addByCode(decodedText);
  setTimeout(() => (scanCooldown = false), 1500);
}

// ---- QR live scanner (QR codes only) ---------------------------------------
// Reuses the same proven approach as the barcode scanner (native BarcodeDetector,
// ZXing fallback) but locked to qr_code, into its own #qr-video element.
let qrStream = null;
let qrDetectLoop = null;
let qrZxingReader = null;
let qrCooldown = false;
let qrPending = null;

// The scanner can serve two places: the machine popup (default — feeds
// addByCode) and the Find Part screen (feeds the stock lookup). qrTarget
// says which video/status elements to use and what to do with a scanned code.
const QR_DEFAULT_TARGET = { videoId: "qr-video", statusId: "qr-status", onCode: (text) => addByCode(text) };
let qrTarget = QR_DEFAULT_TARGET;

function qrStatus(html) { const el = $(qrTarget.statusId); if (el) el.innerHTML = html; }

async function startQrScanner(target) {
  await stopQrScanner();
  qrTarget = target || QR_DEFAULT_TARGET;
  const video = $(qrTarget.videoId);
  if (!video) return;

  try {
    qrStream = await navigator.mediaDevices.getUserMedia({
      video: { facingMode: { ideal: "environment" }, width: { ideal: 1280 }, height: { ideal: 1280 } },
      audio: false,
    });
    video.srcObject = qrStream;
    video.setAttribute("playsinline", "true");
    await video.play();
    qrStatus('<span class="led"></span> Point at a QR code');
  } catch (e) {
    qrStatus('<span class="led" style="background:var(--amber);box-shadow:0 0 0 3px var(--amber-tint)"></span> Camera blocked — switch to Type code');
    return;
  }

  // Path 1: native / polyfilled BarcodeDetector, QR only
  if ("BarcodeDetector" in window) {
    try {
      const detector = new window.BarcodeDetector({ formats: ["qr_code"] });
      const tick = async () => {
        if (!qrStream) return;
        try {
          const codes = await detector.detect(video);
          if (codes && codes.length) onQrCandidate(codes[0].rawValue);
        } catch (_) {}
        qrDetectLoop = requestAnimationFrame(tick);
      };
      qrDetectLoop = requestAnimationFrame(tick);
      return;
    } catch (_) {}
  }

  // Path 2: ZXing fallback
  if (window.ZXingBrowser) {
    try {
      qrZxingReader = new ZXingBrowser.BrowserQRCodeReader
        ? new ZXingBrowser.BrowserQRCodeReader()
        : new ZXingBrowser.BrowserMultiFormatReader();
      qrZxingReader.decodeFromVideoElement(video, (result) => {
        if (result) onQrCandidate(result.getText());
      });
      return;
    } catch (_) {}
  }

  qrStatus('<span class="led" style="background:var(--amber);box-shadow:0 0 0 3px var(--amber-tint)"></span> Scanner not supported here — use Type code');
}

async function stopQrScanner() {
  if (qrDetectLoop) { cancelAnimationFrame(qrDetectLoop); qrDetectLoop = null; }
  if (qrZxingReader) { try { qrZxingReader.reset(); } catch (_) {} qrZxingReader = null; }
  if (qrStream) {
    try { qrStream.getTracks().forEach((t) => t.stop()); } catch (_) {}
    qrStream = null;
  }
  qrPending = null;
  const video = $(qrTarget.videoId);
  if (video) { try { video.srcObject = null; } catch (_) {} }
}

// Double-read confirm (kills one-frame misreads), same pattern as the barcode path.
function onQrCandidate(text) {
  if (!text || qrCooldown) return;
  if (text === qrPending) { qrPending = null; onQrScan(text); }
  else qrPending = text;
}
function onQrScan(text) {
  if (qrCooldown || !text) return;
  qrCooldown = true;
  qrPending = null;
  qrStatus(`<span class="led"></span> Scanned ${escapeHtml(text)}`);
  qrTarget.onCode(text);
  setTimeout(() => (qrCooldown = false), 1500);
}

// ---- OCR mode (read the printed SKU text on damaged labels) -----------------
// Reuses a camera stream into #ocr-video; on capture, Tesseract reads the frame,
// then we pull out the first BRAND+number token (e.g. "SZEN 140051111").
let ocrStream = null;
let ocrBusy = false;

function ocrStatus(html) { $("ocr-status").innerHTML = html; }

async function startOcrCamera() {
  await stopOcrCamera();
  const video = $("ocr-video");
  if (!video) return;
  try {
    ocrStream = await navigator.mediaDevices.getUserMedia({
      video: { facingMode: "environment" },
      audio: false,
    });
    video.srcObject = ocrStream;
    video.setAttribute("playsinline", "true");
    await video.play();
    ocrStatus('<span class="led"></span> Frame the printed code, then tap Read');
  } catch (e) {
    ocrStatus('<span class="led" style="background:var(--amber);box-shadow:0 0 0 3px var(--amber-tint)"></span> Camera blocked — switch to Type code');
  }
}

async function stopOcrCamera() {
  if (ocrStream) {
    try { ocrStream.getTracks().forEach((t) => t.stop()); } catch (_) {}
    ocrStream = null;
  }
  const video = $("ocr-video");
  if (video) { try { video.srcObject = null; } catch (_) {} }
}

// Pull a SKU-shaped token out of raw OCR text: a brand prefix (letters) followed
// by a long number (e.g. "SZEN 140051111"). OM SKUs have a 5+ digit run, so this
// ignores short rack/bin codes like "BK3410" or "R3D6" that share the label.
// OCR sometimes confuses letters/digits inside the number — we fix the common ones.
function fixDigits(s) {
  return s
    .replace(/O/g, "0").replace(/Q/g, "0").replace(/D/g, "0")
    .replace(/I/g, "1").replace(/L/g, "1")
    .replace(/S/g, "5").replace(/B/g, "8").replace(/Z/g, "2").replace(/G/g, "6");
}
function extractSku(text) {
  if (!text) return null;
  const cleaned = text.toUpperCase().replace(/[^A-Z0-9 \n]/g, " ");
  // Allow the "number" part to contain OCR-confused letters; we repair them after.
  const matches = [...cleaned.matchAll(/([A-Z]{2,6})\s*([0-9OQDILSBZG]{5,12})/g)];
  if (!matches.length) return null;
  // Prefer the candidate with the longest run — that's the real part number.
  matches.sort((a, b) => b[2].length - a[2].length);
  const brand = matches[0][1];
  const number = fixDigits(matches[0][2]);
  return brand + " " + number;
}

async function captureAndRead() {
  if (ocrBusy) return;
  const video = $("ocr-video");
  if (!video || !ocrStream) { ocrStatus('<span class="led" style="background:var(--amber);box-shadow:0 0 0 3px var(--amber-tint)"></span> Camera not ready'); return; }
  if (!window.Tesseract) { ocrStatus('<span class="led" style="background:var(--amber);box-shadow:0 0 0 3px var(--amber-tint)"></span> Text reader still loading — try again'); return; }

  ocrBusy = true;
  ocrStatus('<span class="led"></span> Reading…');

  const vw = video.videoWidth || 1280;
  const vh = video.videoHeight || 720;

  // Crop to a central horizontal band — the user aims the SKU line into the guide.
  // This drops the surrounding label noise (barcode, rack codes) so OCR focuses
  // only on the printed part number. Band = full width, middle ~28% of height.
  const bandH = Math.round(vh * 0.28);
  const bandY = Math.round((vh - bandH) / 2);

  // Upscale 2x — Tesseract is far more accurate on larger characters.
  const scale = 2;
  const canvas = document.createElement("canvas");
  canvas.width = vw * scale;
  canvas.height = bandH * scale;
  const ctx = canvas.getContext("2d");
  ctx.drawImage(video, 0, bandY, vw, bandH, 0, 0, canvas.width, canvas.height);

  // Grayscale + contrast boost so crisp black text pops from the label background.
  try {
    const img = ctx.getImageData(0, 0, canvas.width, canvas.height);
    const d = img.data;
    for (let i = 0; i < d.length; i += 4) {
      const g = 0.299 * d[i] + 0.587 * d[i + 1] + 0.114 * d[i + 2];
      // Soft threshold: push toward black/white without going fully binary.
      const v = g < 110 ? Math.max(0, g - 40) : Math.min(255, g + 40);
      d[i] = d[i + 1] = d[i + 2] = v;
    }
    ctx.putImageData(img, 0, 0);
  } catch (_) { /* if getImageData is blocked, proceed with the colour crop */ }

  try {
    const { data } = await Tesseract.recognize(canvas, "eng", {
      tessedit_char_whitelist: "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789 ",
      // PSM 6 = treat the image as a single uniform block of text (one line band).
      tessedit_pageseg_mode: "6",
    });
    const raw = (data && data.text ? data.text : "").trim();
    const sku = extractSku(raw);
    if (sku) {
      ocrStatus(`<span class="led"></span> Read ${escapeHtml(sku)}`);
      addByCode(sku);
    } else {
      ocrStatus('<span class="led" style="background:var(--amber);box-shadow:0 0 0 3px var(--amber-tint)"></span> No code found — line the text up in the guide and try again');
    }
  } catch (e) {
    ocrStatus('<span class="led" style="background:var(--amber);box-shadow:0 0 0 3px var(--amber-tint)"></span> Could not read — try again');
  } finally {
    ocrBusy = false;
  }
}

// ---- Mode toggle (part-entry methods within Open Service) -------------------
function setMode(mode) {
  currentMode = mode;
  document.querySelectorAll("#mode-toggle button").forEach((b) =>
    b.classList.toggle("on", b.dataset.mode === mode)
  );

  const qrPane = $("qr-pane");
  if (qrPane) qrPane.style.display = mode === "qr" ? "flex" : "none";
  const manualPane = $("manual-pane");
  if (manualPane) manualPane.style.display = mode === "manual" ? "block" : "none";

  if (mode === "qr") startQrScanner();
  else stopQrScanner();
  if (mode === "manual") {
    const ci = $("code-input"); if (ci) { ci.value = ""; ci.focus(); }
    const cr = $("code-results"); if (cr) cr.innerHTML = "";
  }
}

// ---- Event wiring ----------------------------------------------------------
// Role selection
// Technician is the only role with a Chinese interface (i18n.js), and that
// layer is installed at page load. So when someone crosses into or out of
// Technician we reload; every other role change stays instant as before.
function languageChanges(nextRole) {
  return (getRole() === "tech") !== (nextRole === "tech");
}
$("switch-role").addEventListener("click", () => {
  const reload = languageChanges("");
  setUser("");
  if (reload) { location.reload(); return; } // reopens on the picker
  renderStaffPicker();
  showScreen("role");
});

// Home navigation
document.querySelectorAll(".home-btn").forEach((b) =>
  b.addEventListener("click", () => {
    const go = b.dataset.go;
    if (go === "new") { resetNewServiceForm(); showScreen("new"); }
    else if (go === "open") { enterOpenService(); }
    else if (go === "close") { enterCloseService(); }
    else if (go === "view") { enterViewSlips(); }
    else if (go === "find") { enterFindPart(); }
    else if (go === "quote") { enterNeedToQuote(); }
    else if (go === "requests") { enterPurchaser(); }
    else if (go === "bulk") { enterBulkOrder(); }
    else if (go === "ipl") { enterIpl(); }
  })
);
$("home-link").addEventListener("click", goHome);

// ---- Find Part --------------------------------------------------------------
// Search AutoCount by description or code; tap a result to see the stock card
// (part no., description, shelf location, balance qty). Read-only.
// ---- The last few parts looked up ------------------------------------------
// Part numbers here are long and unfriendly - SZEN 848CE037A0 - and checking
// the same one twice in a shift means typing it twice. Five is enough to cover
// a job without becoming a list of its own to read.
//
// Kept on the phone, per person: these phones are shared, and 小刘's lookups
// are no use to 文建. Nothing goes to the server; it is a convenience, not a
// record.
const RECENT_MAX = 5;
const recentKey = () => `om_recent_parts_${(getUser() || {}).id || "?"}`;

function recentParts() {
  try {
    const raw = JSON.parse(localStorage.getItem(recentKey()) || "[]");
    return Array.isArray(raw) ? raw.filter((r) => r && r.item_code) : [];
  } catch (_) {
    return [];                       // unreadable or full: simply no history
  }
}

function rememberPart(p) {
  if (!p || !p.item_code) return;
  try {
    const keep = { item_code: p.item_code, description: p.description || p.item_code };
    // Looking at the same part again moves it to the top rather than adding a
    // second row of it.
    const list = [keep, ...recentParts().filter((r) => r.item_code !== keep.item_code)];
    localStorage.setItem(recentKey(), JSON.stringify(list.slice(0, RECENT_MAX)));
  } catch (_) { /* a phone with storage off just gets no history */ }
}

// Shown only on the empty screen: once someone is searching or reading a part,
// the list is in the way of what they asked for.
function renderRecentParts() {
  const box = $("fp-recent");
  if (!box) return;
  const list = recentParts();
  const busy = $("fp-q").value.trim() || $("fp-detail").style.display === "block"
            || $("fp-scan-area").style.display === "flex";
  if (!list.length || busy) { box.style.display = "none"; box.innerHTML = ""; return; }
  box.innerHTML =
    `<p class="eyebrow fp-recent-head">Recently looked up</p>` +
    list.map((r) =>
      `<button type="button" class="company-option" data-recent="${escapeAttr(r.item_code)}">
         <span class="fp-opt-desc">${escapeHtml(r.description)}</span>
         <span class="fp-opt-code mono">${escapeHtml(r.item_code)}</span>
       </button>`).join("");
  box.style.display = "block";
  box.querySelectorAll("[data-recent]").forEach((b) =>
    b.addEventListener("click", () => showPartStock(b.dataset.recent))
  );
}

function enterFindPart() {
  $("fp-q").value = "";
  $("fp-results").innerHTML = "";
  $("fp-detail").style.display = "none";
  $("fp-detail").innerHTML = "";
  $("fp-order-more").style.display = "none";
  fpCurrentPart = null;
  $("fp-scan-area").style.display = "none";
  $("fp-scan").style.display = "flex";
  showScreen("find");
  // Always opens on the part search: it is the common question, and a screen
  // that remembered the mode would have someone typing a part number into a
  // box waiting for a shelf.
  setFindMode("part");
  renderRecentParts();
  setTimeout(() => $("fp-q").focus(), 50);
}
// QR scanning inside Find Part: scan a part's code to jump straight to its
// stock card. Uses the shared scanner pointed at Find Part's own elements.
function stopFindScan() {
  $("fp-scan-area").style.display = "none";
  $("fp-scan").style.display = "flex";
  try { stopQrScanner(); } catch (_) {}
  renderRecentParts();
}
$("fp-scan").addEventListener("click", () => {
  $("fp-results").innerHTML = "";
  $("fp-detail").style.display = "none";
  $("fp-order-more").style.display = "none";
  $("fp-scan").style.display = "none";
  $("fp-scan-area").style.display = "flex";
  $("fp-recent").style.display = "none";
  startQrScanner({
    videoId: "fp-video",
    statusId: "fp-scan-status",
    onCode: (code) => {
      stopFindScan();
      showPartStock(code);
    },
  });
});
$("fp-scan-stop").addEventListener("click", stopFindScan);

// One row for every list that offers a part to pick: Find Part, the search in
// the machine screen, and the shelf listing. They were three copies of the
// same markup, which is how the balance ended up on one of them and not the
// others - the same trap shelfRowHtml exists to avoid.
//
// bal_qty may be absent (an older phone's cached copy of the app talking to a
// new server is fine; a new page talking to an old server is what happens
// mid-deploy). Missing is not zero, and showing a confident "0" for "I don't
// know" would send someone to a shelf for nothing.
function partOptionHtml(p, { extraClass = "" } = {}) {
  const known = p.bal_qty !== undefined && p.bal_qty !== null;
  const n = Number(p.bal_qty) || 0;
  const qty = Number.isInteger(n) ? String(n) : n.toFixed(2);
  const sub = p.shelf ? `${escapeHtml(p.shelf)} · ${escapeHtml(p.item_code)}` : escapeHtml(p.item_code);
  return `<button type="button" class="company-option fp-opt-row ${extraClass}" data-code="${escapeAttr(p.item_code)}">
      <span class="fp-opt-main">
        <span class="fp-opt-desc">${escapeHtml(p.description)}${
          p.desc2 ? ` <span class="fp-opt-model">· ${escapeHtml(p.desc2)}</span>` : ""}</span>
        <span class="fp-opt-code mono">${sub}</span>
      </span>
      ${known ? `<span class="fp-opt-qty ${n > 0 ? "fp-qty-ok" : "fp-qty-zero"}">${escapeHtml(qty)}${
        p.uom ? `<span class="fp-opt-uom">${escapeHtml(p.uom)}</span>` : ""}</span>` : ""}
    </button>`;
}

// ---- Find Part: by part, or by where it lives -------------------------------
// "What is this part" and "what is on this shelf" get asked by the same people
// minutes apart, so they share one box and one results list. The mode decides
// which question is being asked; nothing else about the screen changes.
let fpMode = "part";

function setFindMode(mode) {
  fpMode = mode === "loc" ? "loc" : "part";
  const loc = fpMode === "loc";
  $("fp-q-label").textContent = loc
    ? "Search by location"
    : "Search by description or part no.";
  $("fp-q").placeholder = loc ? "e.g. R4E1" : "e.g. clutch, carburetor, SZEN 140…";
  document.querySelectorAll("#fp-mode [data-fpmode]").forEach((b) =>
    b.classList.toggle("on", b.dataset.fpmode === fpMode));
  // The old question's answers are not answers to the new one.
  $("fp-q").value = "";
  $("fp-results").innerHTML = "";
  $("fp-detail").style.display = "none";
  $("fp-order-more").style.display = "none";
  renderRecentParts();
  $("fp-q").focus();
}

$("fp-mode").addEventListener("click", (e) => {
  const b = e.target.closest("[data-fpmode]");
  if (b) setFindMode(b.dataset.fpmode);
});

// Everything on one shelf. A location holds many parts, so this lists them
// rather than jumping to one, and says how many there are in total - "50
// parts" and "50 of 300" mean very different things when you are checking a
// shelf against what the app says should be on it.
async function runLocationSearch(q) {
  const box = $("fp-results");
  try {
    const data = await api(`/api/parts-by-location?q=${encodeURIComponent(q)}`);
    const list = data.results || [];
    if (!list.length) {
      box.innerHTML = `<div class="fp-empty">Nothing recorded at ${escapeHtml(q)}</div>`;
      return;
    }
    const shown = list.length;
    const more = data.total > shown
      ? `<div class="fp-loc-count">Showing ${shown} of ${data.total} — narrow the location to see the rest</div>`
      : `<div class="fp-loc-count">${data.total} part${data.total === 1 ? "" : "s"} here</div>`;
    // fp-loc-row is only a marker for the taller list: a shelf is read down,
    // a search result is glanced at.
    box.innerHTML = more + list.map((p) => partOptionHtml(p, { extraClass: "fp-loc-row" })).join("");
    box.querySelectorAll(".company-option").forEach((btn) =>
      btn.addEventListener("click", () => showPartStock(btn.dataset.code)));
  } catch (_) {
    box.innerHTML = `<div class="fp-empty">Lookup failed</div>`;
  }
}

let fpDebounce = null;
$("fp-q").addEventListener("input", () => {
  clearTimeout(fpDebounce);
  const q = $("fp-q").value.trim();
  const box = $("fp-results");
  $("fp-detail").style.display = "none";
  $("fp-order-more").style.display = "none";
  // Two characters before searching a description, because one letter matches
  // half the catalogue. A location is different: a rack can be called "A", and
  // asking what is on it is a fair question - the result is capped anyway.
  const least = fpMode === "loc" ? 1 : 2;
  if (q.length < least) { box.innerHTML = ""; renderRecentParts(); return; }
  $("fp-recent").style.display = "none";
  fpDebounce = setTimeout(async () => {
    if (fpMode === "loc") return runLocationSearch(q);
    try {
      const data = await api(`/api/parts-search?q=${encodeURIComponent(q)}`);
      const list = data.results || [];
      if (!list.length) {
        box.innerHTML = `<div class="fp-empty">No matching parts</div>`;
        return;
      }
      box.innerHTML = list.map((p) => partOptionHtml(p)).join("");
      box.querySelectorAll(".company-option").forEach((btn) =>
        btn.addEventListener("click", () => showPartStock(btn.dataset.code))
      );
    } catch (_) { box.innerHTML = ""; }
  }, 250);
});

let fpCurrentPart = null; // the part shown in the Find Part detail card

async function showPartStock(code) {
  const detail = $("fp-detail");
  $("fp-results").innerHTML = "";
  detail.style.display = "block";
  $("fp-order-more").style.display = "none";
  fpCurrentPart = null;
  detail.innerHTML = `<div class="fp-loading">Looking up stock…</div>`;
  try {
    const p = await api(`/api/part-stock/${encodeURIComponent(code)}`);
    fpCurrentPart = p;
    rememberPart(p);
    renderRecentParts();          // now reading a part: stand the list down
    const qty = Number(p.bal_qty);
    const qtyStr = Number.isInteger(qty) ? String(qty) : qty.toFixed(2);
    detail.innerHTML = `
      <div class="fp-row"><span class="fp-lbl">Part No.</span><span class="fp-val mono">${escapeHtml(p.item_code)}</span></div>
      <div class="fp-row"><span class="fp-lbl">Description</span><span class="fp-val">${escapeHtml(p.description)}</span></div>
      ${fitsRowHtml(p)}
      ${shelfRowHtml(p)}
      <div class="fp-row"><span class="fp-lbl">Bal. Qty</span><span class="fp-val fp-qty ${qty > 0 ? "fp-qty-ok" : "fp-qty-zero"}">${qtyStr}${p.uom ? " " + escapeHtml(p.uom) : ""}</span></div>
      <div class="fp-price" id="fp-part-price"></div>`;
    $("fp-order-more").style.display = "block";
    // Prices stay hidden until asked for, the same as on the IPL sheet. Unlike
    // there, the item code is already exact - Find Part resolved it - so there
    // is nothing to disambiguate before the button can be offered.
    iplPriceState = { code: p.item_code, itemCode: p.item_code };
    renderIplPriceButton(p.item_code, $("fp-part-price"));
    wireShelfEdit(detail, p, (shelf) => { p.shelf = shelf; showPartStock(p.item_code); });
    wireFits(detail);
    renderPartNote(detail, p, () => showPartStock(p.item_code));
  } catch (e) {
    detail.innerHTML = `<div class="fp-empty">${escapeHtml(e.message || "Lookup failed")}</div>`;
  }
}

// Whether a machine is finished is the technician's call - they did the work.
// Everyone else can tick it too, so a missed tick at six o'clock does not have
// to wait for the technician to come back in the morning. Purchaser is in here
// with Sales and Admin, the same as every other counter job in the app.
function canMarkRepaired() {
  return ["tech", "sales", "purchaser", "admin"].includes(getRole());
}

// Sales take the call, so Sales record the answer. Purchaser and Admin share
// the sales screens and cover for them, the same as everywhere else in the app.
function canDecide() {
  return ["sales", "purchaser", "admin"].includes(getRole());
}

// ---- A note kept against a part --------------------------------------------
// Chiefly supersessions - "replaced by X". The knowledge lives in people's
// heads and surfaces at the worst moment, so it is recorded against the part
// and shown wherever that part is looked at.
//
// Written by Sales, Purchaser and Admin; read by everyone. Keyed on the exact
// AutoCount item code, so a note on 848BE058B2 never appears on 848BE058B2R.
function canEditNote() {
  return ["sales", "purchaser", "admin"].includes(getRole());
}

// Most parts are keyed on their exact AutoCount item code. Some IPL parts are
// not in AutoCount at all - obsolete, never stocked, or a whole assembly - and
// those are exactly the ones somebody wants to write "no longer available, use
// X" against. They get a key of their own, in a namespace that cannot collide
// with an item code:
//
//     IPL:ZENOAH:848BE058B2
//
// Scoped to the BRAND, not the model: the same part number across two of a
// brand's machines is the same part and should share one note, while an
// identical number under another brand is a different part entirely.
function iplNoteKey(part) {
  const brand = String((ipl.model && ipl.model.name) || "").trim().split(/\s+/)[0] || "?";
  const num = String(part.search || part.part_number || "").replace(/[^A-Za-z0-9]/g, "");
  return `IPL:${brand.toUpperCase()}:${num.toUpperCase()}`;
}

async function fetchPartNote(itemCode, fallbackKey) {
  const read = async (k) => {
    try {
      const r = await api(`/api/part-notes/${encodeURIComponent(k)}`);
      return r && r.note ? { ...r, item_code: k } : null;
    } catch (_) {
      return null;                     // a note must never break a lookup
    }
  };
  const first = await read(itemCode);
  if (first) return first;
  // A note written while the part was unknown to AutoCount should not vanish
  // the day it is added to the catalogue.
  return fallbackKey && fallbackKey !== itemCode ? read(fallbackKey) : null;
}

// A part code written inside a note becomes tappable, so "replaced by
// SZEN 140051112" takes you to that part instead of leaving you to retype it.
//
// The pattern is deliberately mean. Anything with five or more digits in it is
// a part code around here; anything with fewer is a model, a year or a size -
// "fits 525 and 545", "from 2024 onward" - and turning those into links would
// make the notes look like nonsense. An optional short uppercase prefix is
// taken with the number, because SZEN 140051111 is the whole code.
const PART_CODE_RE = /\b(?:[A-Z]{2,5}\s+)?[A-Za-z0-9][A-Za-z0-9._-]{4,}\b/g;

function looksLikePartCode(token) {
  return (token.match(/\d/g) || []).length >= 5;
}

// Escapes everything, then wraps the codes. Building it the other way round -
// wrapping first - would put the note's own text through escaping twice.
function linkifyPartCodes(text) {
  let out = "", last = 0;
  for (const m of String(text).matchAll(PART_CODE_RE)) {
    if (!looksLikePartCode(m[0])) continue;
    out += escapeHtml(text.slice(last, m.index));
    out += `<button type="button" class="part-note-link" data-part-code="${escapeAttr(m[0])}">${escapeHtml(m[0])}</button>`;
    last = m.index + m[0].length;
  }
  return out + escapeHtml(text.slice(last));
}

// One part's details, without leaving what you were reading. Opened from a
// code inside a note: the question is "what is that replacement?", and being
// carried to another screen answers it while losing your place.
let peekCode = null;

function openPeek() {
  $("peek-modal").style.display = "flex";
  document.body.style.overflow = "hidden";
}

function closePeek() {
  $("peek-modal").style.display = "none";
  const stillOpen = ["ipl-modal", "machine-modal", "order-modal", "note-modal"]
    .some((id) => $(id) && $(id).style.display === "flex");
  if (!stillOpen) document.body.style.overflow = "";
  peekCode = null;
}
$("peek-close").addEventListener("click", closePeek);
$("peek-open").addEventListener("click", () => {
  const code = peekCode;
  closePeek();
  if ($("ipl-modal").style.display === "flex") closeIplPart();
  enterFindPart();
  showPartStock(code);
});

async function peekAtPart(code) {
  $("peek-title").textContent = code;
  $("peek-sub").textContent = "";
  $("peek-body").innerHTML = `<div class="fp-loading">Looking it up…</div>`;
  $("peek-open").style.display = "none";
  peekCode = null;
  openPeek();

  try {
    const data = await api(`/api/parts-search?q=${encodeURIComponent(code)}`);
    const list = data.results || [];
    if (!list.length) {
      $("peek-body").innerHTML =
        `<div class="fp-empty">${escapeHtml(code)} is not in AutoCount.</div>`;
      return;
    }
    // A bare number can match a part and its R variant. Ask rather than pick.
    if (list.length > 1) {
      $("peek-sub").textContent = `${list.length} parts match that number`;
      $("peek-body").innerHTML = list.map((r) =>
        `<button type="button" class="company-option" data-code="${escapeAttr(r.item_code)}">
           <span class="fp-opt-desc">${escapeHtml(r.description)}</span>
           <span class="fp-opt-code mono">${escapeHtml(r.item_code)}</span>
         </button>`).join("");
      $("peek-body").querySelectorAll(".company-option").forEach((b) =>
        b.addEventListener("click", () => peekAtPart(b.dataset.code))
      );
      return;
    }
    await showPeekStock(list[0].item_code);
  } catch (e) {
    $("peek-body").innerHTML = `<div class="fp-empty">${escapeHtml(e.message || "Lookup failed")}</div>`;
  }
}

async function showPeekStock(itemCode) {
  peekCode = itemCode;
  try {
    const p = await api(`/api/part-stock/${encodeURIComponent(itemCode)}`);
    const qty = Number(p.bal_qty);
    const qtyStr = Number.isInteger(qty) ? String(qty) : qty.toFixed(2);
    $("peek-title").textContent = p.description || p.item_code;
    $("peek-sub").textContent = p.item_code;
    $("peek-body").innerHTML = `
      <div class="fp-row"><span class="fp-lbl">Part No.</span><span class="fp-val mono">${escapeHtml(p.item_code)}</span></div>
      <div class="fp-row"><span class="fp-lbl">Description</span><span class="fp-val">${escapeHtml(p.description)}</span></div>
      ${fitsRowHtml(p)}
      <div class="fp-row"><span class="fp-lbl">Location / Shelf</span><span class="fp-val">${p.shelf ? escapeHtml(p.shelf) : "—"}</span></div>
      <div class="fp-row"><span class="fp-lbl">Bal. Qty</span><span class="fp-val fp-qty ${qty > 0 ? "fp-qty-ok" : "fp-qty-zero"}">${qtyStr}${p.uom ? " " + escapeHtml(p.uom) : ""}</span></div>`;
    // A replacement can have been replaced in its turn, so its own note shows
    // here too - and its codes are tappable, which walks the chain.
    wireFits($("peek-body"));
    await renderPartNote($("peek-body"), p, () => showPeekStock(itemCode), { addIfEmpty: false });
    $("peek-open").style.display = "";
  } catch (e) {
    $("peek-body").innerHTML = `<div class="fp-empty">${escapeHtml(e.message || "Lookup failed")}</div>`;
  }
}

function partNoteHtml(note, addIfEmpty = true) {
  if (note && note.note) {
    const who = [note.updated_by, String(note.updated_at || "").split(" ")[0]]
      .filter(Boolean).join(" · ");
    return `<div class="part-note">
        <b>Note</b>${linkifyPartCodes(note.note)}${
          canEditNote() ? `<button type="button" class="part-note-edit" data-note-edit>Edit</button>` : ""
        }${who ? `<span class="part-note-who">${escapeHtml(who)}</span>` : ""}
      </div>`;
  }
  return canEditNote() && addIfEmpty
    ? `<button type="button" class="part-note-add" data-note-edit>+ Add a note (e.g. what replaced this part)</button>`
    : "";
}

// Put the note at the top of a card and wire its button. Called after the card
// is written, because innerHTML replaces whatever was there.
async function renderPartNote(container, part, onSaved, { addIfEmpty = true } = {}) {
  if (!container || !part || !part.item_code) return;
  const note = await fetchPartNote(part.item_code, part.note_key);
  // The peek popup answers "what is that part". An invitation to write a note,
  // above the details and before you have read them, is not that answer.
  const html = partNoteHtml(note, addIfEmpty);
  if (!html) return;
  container.insertAdjacentHTML("afterbegin", html);
  const btn = container.querySelector("[data-note-edit]");
  if (btn) btn.addEventListener("click", () => openNoteModal(part, note, onSaved));
  container.querySelectorAll("[data-part-code]").forEach((el) =>
    el.addEventListener("click", () => peekAtPart(el.dataset.partCode))
  );
}

let notePart = null;
let noteOnSaved = null;

function openNoteModal(part, note, onSaved) {
  notePart = part;
  noteOnSaved = onSaved || null;
  $("note-part-name").textContent = `${part.description || ""} · ${part.item_code}`;
  $("note-text").value = (note && note.note) || "";
  $("note-who").textContent = note && note.updated_by
    ? `Last changed by ${note.updated_by} on ${String(note.updated_at || "").split(" ")[0]}`
    : "";
  $("note-delete").style.display = note && note.note ? "" : "none";
  $("note-modal").style.display = "flex";
  document.body.style.overflow = "hidden";
  setTimeout(() => $("note-text").focus(), 50);
}

function closeNoteModal() {
  $("note-modal").style.display = "none";
  // Another sheet may still be open underneath - releasing the scroll lock
  // then would let the page behind it slide about.
  const stillOpen = ["ipl-modal", "machine-modal", "order-modal"]
    .some((id) => $(id) && $(id).style.display === "flex");
  if (!stillOpen) document.body.style.overflow = "";
  notePart = null;
  noteOnSaved = null;
}
$("note-close").addEventListener("click", closeNoteModal);

async function saveNote(text) {
  if (!notePart) return;
  const btn = $("note-save");
  btn.disabled = true;
  try {
    await api("/api/part-notes", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        // An unresolved IPL part carries its own key; a resolved one is
        // written against the AutoCount item, which is the stabler identity.
        item_code: notePart.note_key && !notePart.resolved ? notePart.note_key : notePart.item_code,
        note: text,
        who: initialsFor(getUser()),
        role: getRole(),
      }),
    });
    const saved = noteOnSaved;
    toast(text ? "Note saved" : "Note removed", "ok");
    closeNoteModal();
    if (saved) saved();
  } catch (e) {
    toast(e.message || "Could not save the note", "err");
  }
  btn.disabled = false;
}

$("note-save").addEventListener("click", () => saveNote($("note-text").value.trim()));
$("note-delete").addEventListener("click", () => {
  if (!confirm("Remove this note?\n\nNobody looking up this part will see it any more.")) return;
  saveNote("");
});

// ---- Location row, shared by both stock cards -------------------------------
// Find Part and the IPL part sheet render the same card. The row lives here so
// the Change button cannot end up on one and not the other.
// Purchaser and Admin. The shelf is the Purchaser's job - she is the one
// putting the stock away, so she is the one who knows where it went, and
// having to find an admin to record it is how a location goes stale.
// Technicians and Sales still only read it.
function canChangeLocation() {
  return ["purchaser", "admin"].includes(getRole());
}

function shelfRowHtml(p) {
  return `<div class="fp-row">
      <span class="fp-lbl">Location / Shelf</span>
      <span class="fp-val">${p.shelf ? escapeHtml(p.shelf) : "—"}${
        canChangeLocation() ? `<button type="button" class="fp-shelf-edit" data-shelf-edit>Change</button>` : ""
      }</span>
    </div>`;
}

// Wire whatever Change button that card just rendered. Called after the card is
// written, because innerHTML replaces the previous button and its listener.
function wireShelfEdit(container, part, onSaved) {
  const btn = container.querySelector("[data-shelf-edit]");
  if (btn) btn.addEventListener("click", () => openLocationModal(part, onSaved));
}

// ---- Change location (Purchaser and Admin) ----------------------------------
// This WRITES to AutoCount and overwrites what is there - a location is meant
// to change, so unlike a price there is no "already set" guard to fall back on.
// The confirmation step is the guard: the current value and the new one are put
// side by side before anything is sent.
let locPart = null;
let locOnSaved = null;

function showLocationStep(step) {
  const confirming = step === "confirm";
  $("loc-entry-field").style.display = confirming ? "none" : "";
  $("loc-confirm").style.display = confirming ? "" : "none";
  $("loc-back").style.display = confirming ? "" : "none";
  $("loc-submit").textContent = confirming ? "Change it in AutoCount" : "Continue";
}

function openLocationModal(part, onSaved) {
  if (!part || !part.item_code) return;
  locPart = part;
  locOnSaved = onSaved || null;
  $("loc-part-name").textContent = `${part.description || ""} · ${part.item_code}`;
  $("loc-shelf").value = part.shelf || "";
  $("loc-current").textContent = part.shelf
    ? `Currently ${part.shelf}`
    : "No location recorded yet";
  showLocationStep("entry");
  $("location-modal").style.display = "flex";
  document.body.style.overflow = "hidden";
  setTimeout(() => { $("loc-shelf").focus(); $("loc-shelf").select(); }, 50);
}

function closeLocationModal() {
  $("location-modal").style.display = "none";
  // The IPL part sheet may still be open underneath; only release the page
  // scroll if nothing else is holding it.
  const stillOpen = ["ipl-modal", "machine-modal", "order-modal"]
    .some((id) => $(id) && $(id).style.display === "flex");
  if (!stillOpen) document.body.style.overflow = "";
  locPart = null;
  locOnSaved = null;
}

$("loc-close").addEventListener("click", closeLocationModal);
$("loc-back").addEventListener("click", () => showLocationStep("entry"));

$("loc-submit").addEventListener("click", async () => {
  if (!locPart) return;
  const shelf = $("loc-shelf").value.replace(/\s+/g, " ").trim();
  if (!shelf) { toast("Enter a location", "err"); return; }

  // First tap shows what is about to change; second tap sends it.
  if ($("loc-confirm").style.display === "none") {
    if (shelf === (locPart.shelf || "").trim()) {
      toast("That is already the location", "err");
      return;
    }
    $("loc-c-part").textContent = locPart.item_code;
    $("loc-c-old").textContent = locPart.shelf || "not set";
    $("loc-c-new").textContent = shelf;
    showLocationStep("confirm");
    return;
  }

  const btn = $("loc-submit");
  btn.disabled = true;
  try {
    const me = getUser();
    const r = await api("/api/part-location", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        item_code: locPart.item_code,
        shelf,
        who: initialsFor(me),
        role: getRole(),
        // For the log sheet. The server could look it up again, but it is on
        // screen here already and a second AutoCount round trip to write an
        // audit row would be paid on every change.
        description: locPart.description || "",
        source: $("ipl-modal").style.display === "flex" ? "IPL" : "Find Part",
      }),
    });
    const saved = locOnSaved;
    toast(r.message || "Location changed", "ok");
    closeLocationModal();
    if (saved) saved(shelf);
  } catch (e) {
    toast(e.message || "Could not change the location", "err");
    btn.disabled = false;
    return;
  }
  btn.disabled = false;
});

// ---- Order More popup -------------------------------------------------------
// Opened from two places now — the Find Part card and the IPL part sheet — so
// the part being ordered is held here rather than read back off either screen.
let orderPart = null;

// Ordering runs in two steps: type the quantity, then confirm what is about to
// be sent. A reorder request goes to the purchaser and gets acted on, so a
// mistyped quantity is worth one deliberate tap to catch.
function showOrderStep(step) {
  const confirming = step === "confirm";
  $("om-qty-field").style.display = confirming ? "none" : "";
  $("om-confirm").style.display = confirming ? "" : "none";
  $("om-back").style.display = confirming ? "" : "none";
  $("om-submit").textContent = confirming ? "Confirm order" : "Submit request";
}

function openOrderModal(part) {
  if (!part || !part.item_code) return;
  orderPart = part;
  $("om-part-name").textContent = `${part.description} · ${part.item_code}`;
  $("om-qty").value = "";
  $("om-remarks").value = "";
  // A placeholder code says nothing about what to buy, so the name is asked
  // for here rather than left for the purchaser to chase.
  const placeholder = isFreeTextPart(part.item_code, part.description);
  $("om-desc-field").style.display = placeholder ? "" : "none";
  $("om-desc").value = "";
  renderOnOrder(part.item_code);
  showOrderStep("qty");
  $("order-modal").style.display = "flex";
  document.body.style.overflow = "hidden";
  setTimeout(() => $("om-qty").focus(), 50);
}

// Whether a supplier has already been asked for this part. The point is to
// stop the second person ordering what the first already did - so it is shown
// BEFORE the quantity box, not after the request is sent.
//
// It never blocks: when AutoCount cannot answer, the row is hidden rather than
// guessed at, and the popup behaves exactly as it did before.
async function renderOnOrder(itemCode) {
  const box = $("om-onorder");
  if (!box) return;
  box.style.display = "none";
  box.className = "om-onorder";
  box.textContent = "";
  try {
    const r = await api(`/api/part-on-order/${encodeURIComponent(itemCode)}`);
    if (!r.supported) return;                       // nothing honest to say
    if (!r.qty) {
      box.className = "om-onorder om-onorder-none";
      box.textContent = "Not on any Purchase Order at the moment.";
      box.style.display = "block";
      return;
    }
    const qty = Number.isInteger(r.qty) ? r.qty : Number(r.qty).toFixed(2);
    const list = (r.orders || [])
      .map((o) => `${escapeHtml(o.doc_no)}${o.date ? ` (${escapeHtml(o.date)})` : ""} — ${o.qty}`)
      .join("<br>");
    box.innerHTML = `<b>${qty} already on order</b>${list}`;
    box.style.display = "block";
  } catch (_) {
    // Context, not permission: a failure here leaves the popup as it was.
  }
}

$("fp-order-more").addEventListener("click", () => openOrderModal(fpCurrentPart));

function closeOrderModal() {
  $("order-modal").style.display = "none";
  // Ordering from the IPL stacks this on top of the part sheet, which is still
  // open underneath — releasing the scroll lock here would let the page behind
  // it slide about.
  if ($("ipl-modal").style.display !== "flex") document.body.style.overflow = "";
}
$("om-close").addEventListener("click", closeOrderModal);
$("om-back").addEventListener("click", () => {
  showOrderStep("qty");
  $("om-qty").focus();
});

$("om-submit").addEventListener("click", async () => {
  if (!orderPart) return;
  const qty = parseInt($("om-qty").value, 10);
  const requester = userName();
  if (!Number.isFinite(qty) || qty < 1) { toast("Enter an order quantity", "err"); return; }
  const placeholder = isFreeTextPart(orderPart.item_code, orderPart.description);
  const typedDesc = $("om-desc").value.trim();
  if (placeholder && !typedDesc) {
    toast("Type what this part is", "err");
    $("om-desc").focus();
    return;
  }
  // Nobody signed in means nothing to put in the requester column, and the
  // purchaser would have no idea who asked.
  if (!requester) { toast("Choose your name from the top bar first", "err"); return; }

  // First tap shows what is about to be sent; the second sends it.
  if ($("om-confirm").style.display === "none") {
    const rk = $("om-remarks").value.trim();
    $("om-check-line").textContent = `Order ${qty} × ${placeholder ? typedDesc : orderPart.description}`;
    $("om-check-who").textContent = `${orderPart.item_code} · requested by ${requester}` +
      (rk ? ` · “${rk}”` : "");
    showOrderStep("confirm");
    return;
  }

  $("om-submit").disabled = true;
  try {
    await api(`/api/part-requests`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        item_code: orderPart.item_code,
        description: placeholder ? typedDesc : orderPart.description,
        qty_requested: qty,
        requester,
        remarks: $("om-remarks").value.trim(),
        // Recorded on the row: by the time anyone edits it, the typed name has
        // replaced the catalogue description and the marker is gone.
        free_text: placeholder,
      }),
    });
    toast("Request submitted", "ok");
    closeOrderModal();
  } catch (e) {
    toast(e.message, "err");
  }
  $("om-submit").disabled = false;
});

// ---- Need to Quote: what the technicians have handed back -------------------
// A technician finishing a repair marks the slip "Need to Quote". Until now
// that status was only visible to whoever happened to open the slip; this is
// the list of them, so nothing sits waiting because nobody knew.
async function enterNeedToQuote() {
  showScreen("quote");
  renderPushRow("quote");
  const wrap = $("q-list");
  wrap.innerHTML = `<div class="fp-loading">Loading…</div>`;
  try {
    const rows = await api(`/api/slips?status=need_quote`);
    if (!rows.length) {
      wrap.innerHTML = `<div class="fp-empty">Nothing waiting to be quoted</div>`;
      refreshQuoteCount();
      return;
    }
    wrap.innerHTML = rows.map((s) => {
      const all = s.machines || [];
      // Machines are quoted one at a time now, so the count on its own would be
      // misleading: two machines, one waiting, reads as two to price.
      const waiting = all.filter((m) => m.state === "AWAITING_QUOTE");
      const list = (waiting.length ? waiting : all).map((m) => m.machine_desc);
      const machines = all.length;
      const created = formatDate(s.created_at);
      return `
      <button type="button" class="slip-card" data-slip="${escapeAttr(s.slip_number)}">
        <div class="slip-card-top">
          <strong>${escapeHtml(s.slip_number)}</strong>
          <span class="vs-status vs-NEED_QUOTE">Need to Quote</span>
        </div>
        <div class="slip-card-co">${escapeHtml(s.company)}</div>
        <div class="slip-card-sub">${escapeHtml(list.join(", "))}${
          waiting.length && waiting.length < machines ? ` · ${waiting.length} of ${machines}` : ""
        }${created ? " · " + escapeHtml(created) : ""}</div>
      </button>`;
    }).join("");
    // Straight into View Slips, which already lists every part with its price
    // and carries the "Mark as Quoted" button — no second copy of any of it.
    wrap.querySelectorAll(".slip-card").forEach((b) =>
      b.addEventListener("click", () => {
        showScreen("view");
        if (viewSearch) viewSearch.reset();
        onViewSlipChosen(b.dataset.slip);
      })
    );
  } catch (e) {
    wrap.innerHTML = `<div class="fp-empty">${escapeHtml(e.message || "Could not load")}</div>`;
  }
  refreshQuoteCount();
}

// The count on the home tile. Cheap enough to refresh whenever home is shown,
// and it is the whole point of the feature: seeing there is something waiting
// without having to go looking for it.
async function refreshQuoteCount() {
  const badge = $("quote-count");
  if (!badge) return;
  const tile = document.querySelector('#screen-home .home-btn[data-go="quote"]');
  if (!tile || tile.style.display === "none") return;
  try {
    const rows = await api(`/api/slips?status=need_quote`);
    const n = rows.length;
    badge.textContent = String(n);
    badge.style.display = n ? "grid" : "none";
  } catch (_) {
    badge.style.display = "none";
  }
}

// ---- Push notifications ----------------------------------------------------
// Per device. A subscription belongs to one browser on one phone, so someone
// with a phone and a tablet turns it on twice and is told on both.
//
// What has to be true for the button to do anything: HTTPS with a certificate
// the device trusts, and on iOS the app added to the Home Screen, on 16.4 or
// later. Safari tabs on iOS get nothing at all, so the row is hidden there
// rather than offering something that cannot work.
function pushSupported() {
  return "serviceWorker" in navigator &&
         "PushManager" in window &&
         "Notification" in window;
}

function urlBase64ToUint8Array(base64) {
  const padded = (base64 + "=".repeat((4 - (base64.length % 4)) % 4))
    .replace(/-/g, "+").replace(/_/g, "/");
  const raw = atob(padded);
  return Uint8Array.from([...raw].map((c) => c.charCodeAt(0)));
}

// navigator.serviceWorker.ready never rejects and never times out: with no
// worker registered it simply hangs for ever. Waiting on it before checking
// anything else left the row stuck on its default text and the button dead to
// the touch. Race it, so a worker that is not there yet reports as much.
function swReady(ms = 4000) {
  if (!("serviceWorker" in navigator)) return Promise.resolve(null);
  return Promise.race([
    navigator.serviceWorker.ready,
    new Promise((resolve) => setTimeout(() => resolve(null), ms)),
  ]);
}

async function currentPushSubscription() {
  if (!pushSupported()) return null;
  const reg = await swReady();
  return reg ? reg.pushManager.getSubscription() : null;
}

// There are two of these rows now, because the notifications run both ways:
// Sales are told a machine is ready to quote, and the technician who did the
// work is told what the customer said. One set of behaviour, two sets of
// elements - a second copy would drift, and the blocked-permission handling
// took long enough to get right once.
const PUSH_ROWS = {
  quote: {
    row: "push-row", btn: "push-toggle", sub: "push-sub", help: "push-help",
    group: "", screen: "screen-quote",
    off: "Notify this device when a technician finishes a repair",
  },
  tech: {
    row: "push-row-tech", btn: "push-toggle-tech", sub: "push-sub-tech", help: "push-help-tech",
    group: "tech", screen: "screen-open",
    off: "Notify this device when Sales confirm a repair or condemn a machine",
  },
};

async function renderPushRow(which = "quote") {
  const ids = PUSH_ROWS[which] || PUSH_ROWS.quote;
  const row = $(ids.row);
  if (!row) return;
  if (!pushSupported()) { row.style.display = "none"; return; }
  row.style.display = "flex";

  const btn = $(ids.btn);
  const sub = $(ids.sub);
  btn.dataset.push = which;

  // Checked first, and without awaiting: it is the one answer that settles the
  // row on its own, and it costs nothing to read.
  //
  // Blocked is not the end of it. No website can ask a second time once the
  // phone has been told "Don't allow" - but it can say where to undo it, and
  // hiding the button instead read as the whole feature having disappeared.
  if (Notification.permission === "denied") {
    btn.style.display = "";
    btn.disabled = false;
    btn.textContent = "How to turn it on";
    btn.dataset.mode = "help";
    sub.textContent = "Blocked on this device — this can only be undone in the phone's own settings";
    return;
  }
  const existing = await currentPushSubscription();
  btn.style.display = "";
  btn.disabled = false;
  btn.dataset.mode = "";
  hidePushHelp(which);

  // Shown whether this device is on or off. "0 devices" is the answer to most
  // of the ways this looks broken - everyone assumes someone else turned it on.
  let devices = null;
  try {
    devices = (await api(`/api/push/status${ids.group ? "?group=" + ids.group : ""}`)).devices;
  } catch (_) {}
  const across = devices === null ? ""
    : devices === 0 ? " · no devices are being notified yet"
    : ` · ${devices} device${devices === 1 ? "" : "s"} being notified`;

  if (existing) {
    btn.textContent = "Turn off";
    sub.textContent = "On for this device" + across;
  } else {
    btn.textContent = "Turn on";
    sub.textContent = ids.off + across;
  }
}

// Where to undo a "Don't allow". The steps differ enough between the two that
// showing both would have someone following the wrong one, so the device is
// asked which it is.
function pushHelpText() {
  const ua = navigator.userAgent || "";
  const iOS = /iPad|iPhone|iPod/.test(ua) ||
              (navigator.platform === "MacIntel" && navigator.maxTouchPoints > 1);
  const android = /Android/.test(ua);

  if (iOS) {
    return `<strong>On this iPhone or iPad</strong>
      <p>Settings &rarr; Notifications &rarr; <b>OM Service</b> &rarr; turn on
         <b>Allow Notifications</b>.</p>
      <p>If OM Service is not in that list, iOS never recorded a choice it can
         show. Remove the app from the Home Screen and add it again from Safari,
         then tap Turn on here — iOS only asks once per installation.</p>`;
  }
  if (android) {
    return `<strong>On this Android phone</strong>
      <p>Chrome &rarr; <b>⋮</b> &rarr; Settings &rarr; Site settings &rarr;
         Notifications &rarr; find <b>${escapeHtml(location.host)}</b> &rarr;
         <b>Allow</b>.</p>
      <p>Then come back here and tap Turn on. Also check Settings &rarr; Apps
         &rarr; Chrome &rarr; Notifications, which is a separate switch, and turn
         off Chrome's own <b>Power saver</b> (⋮ &rarr; Settings &rarr; Power
         saver) — it holds notifications back until the app is opened.</p>`;
  }
  return `<strong>On this device</strong>
    <p>Open the browser's site settings for <b>${escapeHtml(location.host)}</b>
       and set Notifications to <b>Allow</b>, then come back and tap Turn on.</p>
    <p>In most browsers that is the icon at the left of the address bar.</p>`;
}

function showPushHelp(which = "quote") {
  const box = $((PUSH_ROWS[which] || PUSH_ROWS.quote).help);
  if (!box) return;
  box.innerHTML = pushHelpText();
  box.style.display = "block";
}

function hidePushHelp(which = "quote") {
  const box = $((PUSH_ROWS[which] || PUSH_ROWS.quote).help);
  if (box) { box.style.display = "none"; box.innerHTML = ""; }
}

// Permission is changed in the phone's settings, not here, so the app only
// finds out when it is looked at again. Without this the row still says blocked
// after the person has just fixed it, and they conclude it did not work.
//
// Two triggers, because which one a browser fires on returning from Settings
// varies, and leaving the row stale is the whole failure being fixed. Entering
// the screen re-renders it anyway; these cover the app already sitting on it.
function recheckPushRow() {
  for (const [which, ids] of Object.entries(PUSH_ROWS)) {
    const screen = document.getElementById(ids.screen);
    if (screen && screen.classList.contains("active")) renderPushRow(which);
  }
}
document.addEventListener("visibilitychange", () => {
  if (document.visibilityState === "visible") recheckPushRow();
});
window.addEventListener("focus", recheckPushRow);

async function togglePush(which = "quote") {
  const ids = PUSH_ROWS[which] || PUSH_ROWS.quote;
  const btn = $(ids.btn);
  // Asking again would do nothing visible: the browser resolves a blocked
  // request immediately without showing anything, so the tap would look broken.
  if (btn.dataset.mode === "help" || Notification.permission === "denied") {
    const box = $(ids.help);
    const open = box && box.style.display === "block";
    if (open) hidePushHelp(which); else showPushHelp(which);
    return;
  }
  btn.disabled = true;
  try {
    const reg = await swReady();
    if (!reg) {
      toast("The app is still starting up — try again in a moment", "err");
      btn.disabled = false;
      return;
    }
    const existing = await reg.pushManager.getSubscription();

    if (existing) {
      await api("/api/push/unsubscribe", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ endpoint: existing.endpoint }),
      }).catch(() => {});
      await existing.unsubscribe();
      toast("Notifications off for this device", "ok");
    } else {
      // Must be asked from a tap. iOS refuses outright otherwise, and Chrome
      // holds it against the site.
      const permission = await Notification.requestPermission();
      if (permission !== "granted") {
        toast(permission === "denied"
          ? "Notifications blocked — allow them in the phone's settings"
          : "Notifications not enabled", "err");
        await renderPushRow(which);
        // Straight to the instructions: this is the moment it was blocked, and
        // the phone will not offer the choice a second time.
        if (permission === "denied") showPushHelp(which);
        return;
      }
      const { key } = await api("/api/push/key");
      const subscription = await reg.pushManager.subscribe({
        // Required, and the only value browsers accept: every push must show
        // something. There is no silent background push here.
        userVisibleOnly: true,
        applicationServerKey: urlBase64ToUint8Array(key),
      });
      await api("/api/push/subscribe", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          subscription: subscription.toJSON(),
          user_id: (getUser() || {}).id || "",
          role: getRole(),
          tech: (getUser() || {}).tech || "",
        }),
      });
      toast("Notifications on for this device", "ok");
    }
  } catch (e) {
    toast(e.message || "Could not change notifications", "err");
  }
  await renderPushRow(which);
}

// Tapping a notification asks an already-open window to move, rather than
// opening a second one.
if ("serviceWorker" in navigator) {
  navigator.serviceWorker.addEventListener("message", (e) => {
    if (e.data && e.data.type === "go" && e.data.screen === "quote") enterNeedToQuote();
  });
}

// ...and a notification that opened the app cold arrives as ?go=quote.
(function openFromNotification() {
  try {
    const go = new URLSearchParams(location.search).get("go");
    if (go === "quote") {
      // After the role has been read, or the screen is shown to nobody.
      setTimeout(() => { if (getUser()) enterNeedToQuote(); }, 300);
    }
  } catch (_) {}
})();

// ---- Purchaser screen: pending reorder requests -----------------------------
function enterPurchaser() {
  showScreen("purchase");
  loadPartRequests();
}

// Which orders the purchaser is looking at. Need to Order is the default: it
// is the work. Ordered is the record it leaves, kept for looking things up.
let puStatus = "PENDING";
$("pu-filters").querySelectorAll(".pu-chip").forEach((chip) =>
  chip.addEventListener("click", () => {
    puStatus = chip.dataset.status;
    $("pu-filters").querySelectorAll(".pu-chip").forEach((c) =>
      c.classList.toggle("pu-chip-on", c === chip));
    loadPartRequests();
  })
);

async function loadPartRequests() {
  const wrap = $("pu-list");
  wrap.innerHTML = `<div class="fp-loading">Loading orders…</div>`;
  try {
    const rows = await api(`/api/part-requests?status=${encodeURIComponent(puStatus)}`);
    if (!rows.length) {
      wrap.innerHTML = `<div class="fp-empty">${
        puStatus === "PENDING" ? "Nothing waiting to be ordered"
        : puStatus === "ORDERED" ? "Nothing has been ordered yet" : "No orders yet"}</div>`;
      return;
    }

    // One card per ORDER, not per part: a bulk order was submitted together and
    // is reviewed and marked together. Rows already arrive newest first; the
    // batch keeps its place by its newest row.
    const batches = [];
    const byId = new Map();
    for (const r of rows) {
      const key = r.batch_id || "R" + r.id;
      if (!byId.has(key)) { byId.set(key, { key, rows: [] }); batches.push(byId.get(key)); }
      byId.get(key).rows.push(r);
    }

    const qty = (v) => (v === null || v === undefined ? "—"
      : Number.isInteger(Number(v)) ? String(v) : Number(v).toFixed(2));
    const day = (t) => String(t || "").split(" ")[0];

    wrap.innerHTML = batches.map((b) => {
      const first = b.rows[b.rows.length - 1]; // oldest row carries the submission
      const pending = b.rows.some((r) => r.status === "PENDING");
      // The order's own note; the same value rides on every row of the batch.
      const orderRemark = first.batch_remarks || "";

      const lines = b.rows.slice().reverse().map((r) => {
        // The balance WHEN THE ORDER WAS MADE - the context of the decision.
        // John chose this over live stock; rows from before the change have
        // none and show a dash.
        const cur = qty(r.stock_at_request);
        const low = r.stock_at_request !== null && r.stock_at_request !== undefined && Number(r.stock_at_request) <= 0;
        return `
        <div class="pu-line">
          <div class="pu-line-main">
            <div class="pu-desc">${escapeHtml(r.description || r.item_code)}</div>
            <div class="pu-code mono">${escapeHtml(r.item_code)}</div>
            ${r.remarks ? `<div class="pu-remarks">“${escapeHtml(r.remarks)}”</div>` : ""}
          </div>
          <div class="pu-line-qty">
            <span class="pu-lbl">Order</span><span class="pu-val">${r.qty_requested}</span>
            <span class="pu-lbl">Stock then</span><span class="pu-val ${low ? "fp-qty-zero" : ""}">${cur}</span>
          </div>
        </div>`;
      }).join("");

      if (pending && puEditing === b.key) return renderOrderEditCard(b);

      // Actions live under the order, not beside its heading: you read what was
      // asked for and then act on it. Three buttons sharing a row with the
      // status and the date left every one of them wrapping on a phone.
      const canManage = ["purchaser", "admin"].includes(getRole());
      const actions = [
        pending && canDecide() ? `<button class="pu-edit" data-edit="${escapeAttr(b.key)}">Edit</button>` : "",
        canManage ? `<button class="pu-delete" data-delete="${escapeAttr(b.key)}">Delete</button>` : "",
        pending && canManage ? `<button class="pu-done" data-batch="${escapeAttr(b.key)}">Mark as Ordered</button>` : "",
      ].filter(Boolean).join("");

      return `
      <div class="pu-card ${pending ? "pu-card-pending" : "pu-card-ordered"}">
        <div class="pu-top">
          <span class="pu-status ${pending ? "pu-st-need" : "pu-st-done"}">${pending ? "Need to Order" : "Ordered"}</span>
          <span class="pu-meta">${escapeHtml(first.requester || "—")} · ${
            // On an ordered card the date worth showing is when it was ORDERED,
            // not when it was asked for. Showing both ran past the width of a
            // phone and the ellipsis ate the one that mattered.
            !pending && (b.rows[0].ordered_at || first.ordered_at)
              ? "ordered " + escapeHtml(day(b.rows[0].ordered_at || first.ordered_at))
              : escapeHtml(day(first.created_at))}</span>
        </div>
        ${lines}
        ${orderRemark ? `<div class="pu-remarks">“${escapeHtml(orderRemark)}”</div>` : ""}
        ${actions ? `<div class="pu-actions">${actions}</div>` : ""}
      </div>`;
    }).join("");

    wrap.querySelectorAll(".pu-edit").forEach((btn) =>
      btn.addEventListener("click", () => { puEditing = btn.dataset.edit; loadPartRequests(); })
    );
    // Deleting is the one action here with no undo, so the confirmation names
    // every part that will go, and says plainly that it cannot be undone.
    wrap.querySelectorAll(".pu-delete").forEach((btn) =>
      btn.addEventListener("click", async () => {
        const b = byId.get(btn.dataset.delete);
        if (!b) return;
        const what = b.rows.map((r) => `  ${r.qty_requested} × ${r.description || r.item_code}`).join("\n");
        const state = b.rows.some((r) => r.status === "PENDING") ? "Need to Order" : "Ordered";
        if (!confirm(
          `Delete this ${state} order?\n\n${what}\n\nThis cannot be undone.`
        )) return;
        btn.disabled = true;
        try {
          const me = getUser();
          await api(`/api/part-requests/batch/${encodeURIComponent(btn.dataset.delete)}` +
                    `?role=${encodeURIComponent(getRole())}&who=${encodeURIComponent(initialsFor(me))}`,
                    { method: "DELETE" });
          toast("Order deleted", "ok");
          if (puEditing === btn.dataset.delete) puEditing = null;
          loadPartRequests();
        } catch (e) {
          toast(e.message, "err");
          btn.disabled = false;
        }
      })
    );
    wireOrderEditCard(wrap);
    wrap.querySelectorAll(".pu-done").forEach((btn) =>
      btn.addEventListener("click", async () => {
        if (!confirm("Mark this order as Ordered?\n\nDo this once it has been transferred to a Purchase Order.")) return;
        btn.disabled = true;
        try {
          await api(`/api/part-requests/batch/${encodeURIComponent(btn.dataset.batch)}/ordered`, { method: "PATCH" });
          toast("Marked as Ordered", "ok");
          loadPartRequests();
        } catch (e) {
          toast(e.message, "err");
          btn.disabled = false;
        }
      })
    );
  } catch (e) {
    wrap.innerHTML = "";
    toast(e.message, "err");
  }
}

// ---- Editing a pending order -------------------------------------------------
// In place, on the card. Once Ordered it is a record and the button is gone.
// Saving asks for confirmation with a summary of exactly what will change.
let puEditing = null;

function renderOrderEditCard(b) {
  const first = b.rows[b.rows.length - 1];
  const lines = b.rows.slice().reverse().map((r) => `
    <div class="pu-edit-line" data-line="${r.id}"${r.free_text ? ' data-placeholder="1"' : ""} data-was="${escapeAttr(r.description || "")}">
      <div class="pu-line-main">
        ${r.free_text
          ? `<input class="pu-edesc" type="text" value="${escapeAttr(r.description || "")}" aria-label="What this part is" />`
          : `<div class="pu-desc">${escapeHtml(r.description || r.item_code)}</div>`}
        <div class="pu-code mono">${escapeHtml(r.item_code)}</div>
      </div>
      <input class="pu-eqty" type="number" min="1" inputmode="numeric" value="${r.qty_requested}" aria-label="Quantity" />
      <button type="button" class="pu-eremove" aria-label="Remove line">&#10005;</button>
    </div>
    <textarea class="pu-eremarks" data-line="${r.id}" placeholder="Remarks for this part (optional)">${escapeHtml(r.remarks || "")}</textarea>`).join("");
  return `
  <div class="pu-card pu-card-pending" data-editing="${escapeAttr(b.key)}">
    <div class="pu-top">
      <span class="pu-status pu-st-need">Editing</span>
      <span class="pu-meta">${escapeHtml(first.requester || "—")} · tap &#10005; to remove a line</span>
    </div>
    ${lines}
    <textarea class="pu-eremarks" id="pu-eorder-remarks" placeholder="Remarks for the whole order (optional)">${escapeHtml(first.batch_remarks || "")}</textarea>
    <div class="pu-edit-actions">
      <button type="button" class="btn-secondary" data-edit-cancel>Cancel</button>
      <button type="button" class="btn-primary" data-edit-save>Save changes</button>
    </div>
  </div>`;
}

function wireOrderEditCard(wrap) {
  const card = wrap.querySelector("[data-editing]");
  if (!card) return;
  card.querySelectorAll(".pu-eremove").forEach((btn) =>
    btn.addEventListener("click", () => {
      const line = btn.closest(".pu-edit-line");
      line.classList.toggle("pu-removed");
      btn.textContent = line.classList.contains("pu-removed") ? "↩" : "\u2715";
    })
  );
  card.querySelector("[data-edit-cancel]").addEventListener("click", () => {
    puEditing = null;
    loadPartRequests();
  });
  card.querySelector("[data-edit-save]").addEventListener("click", async () => {
    const lines = [];
    const summary = [];
    let bad = null;
    let unnamed = null;
    card.querySelectorAll(".pu-edit-line").forEach((el) => {
      const id = Number(el.dataset.line);
      const descInput = el.querySelector(".pu-edesc");
      const was = el.dataset.was || "";
      const desc = descInput ? descInput.value.trim() : el.querySelector(".pu-desc").textContent;
      if (el.classList.contains("pu-removed")) {
        lines.push({ id, remove: true });
        summary.push(`Remove ${was || desc}`);
        return;
      }
      const q = parseInt(el.querySelector(".pu-eqty").value, 10);
      if (!Number.isFinite(q) || q < 1) { bad = was || desc; return; }
      // A placeholder code carries no name of its own, so an empty box would
      // leave the purchaser with nothing to buy.
      if (descInput && !desc) { unnamed = el.querySelector(".pu-code").textContent; return; }
      const rk = (card.querySelector(`.pu-eremarks[data-line="${id}"]`) || { value: "" }).value.trim();
      const line = { id, qty_requested: q, remarks: rk };
      if (descInput) line.description = desc;
      lines.push(line);
      if (descInput && desc !== was) summary.push(`“${was}” → “${desc}”`);
      summary.push(`${desc}: qty ${q}${rk ? ` — “${rk}”` : ""}`);
    });
    if (bad) { toast(`Quantity for ${bad} must be at least 1`, "err"); return; }
    if (unnamed) { toast(`${unnamed} is a placeholder code — type what to order`, "err"); return; }
    const orderRemarks = $("pu-eorder-remarks").value.trim();
    if (orderRemarks) summary.push(`Order remarks: “${orderRemarks}”`);

    if (!confirm(`Save these changes?\n\n${summary.join("\n")}`)) return;
    try {
      await api(`/api/part-requests/batch/${encodeURIComponent(card.dataset.editing)}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ role: getRole(), lines, batch_remarks: orderRemarks }),
      });
      toast("Order updated", "ok");
      puEditing = null;
      loadPartRequests();
    } catch (e) {
      alert(e.message || "Could not save the edit");
    }
  });
}

// ---- Bulk Order --------------------------------------------------------------
// A cart. Parts are added one at a time from the same live search Find Part
// uses, quantities adjusted in place, and NOTHING reaches the purchaser until
// Submit - so a half-built list costs nothing and can simply be walked away
// from. Submitting sends the lot as ONE order for her to review.
let boCart = [];   // { item_code, description, qty }

function enterBulkOrder() {
  boCart = [];
  $("bo-q").value = "";
  $("bo-results").innerHTML = "";
  $("bo-remarks").value = "";
  renderBulkCart();
  showScreen("bulk");
  setTimeout(() => $("bo-q").focus(), 50);
}

let boDebounce = null;
$("bo-q").addEventListener("input", () => {
  clearTimeout(boDebounce);
  const q = $("bo-q").value.trim();
  const box = $("bo-results");
  if (q.length < 2) { box.innerHTML = ""; return; }
  boDebounce = setTimeout(async () => {
    try {
      const data = await api(`/api/parts-search?q=${encodeURIComponent(q)}`);
      const list = data.results || [];
      if (!list.length) { box.innerHTML = `<div class="fp-empty">No matching parts</div>`; return; }
      box.innerHTML = list.map((r) => `
        <button type="button" class="company-option" data-code="${escapeAttr(r.item_code)}" data-desc="${escapeAttr(r.description)}">
          <span class="fp-opt-desc">${escapeHtml(r.description)}${r.desc2 ? ` <span class="fp-val-model">${escapeHtml(r.desc2)}</span>` : ""}</span>
          <span class="fp-opt-code mono">${escapeHtml(r.item_code)}</span>
        </button>`).join("");
      box.querySelectorAll(".company-option").forEach((b) =>
        b.addEventListener("click", () => {
          addToBulkCart(b.dataset.code, b.dataset.desc);
          $("bo-q").value = "";
          box.innerHTML = "";
          $("bo-q").focus();
        })
      );
    } catch (e) {
      box.innerHTML = `<div class="fp-empty">${escapeHtml(e.message || "Search failed")}</div>`;
    }
  }, 250);
});

function addToBulkCart(code, desc) {
  // A placeholder code needs naming as it goes in - and two of them are two
  // DIFFERENT things, so they never merge the way a repeated real part does.
  if (isFreeTextPart(code, desc)) {
    const typed = prompt(`${code}\n\nWhat is this part? The purchaser sees this, not the code.`, "");
    if (typed === null) return;
    const name = typed.trim();
    if (!name) { toast("A placeholder part needs a name", "err"); return; }
    boCart.push({ item_code: code, description: name, qty: 1, remarks: "", placeholder: true });
    renderBulkCart();
    return;
  }
  // The same ordinary part tapped twice means "more of it", not an error.
  const hit = boCart.find((c) => c.item_code === code && !c.placeholder);
  if (hit) hit.qty += 1;
  else boCart.push({ item_code: code, description: desc || code, qty: 1, remarks: "" });
  renderBulkCart();
}

function renderBulkCart() {
  const wrap = $("bo-cart");
  const has = boCart.length > 0;
  $("bo-remarks-field").style.display = has ? "" : "none";
  $("bo-submit").style.display = has ? "" : "none";
  $("bo-submit").textContent = `Submit order (${boCart.length} part${boCart.length === 1 ? "" : "s"})`;
  delete $("bo-submit").dataset.armed;
  if (!has) {
    wrap.innerHTML = `<div class="fp-empty">No parts added yet — search above to build the order</div>`;
    return;
  }
  wrap.innerHTML = boCart.map((c, i) => `
    <div class="bo-item">
      <div class="bo-line">
        <div class="bo-line-main">
          <div class="pu-desc">${escapeHtml(c.description)}${
            c.placeholder
              ? ` <button type="button" class="desc-edit" data-bdesc="${i}" aria-label="Edit description">${PENCIL}</button>`
              : ""
          }</div>
          <div class="pu-code mono">${escapeHtml(c.item_code)}</div>
        </div>
        <input class="bo-qty" type="number" min="1" inputmode="numeric" value="${c.qty}" data-i="${i}" aria-label="Quantity" />
        <button type="button" class="bo-remove" data-i="${i}" aria-label="Remove">&#10005;</button>
      </div>
      <textarea class="bo-line-remarks" data-i="${i}" placeholder="Remarks for this part (optional)">${escapeHtml(c.remarks || "")}</textarea>
    </div>`).join("");
  wrap.querySelectorAll(".bo-line-remarks").forEach((ta) =>
    ta.addEventListener("input", () => { boCart[Number(ta.dataset.i)].remarks = ta.value; })
  );
  wrap.querySelectorAll("[data-bdesc]").forEach((btn) =>
    btn.addEventListener("click", () => {
      const c = boCart[Number(btn.dataset.bdesc)];
      if (!c) return;
      const typed = prompt("What is this part? The purchaser sees this, not the code.", c.description || "");
      if (typed !== null && typed.trim()) { c.description = typed.trim().slice(0, 200); renderBulkCart(); }
    })
  );
  wrap.querySelectorAll(".bo-qty").forEach((inp) =>
    inp.addEventListener("change", () => {
      const n = parseInt(inp.value, 10);
      const c = boCart[Number(inp.dataset.i)];
      if (c && Number.isFinite(n) && n >= 1) { c.qty = n; }
      else if (c) { inp.value = c.qty; }
      delete $("bo-submit").dataset.armed;
      $("bo-submit").textContent = `Submit order (${boCart.length} part${boCart.length === 1 ? "" : "s"})`;
    })
  );
  wrap.querySelectorAll(".bo-remove").forEach((btn) =>
    btn.addEventListener("click", () => {
      boCart.splice(Number(btn.dataset.i), 1);
      renderBulkCart();
    })
  );
}

// ---- Diesel -----------------------------------------------------------------
// The workshop runs on it, the purchaser always orders the same amount, and
// AutoCount does not stock it - so there is no part to search for and no
// quantity worth asking. One button, sent as a free-text line so it lands in
// the purchaser's list beside everything else and gets the same Need to Order
// / Ordered treatment.
//
// Armed on the first tap like the order button below it, because a single tap
// that quietly orders a drum of diesel is a tap somebody will regret.
const DIESEL_LINE = {
  item_code: "DIESEL",
  // Must differ from the code itself, or the server rejects it as a
  // placeholder with no description - which is the right rule for a part
  // somebody typed, and this has to satisfy it too.
  description: "Diesel — usual amount",
  qty_requested: 1,
  free_text: true,
};

function disarmDiesel() {
  const btn = $("bo-diesel");
  if (!btn) return;
  delete btn.dataset.armed;
  btn.classList.remove("armed");
  btn.innerHTML = dieselIdleHtml;
}
let dieselIdleHtml = "";

$("bo-diesel").addEventListener("click", async () => {
  const btn = $("bo-diesel");
  if (!dieselIdleHtml) dieselIdleHtml = btn.innerHTML;
  const requester = userName();
  if (!requester) { toast("Choose your name from the top bar first", "err"); return; }

  if (!btn.dataset.armed) {
    btn.dataset.armed = "1";
    btn.classList.add("armed");
    btn.textContent = "Tap again to send";
    return;
  }

  btn.disabled = true;
  btn.textContent = "Sending…";
  try {
    await api(`/api/part-requests/bulk`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ requester, batch_remarks: "", items: [DIESEL_LINE] }),
    });
    toast("Diesel order sent to the purchaser", "ok");
  } catch (e) {
    toast(e.message || "Could not send the order", "err");
  }
  btn.disabled = false;
  disarmDiesel();
});

$("bo-submit").addEventListener("click", async () => {
  if (!boCart.length) return;
  const requester = userName();
  if (!requester) { toast("Choose your name from the top bar first", "err"); return; }
  const btn = $("bo-submit");

  // Two taps, like everything else that sends: the first shows the total, the
  // second commits. Editing the cart in between disarms it.
  if (!btn.dataset.armed) {
    const total = boCart.reduce((n, c) => n + c.qty, 0);
    btn.dataset.armed = "1";
    btn.textContent = `Tap again to send — ${boCart.length} part${boCart.length === 1 ? "" : "s"}, ${total} pcs`;
    return;
  }

  btn.disabled = true;
  try {
    await api(`/api/part-requests/bulk`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        requester,
        batch_remarks: $("bo-remarks").value.trim(),
        items: boCart.map((c) => ({
          item_code: c.item_code,
          description: c.description,
          qty_requested: c.qty,
          remarks: (c.remarks || "").trim(),
          free_text: !!c.placeholder,
        })),
      }),
    });
    toast("Order submitted", "ok");
    boCart = [];
    $("bo-remarks").value = "";
    renderBulkCart();
  } catch (e) {
    // The repository reports every problem at once; show them all.
    alert(e.message || "Could not submit the order");
    delete btn.dataset.armed;
    renderBulkCart();
  }
  btn.disabled = false;
});

