// ---- Customer signature pad (New Service) ----------------------------------
// The customer signs with a finger at the counter; the drawing is printed onto
// the slip PDF above the signature line, beside the terms they are accepting.
//
// Drawn on a device-pixel-ratio-scaled canvas so strokes stay sharp on phones,
// and exported trimmed to the ink so the PDF gets a tight image rather than a
// mostly-empty rectangle.
const sigPad = { ctx: null, canvas: null, drawing: false, dirty: false, last: null, bounds: null };

function sigPadSetup() {
  const canvas = $("ns-sig-canvas");
  if (!canvas || sigPad.canvas) return;
  sigPad.canvas = canvas;
  sigPad.ctx = canvas.getContext("2d");
  sigPadResize();

  const pos = (e) => {
    const r = canvas.getBoundingClientRect();
    return { x: e.clientX - r.left, y: e.clientY - r.top };
  };

  canvas.addEventListener("pointerdown", (e) => {
    e.preventDefault();
    canvas.setPointerCapture(e.pointerId);
    sigPad.drawing = true;
    sigPad.last = pos(e);
    sigPadMark(sigPad.last);
    // A tap with no drag should still leave a dot.
    const c = sigPad.ctx;
    c.beginPath();
    c.arc(sigPad.last.x, sigPad.last.y, c.lineWidth / 2, 0, Math.PI * 2);
    c.fill();
  });

  canvas.addEventListener("pointermove", (e) => {
    if (!sigPad.drawing) return;
    e.preventDefault();
    const p = pos(e);
    const c = sigPad.ctx;
    c.beginPath();
    c.moveTo(sigPad.last.x, sigPad.last.y);
    c.lineTo(p.x, p.y);
    c.stroke();
    sigPad.last = p;
    sigPadMark(p);
  });

  const end = (e) => {
    if (!sigPad.drawing) return;
    sigPad.drawing = false;
    try { canvas.releasePointerCapture(e.pointerId); } catch (_) {}
  };
  canvas.addEventListener("pointerup", end);
  canvas.addEventListener("pointercancel", end);
  canvas.addEventListener("pointerleave", end);

  $("ns-sig-clear").addEventListener("click", () => { sigPadClear(); renderSigPreview(); });
  window.addEventListener("resize", sigPadResize);
  $("ns-sig-open").addEventListener("click", openSigModal);
  $("sig-close").addEventListener("click", closeSigModal);
  $("sig-done").addEventListener("click", closeSigModal);
  // Tapping the backdrop closes it, but only the backdrop - a stray touch that
  // lands on the pad is a signature, not a dismissal.
  $("sig-modal").addEventListener("click", (e) => { if (e.target === $("sig-modal")) closeSigModal(); });
}

// Track the inked area so the export can be trimmed to it.
function sigPadMark(p) {
  if (!sigPad.dirty) {
    sigPad.dirty = true;
    $("ns-sig-pad").classList.add("signed");
  }
  const b = sigPad.bounds;
  if (!b) sigPad.bounds = { x1: p.x, y1: p.y, x2: p.x, y2: p.y };
  else {
    if (p.x < b.x1) b.x1 = p.x;
    if (p.y < b.y1) b.y1 = p.y;
    if (p.x > b.x2) b.x2 = p.x;
    if (p.y > b.y2) b.y2 = p.y;
  }
}

function sigPadResize() {
  const canvas = sigPad.canvas;
  if (!canvas) return;
  // Resizing clears the bitmap, so only do it while the pad is still empty.
  if (sigPad.dirty) return;
  const r = canvas.getBoundingClientRect();
  if (!r.width || !r.height) return;
  const dpr = Math.min(window.devicePixelRatio || 1, 3);
  canvas.width = Math.round(r.width * dpr);
  canvas.height = Math.round(r.height * dpr);
  const c = sigPad.ctx;
  c.setTransform(dpr, 0, 0, dpr, 0, 0);
  c.lineWidth = 2.4;
  c.lineCap = "round";
  c.lineJoin = "round";
  c.strokeStyle = "#16241f";
  c.fillStyle = "#16241f";
}

// The pad now lives on a popup, so it measures zero until that popup is
// actually on screen. This is the same trap that produced a stretched 300x150
// signature before, one layer deeper: size it when the modal opens, never on a
// screen change.
function openSigModal() {
  $("sig-modal").style.display = "flex";
  document.body.style.overflow = "hidden";
  // Measure straight away. Reading the pad's size forces layout, so the
  // popup's real dimensions are already available on this line.
  //
  // Do NOT reach for requestAnimationFrame here: it does not fire at all while
  // the document is hidden, and the canvas would silently keep its 300x150
  // default - a stretched, blurry signature on the customer's slip. The timer
  // below is only a safety net for a pad that genuinely has no size yet.
  sigPadResize();
  sizeSigPadWhenVisible();
}

// Third time this canvas has been caught measuring nothing, so it keeps
// checking rather than assuming. Stops as soon as the bitmap matches the pad,
// and sigPadResize refuses to touch a pad that has been drawn on.
function sizeSigPadWhenVisible(tries = 20) {
  const c = sigPad.canvas;
  if (!c || sigPad.dirty) return;
  const r = c.getBoundingClientRect();
  const dpr = Math.min(window.devicePixelRatio || 1, 3);
  if (r.width && r.height && Math.abs(c.width - r.width * dpr) < 2) return;
  if (r.width && r.height) sigPadResize();
  if (tries > 0) setTimeout(() => sizeSigPadWhenVisible(tries - 1), 30);
}

function closeSigModal() {
  $("sig-modal").style.display = "none";
  document.body.style.overflow = "";
  renderSigPreview();
}

// Show what was signed on the form itself, so nobody has to reopen the pad to
// check whether a customer actually signed.
function renderSigPreview() {
  const box = $("ns-sig-preview");
  const label = $("ns-sig-open-label");
  if (!box) return;
  const data = sigPadData();
  if (!data) {
    box.style.display = "none";
    box.innerHTML = "";
    if (label) label.textContent = "Sign here";
    return;
  }
  box.innerHTML = `<img src="${data}" alt="Customer signature">`;
  box.style.display = "block";
  if (label) label.textContent = "Signed — tap to sign again";
}

function sigPadClear() {
  const canvas = sigPad.canvas;
  sigPad.dirty = false;
  sigPad.bounds = null;
  sigPad.drawing = false;
  const pad = $("ns-sig-pad");
  if (pad) pad.classList.remove("signed");
  if (!canvas || !sigPad.ctx) return;
  sigPad.ctx.clearRect(0, 0, canvas.width, canvas.height);
  sigPadResize();
}

// Export the signature as a trimmed PNG data URL, or "" if nothing was drawn.
function sigPadData() {
  if (!sigPad.dirty || !sigPad.canvas || !sigPad.bounds) return "";
  const dpr = Math.min(window.devicePixelRatio || 1, 3);
  const b = sigPad.bounds;
  const pad = 8;
  const x = Math.max(0, (b.x1 - pad)) * dpr;
  const y = Math.max(0, (b.y1 - pad)) * dpr;
  const w = Math.min(sigPad.canvas.width - x, (b.x2 - b.x1 + pad * 2) * dpr);
  const h = Math.min(sigPad.canvas.height - y, (b.y2 - b.y1 + pad * 2) * dpr);
  if (w <= 0 || h <= 0) return "";
  try {
    const out = document.createElement("canvas");
    out.width = Math.round(w);
    out.height = Math.round(h);
    out.getContext("2d").drawImage(sigPad.canvas, x, y, w, h, 0, 0, out.width, out.height);
    return out.toDataURL("image/png");
  } catch (_) {
    return "";
  }
}

sigPadSetup();

// ---- IPL: illustrated parts list --------------------------------------------
// Data comes from tools/ipl-extract.js, which reads the manufacturer's IPL PDF.
// Callout coordinates are lifted from the PDF's own text layer, so the hotspots
// sit exactly on the printed numbers rather than being placed by hand.
const ipl = { models: null, model: null, figure: null, selectedKey: null, q: "", type: "" };

// The last few models this phone opened, most recent first. Per device rather
// than per account: it is a convenience, not a record, and it never leaves the
// phone.
const IPL_RECENT_KEY = "om_ipl_recent";
const IPL_RECENT_MAX = 3;

function iplRecent() {
  try {
    const v = JSON.parse(localStorage.getItem(IPL_RECENT_KEY) || "[]");
    return Array.isArray(v) ? v.filter((x) => typeof x === "string") : [];
  } catch (_) {
    return [];
  }
}

function iplRemember(id) {
  const next = [id].concat(iplRecent().filter((x) => x !== id)).slice(0, IPL_RECENT_MAX);
  try { localStorage.setItem(IPL_RECENT_KEY, JSON.stringify(next)); } catch (_) {}
}

async function enterIpl() {
  showScreen("ipl");
  if (!ipl.models) {
    try {
      ipl.models = await api("./ipl/index.json");
    } catch (_) {
      ipl.models = [];
    }
  }
  showIplPicker();
}

// Each brand's own colour, sampled from the logo files the marketing folder
// keeps at M:\SALES_&_MARKETING\WEBSITE IMAGES\Brand Logos, then darkened until
// it is legible — the same thing the stylesheet does to the OM gradient, which
// fails contrast at full strength. `fill` carries white text on the tile;
// `ink` is the brand name on the picker's ground. Both clear 4.5:1.
//
// Every brand in that folder is listed, not just the two with IPLs loaded, so
// the first Ferris or Billy Goat book arrives already in its own colour.
//
// `logo` is the plate built by tools/build-brand-logos.py from those same
// files: the logo on its own background, trimmed and sized, because these come
// drawn for different grounds — Husqvarna's is white on navy, Zenoah's is white
// text that would vanish without the black behind it, and the rest are coloured
// artwork made for white.
// `w` is the plate's width in CSS pixels at its 30px height, so the browser
// reserves the right space and the heading does not jump when the logo lands.
const IPL_BRAND_COLOUR = {
  husqvarna:   { fill: "#183060", ink: "#183060", logo: "husqvarna",   w: 37 },  // logo navy
  zenoah:      { fill: "#dc3030", ink: "#ce2d2d", logo: "zenoah",      w: 84 },  // logo red
  billygoat:   { fill: "#008050", ink: "#008050", logo: "billygoat",   w: 30 },
  ferris:      { fill: "#8f1020", ink: "#8f1020", logo: "ferris",      w: 32 },
  grasshopper: { fill: "#e01020", ink: "#d20f1e", logo: "grasshopper", w: 63 },
  pulsfog:     { fill: "#e12d3c", ink: "#d32a38", logo: "pulsfog",     w: 84 },
  rayco:       { fill: "#91691a", ink: "#886218", logo: "rayco",       w: 84 },
};
// An unknown brand falls back to the app's own teal rather than to grey, so a
// new brand looks deliberate on the day it lands.
const IPL_BRAND_FALLBACK = { fill: "#0a7f86", ink: "#0a7f86" };

function iplBrandColour(brand) {
  const key = String(brand || "").toLowerCase().replace(/[^a-z0-9]/g, "");
  return IPL_BRAND_COLOUR[key] || IPL_BRAND_FALLBACK;
}

// One big letter for a one-word brand, initials for the rest: "H", "Z",
// "BG" — rather than the first two letters, which gives "BI" for Billy Goat.
function iplBrandInitials(brand) {
  const words = String(brand || "").trim().split(/\s+/).filter(Boolean);
  if (words.length > 1) return words.slice(0, 2).map((w) => w[0]).join("").toUpperCase();
  return (words[0] || "?").slice(0, 1).toUpperCase();
}

// Models added before the picker existed have no brand or category, so fall
// back rather than dropping them out of the list entirely.
function iplBrand(m) { return m.brand || String(m.name || "").split(" ")[0] || "Other"; }
function iplShort(m) { return m.short || m.name || m.id; }
function iplCategory(m) { return m.category || ""; }

function iplMatches(m, q) {
  if (!q) return true;
  const hay = `${iplBrand(m)} ${iplShort(m)} ${m.name} ${iplCategory(m)}`.toLowerCase();
  if (hay.includes(q)) return true;
  // Also match with punctuation dropped, so "bk3410" finds "BK3410FL / FL-S"
  // and "pht750" finds "PHT750 / PHT1200 / PHT1500".
  const strip = (s) => s.replace(/[^a-z0-9]/g, "");
  return strip(hay).includes(strip(q));
}

// Highlight the matched run, so it is obvious why a row is showing when the
// match was in the machine type rather than the name you were reading.
function iplMark(text, q) {
  const s = String(text || "");
  if (!q) return escapeHtml(s);
  const i = s.toLowerCase().indexOf(q);
  if (i < 0) return escapeHtml(s);
  return escapeHtml(s.slice(0, i)) + "<mark>" + escapeHtml(s.slice(i, i + q.length)) +
         "</mark>" + escapeHtml(s.slice(i + q.length));
}

function showIplPicker() {
  $("ipl-picker").style.display = "";
  $("ipl-viewer").style.display = "none";
  renderIplPicker();
}

function renderIplPicker() {
  const all = ipl.models || [];
  const box = $("ipl-models");

  if (!all.length) {
    $("ipl-types").innerHTML = "";
    $("ipl-recent").innerHTML = "";
    box.innerHTML = `<div class="mp-empty"><strong>No IPLs installed yet</strong>Ask John to add one.</div>`;
    return;
  }

  const q = ipl.q.trim().toLowerCase();
  $("ipl-search-clear").classList.toggle("on", !!ipl.q);

  // Type chips, commonest first, counted from the data — a category with
  // nothing in it never appears.
  const counts = new Map();
  all.forEach((m) => {
    const c = iplCategory(m);
    if (c) counts.set(c, (counts.get(c) || 0) + 1);
  });
  const types = [...counts.entries()].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]));
  // A filter matching nothing would leave a blank screen; drop it instead.
  if (ipl.type && !counts.has(ipl.type)) ipl.type = "";

  $("ipl-types").innerHTML =
    `<button type="button" class="mp-chip" data-type="" aria-pressed="${!ipl.type}">All ${all.length}</button>` +
    types.map(([t, n]) =>
      `<button type="button" class="mp-chip" data-type="${escapeAttr(t)}" aria-pressed="${ipl.type === t}">${escapeHtml(t)} ${n}</button>`
    ).join("");
  $("ipl-types").querySelectorAll(".mp-chip").forEach((c) =>
    c.addEventListener("click", () => {
      ipl.type = ipl.type === c.dataset.type ? "" : c.dataset.type;
      renderIplPicker();
    })
  );

  // Recently opened, but only while nothing is being narrowed — with a search
  // running it is just a second list competing with the results.
  const recent = (!q && !ipl.type)
    ? iplRecent().map((id) => all.find((m) => m.id === id)).filter(Boolean)
    : [];
  $("ipl-recent").innerHTML = recent.length
    ? `<div class="mp-lab">Recently opened</div><div class="mp-recent-row">` +
      recent.map((m) =>
        `<button type="button" class="mp-rc" data-id="${escapeAttr(m.id)}">
           <strong>${escapeHtml(iplShort(m))}</strong>
           <small>${escapeHtml(iplBrand(m))}${iplCategory(m) ? " &middot; " + escapeHtml(iplCategory(m)) : ""}</small>
         </button>`).join("") + `</div>`
    : "";

  const list = all.filter((m) =>
    (!ipl.type || iplCategory(m) === ipl.type) && iplMatches(m, q)
  );

  if (!list.length) {
    box.innerHTML =
      `<div class="mp-empty"><strong>Nothing matches &ldquo;${escapeHtml(ipl.q)}&rdquo;</strong>` +
      `Try the model number printed on the machine.</div>`;
    wireIplPicks();
    return;
  }

  const byBrand = new Map();
  list.forEach((m) => {
    const b = iplBrand(m);
    if (!byBrand.has(b)) byBrand.set(b, []);
    byBrand.get(b).push(m);
  });

  const byName = (x, y) => iplShort(x).localeCompare(iplShort(y), undefined, { numeric: true });

  const rowHtml = (m) =>
    `<button type="button" class="mp-row" data-id="${escapeAttr(m.id)}">
       <span class="txt">
         <span class="nm">${iplMark(iplShort(m), q)}</span>
         <span class="mt">${m.figures} figure${m.figures === 1 ? "" : "s"}${m.parts ? " &middot; " + m.parts + " parts" : ""}</span>
       </span>
       <svg class="chev" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M9 18l6-6-6-6"/></svg>
     </button>`;

  box.innerHTML = [...byBrand.keys()].sort().map((b) => {
    const models = byBrand.get(b);
    const col = iplBrandColour(b);
    // The logo where we hold one, the coloured initials where we do not — so a
    // brand nobody has supplied artwork for still reads as a proper heading.
    const badge = col.logo
      ? `<img class="mp-glogo" src="./ipl/brands/${encodeURIComponent(col.logo)}.png" alt="" width="${col.w}" height="30">`
      : `<span class="mp-gmark">${escapeHtml(iplBrandInitials(b))}</span>`;

    // Within a brand, group by machine type. Alphabetical rather than by count:
    // a category has to keep its place in the list as models are added to it,
    // or nobody can learn where anything is.
    const byCat = new Map();
    models.forEach((m) => {
      const c = iplCategory(m) || "Other";
      if (!byCat.has(c)) byCat.set(c, []);
      byCat.get(c).push(m);
    });
    const cats = [...byCat.keys()].sort((x, y) =>
      x === "Other" ? 1 : y === "Other" ? -1 : x.localeCompare(y)
    );

    // A category label repeating the chip you just tapped says nothing, so with
    // a type filter running the rows are listed plainly instead.
    const showCats = !ipl.type;

    const body = cats.map((c) => {
      const rows = byCat.get(c).slice().sort(byName);
      const label = showCats
        ? `<div class="mp-clab">${iplMark(c, q)}<b>${rows.length}</b></div>`
        : "";
      return label + `<div class="mp-rows">${rows.map(rowHtml).join("")}</div>`;
    }).join("");

    return `<div class="mp-group">
      <div class="mp-ghead" style="--brand-fill:${col.fill};--brand-ink:${col.ink};">
        ${badge}
        <strong>${escapeHtml(b)}</strong><span class="n">${models.length}</span>
      </div>${body}</div>`;
  }).join("");

  wireIplPicks();
}

function wireIplPicks() {
  document.querySelectorAll("#ipl-picker .mp-row, #ipl-picker .mp-rc").forEach((b) =>
    b.addEventListener("click", () => openIplModel(b.dataset.id))
  );
}

async function openIplModel(id) {
  const entry = (ipl.models || []).find((m) => m.id === id);
  if (!entry) return;
  const ok = await loadIplModel(id);
  if (!ok) return;
  iplRemember(id);
  $("ipl-chosen-name").textContent = `${iplBrand(entry)} ${iplShort(entry)}`.trim();
  $("ipl-chosen-meta").textContent =
    [iplCategory(entry), `${entry.figures} figure${entry.figures === 1 ? "" : "s"}`]
      .filter(Boolean).join(" · ");
  $("ipl-picker").style.display = "none";
  $("ipl-viewer").style.display = "";
  window.scrollTo({ top: 0 });
  syncIplStageSize();
}

async function loadIplModel(id) {
  try {
    ipl.model = await api(`./ipl/${encodeURIComponent(id)}.json`);
  } catch (e) {
    toast("Couldn't load that IPL", "err");
    return false;
  }
  // Selected by id, not by the printed figure number — a figure can span
  // several sheets and they would otherwise collide.
  $("ipl-figs").innerHTML = ipl.model.figures.map((f, i) =>
    `<button type="button" class="ipl-fig-btn${i === 0 ? " on" : ""}" data-fig="${escapeAttr(f.id)}">
       ${escapeHtml(f.label || `Fig.${f.number} ${f.title}`)}
     </button>`
  ).join("");
  $("ipl-figs").querySelectorAll(".ipl-fig-btn").forEach((b) =>
    b.addEventListener("click", () => showIplFigure(b.dataset.fig))
  );
  showIplFigure(ipl.model.figures[0].id);
  syncIplStageSize();
  return true;
}

function showIplFigure(id) {
  const fig = ipl.model.figures.find((f) => f.id === id);
  if (!fig) return;
  ipl.figure = fig;
  ipl.selectedKey = null;

  $("ipl-figs").querySelectorAll(".ipl-fig-btn").forEach((b) =>
    b.classList.toggle("on", b.dataset.fig === id)
  );

  const canvas = $("ipl-canvas");
  canvas.querySelectorAll(".ipl-spot").forEach((s) => s.remove());
  const img = $("ipl-img");
  // Size the stage once this drawing's own shape is known, and again on every
  // figure: the G3800 turns landscape for its carburetor sheet, so the room a
  // figure can fill is not settled until its image is there.
  img.onload = syncIplStageSize;
  img.src = `./ipl/${fig.image}`;
  if (img.complete) syncIplStageSize();

  // One hotspot per printed callout — a part shown twice on the drawing gets
  // two, both selecting the same row.
  fig.hotspots.forEach((h) => {
    const b = document.createElement("button");
    b.type = "button";
    b.className = "ipl-spot";
    b.dataset.key = h.key;
    b.style.left = h.x + "%";
    b.style.top = h.y + "%";
    b.setAttribute("aria-label", "Part " + h.key);
    b.addEventListener("click", () => selectIplKey(h.key, true));
    canvas.appendChild(b);
  });

  // Husqvarna Portal diagrams are flat images with the callout numbers baked
  // in, so those figures have no hotspots. Say so rather than inviting a tap
  // that cannot work.
  const hint = $("ipl-hint");
  if (hint) {
    // On the older books the drawing is a scan, so the numbers were read off
    // the picture rather than lifted from the file. Most are there; a few are
    // not, and it is fairer to say so than to leave someone tapping a number
    // that was never found.
    // A book with neither hotspots NOR a parts list is a set of page images -
    // the PulsFOG manuals are like this, their parts tables printed as pages of
    // their own. Telling someone to pick from a list that is not there reads as
    // a fault in the app.
    hint.textContent = !fig.hotspots.length && !(fig.parts || []).length
      ? "Pinch to zoom · drag to move · the parts tables are pages of their own in this book"
      : !fig.hotspots.length
      ? "Pinch to zoom · drag to move · pick a part from the list below"
      : fig.ocr
        ? "Pinch to zoom · tap a number · scanned drawing, a few numbers may not respond"
        : "Pinch to zoom · drag to move · tap a number";
  }

  $("ipl-filter").value = "";
  if (typeof iplReset === "function") iplReset();
  renderIplList();
}

function renderIplList() {
  const fig = ipl.figure;
  if (!fig) return;
  // The books nest sub-components two deep — a screen inside a pump cover
  // inside the carburetor assembly — so draw one bullet per level. depth is
  // newer than sub; fall back so a model extracted before it still indents.
  const iplIndent = (p) => {
    const d = p.depth != null ? p.depth : (p.sub ? 1 : 0);
    return d ? `<span class="sub">${"&middot; ".repeat(d)}</span>` : "";
  };
  const q = $("ipl-filter").value.trim().toLowerCase();
  const rows = fig.parts.filter((p) =>
    !q || p.description.toLowerCase().includes(q) ||
    p.part_number.toLowerCase().includes(q) ||
    p.search.toLowerCase().includes(q.replace(/[^a-z0-9]/g, "")) ||
    p.key.toLowerCase() === q
  );

  $("ipl-list").innerHTML = rows.length
    ? rows.map((p) => `
        <button type="button" class="ipl-row${p.key === ipl.selectedKey ? " on" : ""}" data-key="${escapeAttr(p.key)}" data-index="${fig.parts.indexOf(p)}">
          <span class="k">${escapeHtml(p.key)}</span>
          <span class="d">
            <span class="n">${iplIndent(p)}${escapeHtml(p.description)}</span>
            <span class="c mono">${escapeHtml(p.part_number)}${p.remarks ? " &middot; " + escapeHtml(p.remarks) : ""}</span>
          </span>
          <span class="q">${p.qty ? "&times;" + escapeHtml(p.qty) : ""}</span>
        </button>`).join("")
    : `<div class="ipl-empty">No parts match that.</div>`;

  $("ipl-list").querySelectorAll(".ipl-row").forEach((b) =>
    b.addEventListener("click", () => {
      selectIplKey(b.dataset.key, false);
      openIplPart(Number(b.dataset.index));
    })
  );
}

// Highlight a key on both the drawing and the list. fromDiagram scrolls the
// list to the row; tapping the row instead opens the part straight away.
function selectIplKey(key, fromDiagram) {
  ipl.selectedKey = key;
  document.querySelectorAll(".ipl-spot").forEach((s) =>
    s.classList.toggle("on", s.dataset.key === key)
  );
  document.querySelectorAll(".ipl-row").forEach((r) =>
    r.classList.toggle("on", r.dataset.key === key)
  );
  if (fromDiagram) {
    const row = document.querySelector('.ipl-row[data-key="' + CSS.escape(key) + '"]');
    if (row) row.scrollIntoView({ behavior: "smooth", block: "center" });
    // Husqvarna IPLs list variants under one callout — the same number with a
    // different article number per machine SKU or serial range. Only the list
    // shows what distinguishes them, so offer the choice rather than silently
    // opening the first and showing the wrong part number and price.
    const matches = ipl.figure.parts
      .map((p, i) => ({ p, i }))
      .filter((x) => x.p.key === key);
    if (matches.length === 1) openIplPart(matches[0].i);
    else if (matches.length > 1) {
      toast(`${matches.length} versions of ${key} — pick one from the list`, "ok");
    } else {
      // A number the drawing prints that its own parts table skips - Zenoah's
      // MD431 does this with 56 and 14. Tapping it used to do nothing, and
      // nothing is indistinguishable from a broken app. Better to say the book
      // is short a row than to leave someone tapping the same number twice.
      toast(`${key} is on the drawing but not listed in this book`, "err");
    }
  }
}

// The IPL gives the manufacturer's part number; AutoCount stores it with the
// brand prefix and no separators (IPL "585 60 19-01" is "SZEN 585601901").
// So resolve the real item code by search first, then ask for its stock —
// getPartStock matches the code exactly and would miss otherwise.
// Takes the part's index within the figure, not its callout number: several
// parts can share a number and differ only by article number.
let iplDiagramPart = null;      // the part as the BOOK lists it

async function openIplPart(index) {
  const part = ipl.figure.parts[index];
  if (!part) return;
  iplDiagramPart = part;

  $("ipl-part-title").textContent = part.description || part.part_number;
  $("ipl-part-sub").textContent =
    `${ipl.figure.label || `Fig.${ipl.figure.number} ${ipl.figure.title}`} · Key ${part.key}`;
  $("ipl-part-stock").innerHTML = `<div class="fp-loading">Looking up stock…</div>`;
  // Prices are per part and hidden until asked for, so reset the panel rather
  // than leaving the previous part's figures showing.
  //
  // The price stays UNBOUND until the exact AutoCount item is known. The number
  // printed on the diagram is not enough to identify one: "848BE058B2" matches
  // both SZEN 848BE058B2 and SZEN 848BE058B2R, which are different parts at
  // different prices. Binding happens below, once the item is resolved.
  iplPriceState = { code: null, itemCode: null };
  renderIplPriceButton(null);
  // Nothing to order until the diagram number resolves to an AutoCount item.
  iplOrderPart = null;
  $("ipl-order-more").style.display = "none";
  $("ipl-modal").style.display = "flex";
  document.body.style.overflow = "hidden";

  try {
    const data = await api(`/api/parts-search?q=${encodeURIComponent(part.search)}`);
    const list = data.results || [];
    if (!list.length) {
      $("ipl-part-stock").innerHTML =
        `<div class="fp-empty">Not found in AutoCount under this number.</div>`;
      // A part the catalogue does not hold is the one most likely to have been
      // replaced by something else, so this is where a note earns its keep.
      // It is keyed to the book's own number rather than an item code, since
      // there is no item code to key it to.
      await renderPartNote($("ipl-part-stock"), {
        item_code: iplNoteKey(part),
        note_key: iplNoteKey(part),
        resolved: false,
        description: part.description || part.part_number,
      }, () => openIplPart(index));
      return;
    }
    if (list.length > 1) {
      // More than one match — usually the plain code and an "R" variant. Let
      // the user pick rather than guessing which one they meant.
      $("ipl-part-stock").innerHTML = list.map((r) =>
        `<button type="button" class="company-option" data-code="${escapeAttr(r.item_code)}">
           <span class="fp-opt-desc">${escapeHtml(r.description)}</span>
           <span class="fp-opt-code mono">${escapeHtml(r.item_code)}</span>
         </button>`).join("");
      $("ipl-part-stock").querySelectorAll(".company-option").forEach((b) =>
        b.addEventListener("click", () => renderIplStock(b.dataset.code))
      );
      return;
    }
    renderIplStock(list[0].item_code);
  } catch (e) {
    $("ipl-part-stock").innerHTML =
      `<div class="fp-empty">${escapeHtml(e.message || "Lookup failed")}</div>`;
  }
}

// The part the IPL sheet is currently showing, once it is a real AutoCount
// item — which is the only thing a reorder request can name.
let iplOrderPart = null;

async function renderIplStock(itemCode) {
  const box = $("ipl-part-stock");
  box.innerHTML = `<div class="fp-loading">Looking up stock…</div>`;
  iplOrderPart = null;
  $("ipl-order-more").style.display = "none";
  // Stock and price must describe the same item. This is the single point where
  // the diagram number becomes a real AutoCount item, so bind the price here.
  iplPriceState = { code: itemCode, itemCode };
  renderIplPriceButton(itemCode);
  try {
    const p = await api(`/api/part-stock/${encodeURIComponent(itemCode)}`);
    const qty = Number(p.bal_qty);
    const qtyStr = Number.isInteger(qty) ? String(qty) : qty.toFixed(2);
    box.innerHTML = `
      <div class="fp-row"><span class="fp-lbl">Part No.</span><span class="fp-val mono">${escapeHtml(p.item_code)}</span></div>
      <div class="fp-row"><span class="fp-lbl">Description</span><span class="fp-val">${escapeHtml(p.description)}</span></div>
      ${fitsRowHtml(p)}
      ${shelfRowHtml(p)}
      <div class="fp-row"><span class="fp-lbl">Bal. Qty</span><span class="fp-val fp-qty ${qty > 0 ? "fp-qty-ok" : "fp-qty-zero"}">${qtyStr}${p.uom ? " " + escapeHtml(p.uom) : ""}</span></div>`;
    iplOrderPart = p;
    $("ipl-order-more").style.display = "block";
    wireShelfEdit(box, p, (shelf) => { p.shelf = shelf; renderIplStock(p.item_code); });
    wireFits(box);
    renderPartNote(box, {
      ...p,
      note_key: iplDiagramPart ? iplNoteKey(iplDiagramPart) : null,
      resolved: true,
    }, () => renderIplStock(p.item_code));
  } catch (e) {
    box.innerHTML = `<div class="fp-empty">${escapeHtml(e.message || "Stock lookup failed")}</div>`;
  }
}

$("ipl-order-more").addEventListener("click", () => openOrderModal(iplOrderPart));
$("push-toggle").addEventListener("click", () => togglePush("quote"));
$("push-toggle-tech").addEventListener("click", () => togglePush("tech"));

function closeIplPart() {
  $("ipl-modal").style.display = "none";
  document.body.style.overflow = "";
}
$("ipl-part-close").addEventListener("click", closeIplPart);
$("ipl-modal").addEventListener("click", (e) => { if (e.target === $("ipl-modal")) closeIplPart(); });
$("ipl-search").addEventListener("input", (e) => {
  ipl.q = e.target.value;
  // Re-rendering replaces the chips and rows around it, not the input itself,
  // so the caret and the keyboard both stay put.
  renderIplPicker();
});
$("ipl-search-clear").addEventListener("click", () => {
  ipl.q = "";
  $("ipl-search").value = "";
  renderIplPicker();
  $("ipl-search").focus();
});
$("ipl-change").addEventListener("click", () => {
  showIplPicker();
  window.scrollTo({ top: 0 });
});
$("ipl-filter").addEventListener("input", renderIplList);

// ---- Diagram pinch / pan ----------------------------------------------------
// The stage clips, and the drawing is moved with a transform rather than by
// scrolling, so pinch and drag can share one gesture model.
//
// Two details worth keeping:
//  * The hotspots live inside the transformed canvas, so they would grow with
//    the zoom. They are counter-scaled through the --k variable, staying a
//    constant tap size at any magnification.
//  * A drag that ends on a hotspot must not also select it, so any gesture
//    that travels beyond a few pixels suppresses the click that follows.
const iplView = { k: 1, tx: 0, ty: 0, moved: false };
const IPL_MAX = 6;

function iplApply() {
  const c = $("ipl-canvas");
  if (!c) return;
  // Keep the drawing anchored: never let it be dragged clear of the stage.
  const stage = $("ipl-stage");
  const w = stage.clientWidth, h = stage.clientHeight;
  const maxX = 0, maxY = 0;
  // Measure the canvas rather than assuming it fills the stage. On a tablet the
  // stage is capped to the drawing's own shape, so the two can differ, and
  // using the stage's width as the canvas's would have let the drawing be
  // dragged clear of its own frame.
  const minX = Math.min(0, w - c.offsetWidth * iplView.k);
  const minY = Math.min(0, h - c.offsetHeight * iplView.k);
  iplView.tx = Math.max(minX, Math.min(maxX, iplView.tx));
  iplView.ty = Math.max(minY, Math.min(maxY, iplView.ty));

  c.style.setProperty("--k", iplView.k);
  c.style.transform = `translate(${iplView.tx}px, ${iplView.ty}px) scale(${iplView.k})`;
  stage.style.touchAction = iplView.k > 1.01 ? "none" : "pan-y";
  const reset = $("ipl-reset");
  if (reset) reset.style.display = iplView.k > 1.01 ? "inline-flex" : "none";
}

function iplReset() {
  iplView.k = 1; iplView.tx = 0; iplView.ty = 0;
  iplApply();
}

// Zoom about a point so the spot under the fingers stays put.
function iplZoomAt(x, y, factor) {
  const next = Math.max(1, Math.min(IPL_MAX, iplView.k * factor));
  const ratio = next / iplView.k;
  iplView.tx = x - (x - iplView.tx) * ratio;
  iplView.ty = y - (y - iplView.ty) * ratio;
  iplView.k = next;
  iplApply();
}

(function wireIplGestures() {
  const stage = $("ipl-stage");
  if (!stage) return;
  const pts = new Map();
  let startDist = 0, startK = 1, lastMid = null, lastOne = null;

  const mid = (a, b) => ({ x: (a.x + b.x) / 2, y: (a.y + b.y) / 2 });
  const dist = (a, b) => Math.hypot(a.x - b.x, a.y - b.y);
  const local = (e) => {
    const r = stage.getBoundingClientRect();
    return { x: e.clientX - r.left, y: e.clientY - r.top };
  };

  stage.addEventListener("pointerdown", (e) => {
    pts.set(e.pointerId, local(e));
    iplView.moved = false;
    if (pts.size === 2) {
      const [a, b] = [...pts.values()];
      startDist = dist(a, b);
      startK = iplView.k;
      lastMid = mid(a, b);
    } else if (pts.size === 1) {
      lastOne = local(e);
    }
    // Capture can throw if the pointer has already gone (a finger lifted
    // mid-gesture, or a synthetic event); losing capture is survivable, an
    // exception here would abort the gesture entirely.
    try { stage.setPointerCapture(e.pointerId); } catch (_) {}
  });

  stage.addEventListener("pointermove", (e) => {
    if (!pts.has(e.pointerId)) return;
    pts.set(e.pointerId, local(e));

    if (pts.size >= 2) {
      const [a, b] = [...pts.values()];
      const d = dist(a, b);
      if (startDist > 0) {
        const m = mid(a, b);
        const next = Math.max(1, Math.min(IPL_MAX, startK * (d / startDist)));
        const ratio = next / iplView.k;
        // Scale about the pinch centre, then follow it as the fingers travel.
        iplView.tx = m.x - (m.x - iplView.tx) * ratio + (lastMid ? m.x - lastMid.x : 0);
        iplView.ty = m.y - (m.y - iplView.ty) * ratio + (lastMid ? m.y - lastMid.y : 0);
        iplView.k = next;
        lastMid = m;
        iplView.moved = true;
        iplApply();
      }
      e.preventDefault();
    } else if (pts.size === 1 && iplView.k > 1.01) {
      const p = local(e);
      if (lastOne) {
        iplView.tx += p.x - lastOne.x;
        iplView.ty += p.y - lastOne.y;
        if (Math.abs(p.x - lastOne.x) > 2 || Math.abs(p.y - lastOne.y) > 2) iplView.moved = true;
        iplApply();
      }
      lastOne = p;
      e.preventDefault();
    }
  });

  const release = (e) => {
    pts.delete(e.pointerId);
    if (pts.size < 2) { startDist = 0; lastMid = null; }
    if (pts.size === 1) lastOne = [...pts.values()][0];
    if (pts.size === 0) lastOne = null;
  };
  stage.addEventListener("pointerup", release);
  stage.addEventListener("pointercancel", release);

  // A pan or pinch must not select whatever it finished on top of.
  stage.addEventListener("click", (e) => {
    if (iplView.moved) { e.stopPropagation(); e.preventDefault(); iplView.moved = false; }
  }, true);

  // Desktop: wheel to zoom, double-click to toggle.
  stage.addEventListener("wheel", (e) => {
    e.preventDefault();
    const p = local(e);
    iplZoomAt(p.x, p.y, e.deltaY < 0 ? 1.12 : 1 / 1.12);
  }, { passive: false });

  stage.addEventListener("dblclick", (e) => {
    const p = local(e);
    if (iplView.k > 1.01) iplReset();
    else iplZoomAt(p.x, p.y, 2.5);
  });

  const reset = $("ipl-reset");
  if (reset) reset.addEventListener("click", iplReset);
  window.addEventListener("resize", iplApply);
})();

// ---- Part prices (IPL viewer) -----------------------------------------------
// Read-only from AutoCount, which holds the tiers on the item's base-UOM row:
// Price1 is the Contractor Price and Price6 the List Price. Prices stay hidden
// until "Check Price" is tapped.
//
// A price that AutoCount does not have yet can be filled in from here, because
// a blank price is the one case where there is nothing to overwrite. A price
// that already exists is never editable from the app — that stays AutoCount's
// to own. Sales and Purchaser only, initials required, and the write is
// confirmed before it happens because it lands in the accounting system.
const IPL_TIERS = [
  { field: "list_price",       code: "LP", name: "List Price",       tier: "list" },
  { field: "contractor_price", code: "CP", name: "Contractor Price", tier: "contractor" },
];

let iplPriceState = { code: "" };

// Who may fill in a missing price. Technicians deliberately cannot: they see
// prices on the slip screens, but these values feed customer quotes.
const CAN_SET_PRICE = ["sales", "purchaser", "admin"];

// box is passed in because two cards render this now - the IPL part sheet and
// the Find Part stock card. Only one is ever on screen at a time, which is why
// the price state below can stay a single value.
function renderIplPriceButton(itemCode, box = $("ipl-part-price")) {
  if (!itemCode) {
    // More than one AutoCount item can carry the same diagram number, so there
    // is nothing honest to show a price for until one has been picked above.
    box.innerHTML = `<div class="ipl-price-wait">Choose the part above to see its price.</div>`;
    return;
  }
  box.innerHTML =
    `<button type="button" class="ipl-price-btn" id="ipl-check-price">Check Price</button>`;
  box.querySelector("#ipl-check-price").addEventListener("click", () => loadIplPrices(box));
}

async function loadIplPrices(box = $("ipl-part-price")) {
  box.innerHTML = `<div class="fp-loading">Checking price…</div>`;
  try {
    const p = await api(`/api/part-prices/${encodeURIComponent(iplPriceState.code)}`);
    let html = `<div class="ipl-price-for mono">${escapeHtml(p.item_code)}</div>`;
    html += `<div class="ipl-prices">`;
    for (const t of IPL_TIERS) {
      const v = p[t.field];
      // AutoCount leaves an unset price as NULL or as a plain zero, and both
      // mean the same thing to a person looking at the screen.
      const missing = v === null || v === undefined || Number(v) === 0;
      const canSet = missing && CAN_SET_PRICE.includes(getRole());
      html += `
        <div class="ipl-price-row" data-tier="${t.tier}">
          <span class="lbl"><b>${t.code}</b>${t.name}</span>
          <span class="val${missing ? " none" : ""}">${missing ? "Not set" : money(v)}</span>
          ${canSet ? `<button type="button" class="ipl-setprice" data-tier="${t.tier}" data-name="${escapeHtml(t.name)}">Set price</button>` : ""}
        </div>`;
    }
    html += `</div>`;
    // The resolved AutoCount code, not the number printed on the diagram. Any
    // write must target the exact item whose price was just shown.
    iplPriceState.itemCode = p.item_code;
    box.innerHTML = html;
    box.querySelectorAll(".ipl-setprice").forEach((b) =>
      b.addEventListener("click", () => openSetPrice(b.dataset.tier, b.dataset.name))
    );
  } catch (e) {
    box.innerHTML = `<div class="fp-empty">${escapeHtml(e.message || "Couldn't load prices")}</div>`;
  }
}

// Fill in a price AutoCount does not have. Two deliberate steps: the value is
// typed into a small form, and then confirmed against the item code and tier
// spelled out in full, because this writes to the accounting database and the
// app cannot undo it afterwards.
function openSetPrice(tier, tierName) {
  const row = document.querySelector(`.ipl-price-row[data-tier="${tier}"]`);
  if (!row || row.querySelector(".ipl-setform")) return;
  row.querySelector(".ipl-setprice").style.display = "none";

  // No "your initials" box any more - the app knows who is signed in, and a
  // typed-in name on an audit trail is only as good as whoever typed it.
  const form = document.createElement("div");
  form.className = "ipl-setform";
  form.innerHTML = `
    <div class="ipl-setform-item">${escapeHtml(iplPriceState.itemCode || iplPriceState.code)}</div>
    <div class="ipl-setform-fields">
      <label>${escapeHtml(tierName)}
        <input type="number" class="sp-price" inputmode="decimal" step="0.01" min="0.01" placeholder="0.00">
      </label>
    </div>
    <div class="ipl-setform-by">Recorded against ${escapeHtml(userName() || "an unknown user")}</div>
    <div class="ipl-setform-actions">
      <button type="button" class="sp-cancel">Cancel</button>
      <button type="button" class="sp-save">Save to AutoCount</button>
    </div>
    <div class="ipl-setform-note">Writes into AutoCount. It cannot be changed back from this app.</div>`;
  row.appendChild(form);
  const price = form.querySelector(".sp-price");
  price.focus();

  form.querySelector(".sp-cancel").addEventListener("click", () => {
    form.remove();
    const b = row.querySelector(".ipl-setprice");
    if (b) b.style.display = "";
  });

  form.querySelector(".sp-save").addEventListener("click", async () => {
    const value = Number(price.value);
    if (!Number.isFinite(value) || value <= 0) { toast("Enter a price greater than zero.", "err"); price.focus(); return; }
    const initials = userName();
    if (!initials) { toast("Pick your name on the first screen before setting a price.", "err"); return; }

    const item = iplPriceState.itemCode || iplPriceState.code;
    const ok = confirm(
      `Set the ${tierName} for ${item} to ${money(value)} in AutoCount?

` +
      `This writes to AutoCount and cannot be undone from this app.`
    );
    if (!ok) return;

    const btn = form.querySelector(".sp-save");
    btn.disabled = true; btn.textContent = "Saving…";
    try {
      const r = await api("/api/part-prices", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          item_code: item, tier, price: value, who: initials, role: getRole(),
        }),
      });
      toast(r.message || "Price saved.", "ok");
      loadIplPrices();
    } catch (e) {
      toast(e.message || "Could not save the price.", "err");
      btn.disabled = false; btn.textContent = "Save to AutoCount";
    }
  });
}

// On a tablet the diagram should be as large as the screen allows, and never
// cropped to get there.
//
// The stage is a plain block whose canvas fills its width, so the drawing's
// height follows from the width it is given. Work backwards: measure the room
// left below the figure tabs, then set a width that puts the height just inside
// it. The shape comes from the figure itself, because it varies — the G3800
// prints its carburetor sheet landscape while every other page is portrait, and
// a single assumed aspect would crop one or waste the screen on the other.
function syncIplStageSize() {
  const viewer = $("ipl-viewer");
  const stage = $("ipl-stage");
  const img = $("ipl-img");
  if (!viewer || !stage || !img) return;

  // Phones keep the layout they have; this is a tablet-and-up affordance.
  if (!window.matchMedia("(min-width: 700px)").matches || viewer.style.display === "none") {
    stage.style.removeProperty("max-width");
    return;
  }
  const aspect = img.naturalWidth && img.naturalHeight
    ? img.naturalWidth / img.naturalHeight
    : 0;
  if (!aspect) return;   // called before the drawing loaded; onload calls again

  // A share of the screen, not what happens to be left below the figure tabs.
  // Measuring the leftover was the obvious way and gave a drawing no bigger
  // than a phone's: fifteen wrapped tabs push the stage 680px down a 1180px
  // screen, leaving it the scraps. The page may scroll to show the parts list —
  // it does on a phone too — so the drawing is not owed a place above the fold.
  const full = viewer.clientWidth;
  stage.style.maxWidth =
    Math.round(Math.min(full, window.innerHeight * 0.78 * aspect)) + "px";
}

// The IPL picker's brand headings pin themselves below the topbar, which needs
// its height as a number. Measured rather than hard-coded: the bar is taller
// for technicians, who get a language toggle in it.
function syncTopbarHeight() {
  const bar = document.querySelector(".topbar");
  if (bar && bar.offsetHeight) {
    document.documentElement.style.setProperty("--topbar-h", bar.offsetHeight + "px");
  }
}
syncTopbarHeight();
window.addEventListener("resize", () => { syncTopbarHeight(); syncIplStageSize(); });
window.addEventListener("orientationchange", () => { syncTopbarHeight(); syncIplStageSize(); });
